css:
.widget-container {
  font-size: 18px;
  max-width: min(750px, 100%);
  margin-left: auto;
  margin-right: auto;
  line-height: 1.35;
  box-sizing: border-box;
  color: #434343;
}

.widget-container img {
  width: 100%;
  height: auto;
  display: block;
  margin: 0;
}

.widget-container>* {
  box-sizing: border-box;
}

@media (max-width: 500px) {
  .widget-container {
    font-size: 3.3vw;
  }
}

.widget-wrapper>*+* {
  margin-top: 2.85em;
}

.widget-item>*+* {
  margin-top: 1.5em;
}

.widget-item.is-hidden {
  display: none !important;
}

.widget-item-header {
  margin: 0;
}

.widget-item-header img {
  margin-top: 1em;
}

.widget-item-number {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 2.5em;
  margin-bottom: 1.5em;
}

.widget-item-number span {
  width: 2.5em;
  aspect-ratio: 1/1;
  border-radius: 50%;
  background-color: #e2d0b2;
  color: #fff;
  display: grid;
  place-items: center;
  line-height: 1;
  font-size: 1.1em;
  font-weight: 600;
  position: relative;
}

.widget-item-number span:not(:last-child)::after {
  content: "→";
  position: absolute;
  color: #343434;
  font-weight: 900;
  top: 50%;
  translate: 0 -50%;
  right: -1.5em;
}

.widget-item-number span.current {
  background-color: #9c7745;
}

.widget-item-title {
  font-size: 1.5em;
  font-weight: 600;
  margin: 0.75em 0 0;
  text-align: center;
}

.widget-item-radiobox,
.widget-item-checkbox {
  display: grid;
  gap: 0.85em;
}

.widget-item-radiobox .radiobox-item,
.widget-item-checkbox .radiobox-item,
.widget-item-radiobox .checkbox-item,
.widget-item-checkbox .checkbox-item {
  margin: 0;
}

.widget-item-radiobox .radiobox-item input,
.widget-item-checkbox .radiobox-item input,
.widget-item-radiobox .checkbox-item input,
.widget-item-checkbox .checkbox-item input {
  display: none;
}

.widget-item-radiobox .radiobox-item input+label,
.widget-item-checkbox .radiobox-item input+label,
.widget-item-radiobox .checkbox-item input+label,
.widget-item-checkbox .checkbox-item input+label {
  display: block;
  text-align: center;
  background-color: #f6dbdf;
  padding: 1em;
  cursor: pointer;
  border: 2px solid #e1e1e1;
  box-shadow: 0 4px 30px rgba(222, 222, 222, 0.46);
  border-radius: 0.5em;
  font-size: 1.1em;
  transition: 0.25s;
}

.widget-item-radiobox .radiobox-item input:checked+label,
.widget-item-checkbox .radiobox-item input:checked+label,
.widget-item-radiobox .checkbox-item input:checked+label,
.widget-item-checkbox .checkbox-item input:checked+label {
  background-color: #d45566;
  border: 2px solid #d45566;
  box-shadow: 0 4px 0 #cd394e;
  color: #fff;
}

.widget-item-footer {
  margin-bottom: 0;
}

.widget-item-button {
  cursor: pointer;
  display: block;
  width: fit-content;
  margin: auto;
  background-color: #9c7745;
  background-image: linear-gradient(0deg, #9c7745 55%, #e2d0b2);
  font-weight: 600;
  padding: 0.75em 2.5em 0.75em 3.1em;
  border-radius: 99px;
  transition: 0.25s;
}

.widget-item-button.is-hidden {
  display: none !important;
}

.widget-item-button button {
  font-size: 1.3em;
  font-weight: 600;
  color: #fff;
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 0.5em;
  cursor: pointer;
  margin: 0;
  padding: 0 !important;
}

.widget-item-button button::after {
  content: "";
  width: 1.2em;
  aspect-ratio: 1/1;
  display: block;
  background-color: #fff;
  border-radius: 50%;
  line-height: 1;
}

.widget-item-button button::before {
  content: "";
  width: 0.45em;
  height: 0.5em;
  display: block;
  background-color: #9c7745;
  line-height: 1;
  clip-path: polygon(0 0, 0% 100%, 100% 50%);
  position: absolute;
  right: calc(0.6em / 2);
}

.widget-item-button.lg {
  min-width: 100%;
  box-sizing: border-box;
  display: grid;
  place-items: center;
}

.widget-item-button.lg button {
  padding-top: 0.5em !important;
  padding-bottom: 0.5em !important;
  font-size: 1.8em;
}

.widget-item-result {
  text-align: center;
}

.widget-item-result .text {
  margin: 1em 0 0;
  font-size: 1em;
}

.widget-item-result .link {
  display: inline-block;
  margin: 1em 0 0;
  color: #9c7745;
  font-weight: 600;
  text-decoration: underline;
}

button {
  outline: none;
  border: none;
  background-color: transparent;
}

 .questionLink {
  width: 100%;
  height: auto;
  font-size: min(16px, 3vw);
}

 .questionLink .head,
 .questionLink .link {
  width: 100%;
  height: auto;
}

 .questionLink .progress {
  width: 90%;
  height: auto;
  margin: 0 auto;
  display: flex;
  justify-content: center;
  align-items: center;
  column-gap: 2em;
}

 .questionLink .progress .progress__item {
  width: 3em;
  height: 3em !important;
  background: transparent;
  border-radius: 1.5em;
  display: flex;
  justify-content: center;
  align-items: center;
  color: #999;
  font-size: 1em;
  font-weight: bold;
  position: relative;
}

 .questionLink .progress .progress__item:before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 1.5em;
  background: #eee;
  z-index: 1;
}

 .questionLink .progress .progress__item span {
  position: relative;
  z-index: 2;
}

 .questionLink .progress .progress__item.is-active {
  color: #fff;
}

 .questionLink .progress .progress__item.is-active:before {
  background: #524646;
}

 .questionLink .progress .progress__item:after {
  content: '';
  width: 5em;
  height: auto;
  display: block;
  border-top: 2px solid #eee;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 0;
}

 .questionLink .progress .progress__item:first-of-type:after {
  width: 3em;
  transform: translate(0, -50%);
}

 .questionLink .progress .progress__item:last-of-type:after {
  width: 3em;
  left: initial;
  right: 50%;
  transform: translate(0, -50%);
}

 .questionLink .head .head__num {
  margin: 1em auto 0;
  width: 2.5em;
  height: 2.5em !important;
  border-radius: 2.5em;
  background: #524646;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 2em;
  font-weight: bold;
  color: #fff;
}

 .questionLink .head .head__text {
  font-size: 1.2em;
  text-align: center;
  margin-top: 1em;
}

 .questionLink .kome {
  font-size: 0.6em;
  vertical-align: bottom;
}

 .questionLink .note {
  text-align: right;
  font-size: 0.9em;
}

 .questionLink .image {
  margin-top: 1em;
}

 .questionLink .image img,
 .questionLink .image video {
  width: 100%;
  height: auto;
  vertical-align: bottom;
  margin-top: 0em;
  margin-bottom: 0;
}

 .questionLink .link,
 .questionLink .select {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  margin-top: 2em;
}

 .questionLink .select input {
  display: none;
}

 .questionLink .select__button,
 .questionLink .link__button {
  width: 100%;
  height: auto;
  border: 2px solid #EC5B38;
  border-bottom-width: 5px;
  border-radius: 5px;
  box-sizing: border-box;
  padding: 1em 0.5em 1em 2.5em;
  text-decoration: none;
  color: #EC5B38;
  font-size: 1em;
  font-weight: bold;
  position: relative;
  cursor: pointer;
  transition: background 0.2s, color 0.2s;
}

 .questionLink .select .select__button+input+.select__button {
  margin-top: 0.5em;
}

 .questionLink .select__button:before {
  content: '';
  width: 1em;
  height: 1em;
  display: block;
  position: absolute;
  top: 50%;
  left: 0.8em;
  border: 1px solid #EC5B38;
  border-radius: 3px;
  transform: translateY(-50%);
}

 .questionLink input:checked+.select__button {
  background: #EC5B38;
  color: #fff;
}

 .questionLink input:checked+.select__button:before {
  background: #FCF2E5;
}

 .questionLink input:checked+.select__button:after {
  content: '';
  width: 0.7em;
  height: 0.2em;
  border-width: 0 0 2px 2px;
  border-color: #EC5B38;
  border-style: solid;
  position: absolute;
  top: 49%;
  left: 0.95em;
  transform: translateY(-50%) rotate(-45deg);
}

 .questionLink .noteItems {
  list-style: none;
  text-align: left;
  font-size: 0.8em;
  color: #333;
  padding-left: 0;
}

 .questionLink .link__button.link__button--next,
 .questionLink .link__button.link__button--back {
  width: 90%;
  height: auto;
  background: #aaa;
  border-color: #aaa;
  border-bottom-color: #666;
  color: #fff;
  text-align: center;
  padding-left: 0.5em;
}

 .questionLink .link__button.link__button--next {
  background: #FCF2E5;
  border-color: #EC5B38;
  color: #EC5B38;
}

 .questionLink .link__button.link__button--next.is-disabled {
  background: #eee;
  color: #aaa;
  border-color: #aaa;
}

 .questionLink .link__button.link__button--back {
  margin-top: 1em;
  opacity: 1;
  transition: opacity 0.2s;
}

 .questionLink .link__button.link__button--back:hover {
  opacity: 0.8;
}

