  text-decoration: none;
  color: #EC5B38;
  font-size: 1em;
  font-weight: bold;
  position: relative;
  cursor: pointer;
  pointer-events: none;
  transition: background 0.2s, color 0.2s;
}

.questionLink .link .link__button+.link__button {
  margin-top: 0.5em;
}

.questionLink .link .link__button:before {
  content: '';
  width: 1em;
  height: 1em;
  display: block;
  position: absolute;
  top: 50%;
  left: 0.8em;
  border: 1px solid #EC5B38;
  border-radius: 3px;
  transform: translateY(-50%);
}

.questionLink .link .link__button.is-ready {
  pointer-events: auto;
}

.questionLink .link .link__button.is-disabled {
  pointer-events: none;
  opacity: 0.6;
}

.questionLink .link .link__button.is-active {
  background: #EC5B38;
  color: #fff;
}

.questionLink .link .link__button.is-active:before {
  background: #FCF2E5;
}

.questionLink .link .link__button.is-active:after {
  content: '';
  width: 0.7em;
