  background: #aaa;
  border-color: #aaa;
  border-bottom-color: #666;
  color: #fff;
  text-align: center;
  padding-left: 0.5em;
  margin-top: 1em;
  opacity: 1;
  transition: opacity 0.2s;
  pointer-events: auto;
}

.questionLink .link__button.link__button--back:hover {
  opacity: 0.8;
}

.questionLink .link__button.link__button--back:before {
  content: none;
}

.questionCurtain {
  width: 100%;
  height: auto;
  font-size: min(3vw, 16px);
}

.questionCurtain p {
  margin: 0;
}

.questionCurtain img,
.questionCurtain video {
  width: 100%;
  height: auto;
  vertical-align: bottom;
}

.questionCurtain__header,
.questionCurtain__kv {
  width: 100%;
  height: auto;
}

.questionCurtain__kv img {
  width: 100%;
  height: auto;
}

.questionCurtain__step {
  width: 100%;
  height: auto;
  margin: 0 auto;
  padding-top: 4em;
  display: flex;
  justify-content: center;
  align-items: flex-end;
  gap: 0;
}

.step {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}

.step__body {
  width: 100%;
  height: 4em;
  background-color: #dbdbdb;
  display: flex;
  align-items: center;
  justify-content: center;
  padding-right: 1em;
  box-sizing: border-box;
  clip-path: polygon(0% 0%, 85% 0%, 100% 50%, 85% 100%, 0% 100%);
}

.questionCurtain__step .step:first-child .step__body {
  padding-left: 0;
}

.step.is-active .step__body {
  background-color: #FA6781;
}

.step.is-active:before {
  content: '';
  width: 86%;
  height: auto;
  display: block;
  background-image: url('/uploads/b2a43120a9b3ac8e0801d4e9ae6c5efa881a7761649f09dc97fdcfb7457d78f1.png');
  aspect-ratio: 800/533;
  background-size: 100%;
  position: absolute;
  top: -5em;
  left: 0;
}

@media screen and (max-width: 600px) {
  .step.is-active:before {
    top: -4em;
  }
}

.step.step-result.is-active:before {
  content: none;
}

.step__number {
  font-size: 1.5em;
  font-weight: normal;
  color: #707070;
  transition: color 0.3s ease;
}

.step.is-active .step__number {
  color: #ffffff;
}

.step-result {
  align-self: flex-end;
}

.step-result .step__body {
  background: transparent;
  clip-path: none;
  padding-right: 0;
  height: auto;
}

.step-result .step__body picture,
.step-result .step__body img {
  display: block;
  width: 100%;
  height: auto;
  max-height: 8em;
  object-fit: contain;
}

.questionCurtain__main {
  width: 100%;
  height: auto;
  margin-top: 2em;
}

.questionCurtain__items {
  padding: 1em 0;
  display: none;
  opacity: 0;
}

.questionCurtain__items.is-active {
  display: block;
  opacity: 1;
  animation: fadeinQuestion 0.5s 1 forwards;
}

@keyframes fadeinQuestion {
  0% {
    opacity: 0;
  }

  100% {
    opacity: 1;
  }
}

.questionCurtain__items-title .title {
  font-size: 1.4em;
  font-weight: bold;
  text-align: center;
}

.questionCurtain__items-title .title .line {
  padding: 0 0.05em;
  display: inline-block;
  background: linear-gradient(to bottom, transparent 0%, transparent 60%, #FFC94D 61%, #FFC94D 90%, transparent 91%);
}

.questionCurtain__items-img {
  margin-top: 2em;
}

.questionCurtain__btns {
  margin-top: 2em;
  width: 100%;
  height: auto;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  flex-wrap: wrap;
  column-gap: 1em;
  row-gap: 1em;
}

.questionCurtain__btns input {
  display: none;
}

.questionCurtain__btns label {
  width: calc(50% - 4.5em);
  height: auto;
  background: #59B292;
  border-radius: 3px;
  border-bottom: 3px solid #346956;
  padding: 1em 1em 1em 2.5em;
  color: #fff;
  font-size: 1.2em;
  font-weight: bold;
  position: relative;
  top: 0px;
  transition: border-botoom 0.2s, top 0.2s;
  cursor: pointer;
}

.questionCurtain__btns input:hover+label,
.questionCurtain__btns input:checked+label {
  border-bottom: 0;
  top: 3px;
  transition: border-botoom 0.2s, top 0.2s;
  margin-top: 3px;
}

.questionCurtain__btns label:before {
  content: '';
  position: absolute;
  top: 50%;
  left: 0.8em;
  transform: translateY(-50%);
  width: 0.8em;
  height: 0.8em;
  display: block;
  border: 1px solid #fff;
  transition: background 0.2s;
}

.questionCurtain__btns input:hover+label:before,
.questionCurtain__btns input:checked+label:before {
  background: #fff;
  transition: background 0.2s;
}

.questionCurtain__btns input:hover+label:after,
.questionCurtain__btns input:checked+label:after {
  content: '';
  position: absolute;
  top: 47%;
  left: 1.1em;
  width: 0.7em;
  height: 0.3em;
  display: block;
  transform: rotate(-45deg) translateY(-50%);
  border-bottom: 3px solid #59B292;
  border-left: 3px solid #59B292;
}

.questionCurtain__btns label picture {
  display: block;
  margin-top: 0.5em;
}

.questionCurtain__btns label:before {
  top: 1.8em;
}

.questionCurtain__btns input:hover+label:after,
.questionCurtain__btns input:checked+label:after {
  top: 1.7em;
}

.questionCurtain__btns label.img {
  padding: 1em;
  width: calc(48% - 2em);
}

.questionCurtain__btns label .img-label {
  padding-left: 1.5em;
}

.questionCurtain__items-msg {
  margin-top: 2em;
  font-size: 0.9em;
  color: #666;
}

.questionCurtain__items-msg .text-right {
  text-align: right;
}

.questionCurtain__items-msg .text-left {
  text-align: left;
}

.fadein__area {
  transform: translateY(40px);
  opacity: 0;
  display: none;
}

.fadein__area+.fadein__area {
  margin-top: 4em;
}

.question__area {
  width: 100%;
  height: auto;
  margin: 4em auto 0;
  padding-bottom: 2em;
  display: block;
  font-size: min(16px, 3vw);
}

.question__head__area {
  width: 96%;
  height: auto;
  margin: 0 auto;
  display: block;
  position: relative;
}

.question__head__inner {
  width: 100%;
  height: auto;
  background: #fff;
  padding: 3em;
  box-sizing: border-box;
  border-radius: 10px;
  z-index: 1;
}

.question__head__area:after {
  content: '';
  width: 100%;
  height: 100%;
  display: block;
  background-image: linear-gradient(-20deg, #ddd6f3 0%, #faaca8 100%, #faaca8 100%);
  filter: blur(5px);
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  z-index: -1;
}

.question__num__area {
  width: 4em;
  height: 4em !important;
  border-radius: 2em;
  position: absolute;
  top: -1em;
  left: 1em;
  background-image: linear-gradient(-20deg, #ffc3a0 0%, #ffafbd 100%);
  display: flex;
  justify-content: center;
  align-items: center;
}

.question__num__area .num {
  font-size: 2em;
  color: #fff;
  text-align: center;
  margin: 0;
  font-weight: bold;
}

