}

.questionCheckRotate--select__box label .selectFlont__item {
  transform: rotateY(0);
  position: relative;
  top: 0;
  left: 0;
  z-index: 2;
}

.questionCheckRotate--select__box label .selectBack__item {
  transform: rotateY(180deg);
  position: absolute;
  top: 0;
  left: 0;
  z-index: 1;
}

.questionCheckRotate--select__box label .selectFlont__item,
.questionCheckRotate--select__box label .selectBack__item {
  transition: opacity 0.2s ease;
  backface-visibility: hidden;
}

.questionCheckRotate--select__box label .selectFlont__item {
  opacity: 1;
  transform: rotateY(0deg);
  z-index: 2;
  position: relative;
}

.questionCheckRotate--select__box label .selectBack__item {
  opacity: 0;
  transform: rotateY(180deg);
  z-index: 1;
  position: absolute;
  top: 0;
  left: 0;
}

.questionCheckRotate--select__box input:checked+label .selectFlont__item {
  opacity: 0;
  transition-delay: 0.1s;
}

.questionCheckRotate--select__box input:checked+label .selectBack__item {
  opacity: 1;
  transition-delay: 0.1s;
}

.questionCheckRotate--select__box input:not(:checked)+label {
  transform: rotateY(0deg);
}

.questionCheckRotate--select__box input:not(:checked)+label .selectBack__item {
  opacity: 0;
  transition-delay: 0.0s;
}

.questionCheckRotate--select__box input:not(:checked)+label .selectFlont__item {
