 [data-step="3"] .button {
  width: calc(90% / var(--col));
  aspect-ratio: 277/104;
}

 [data-step="2"] .button.button01,
 [data-step="3"] .button.button01 {
  left: calc(5% - 2px);
  bottom: calc(25.5% - 2px);
}

 [data-step="2"] .button.button02,
 [data-step="3"] .button.button02 {
  right: calc(5% - 2px);
  bottom: calc(25.5% - 2px);
}

 [data-step="2"] .button.button03,
 [data-step="3"] .button.button03 {
  left: calc(5% - 2px);
  bottom: calc(15.5% - 5px);
}

 [data-step="2"] .button.button04,
 [data-step="3"] .button.button04 {
  right: calc(5% - 2px);
  bottom: calc(15.5% - 5px);
}

 [data-step="5"] .button {
  width: calc(90% / var(--col));
  aspect-ratio: 279/47;
}

 [data-step="5"] .button.button01 {
  top: calc(30.5% - 2px);
  left: calc(5% - 2px);
}

 [data-step="5"] .button.button02 {
  top: calc(40.5% - 5px);
  left: calc(5% - 2px);
}

 [data-step="5"] .button.button03 {
  top: calc(50.5% - 10px);
  left: calc(5% - 2px);
}

 [data-step="5"] .button.button04 {
  top: calc(60.5% - 15px);
  left: calc(5% - 2px);
}

 [data-step="6"] .button {
  width: calc(90% / var(--col));
  aspect-ratio: 556/135;
  bottom: calc(23.5% - 10px);
  left: calc(5% - 2px);
}

 [data-step="6"] .button::before {
  border-radius: 99px;
