@keyframes fadeIn {
  from {
    display: none;
    opacity: 0;
  }

  10% {
    display: block;
    opacity: 0;
  }

  100% {
    display: block;
    opacity: 1;
  }
}

@keyframes fadeOut {
  from {
    display: block;
    opacity: 1;
  }

  90% {
    display: block;
    opacity: 0;
  }

  100% {
    display: none;
    opacity: 0;
  }
}

@keyframes spin {
  from {
    transform: rotate(0deg);
