}

.fixed-cta-btn:not(:has(img)) .fixed-cta-btn-link.bound {
  animation: bound-btn 1s steps(1) infinite;
}

.progress {
  width: 90%;
  height: 4px;
  position: absolute;
  top: 1.5em;
  left: 5%;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
  gap: 10px;
}

.progress-item {
  background-color: #fff;
  height: 100%;
  width: calc(100% / var(--slide-count));
  position: relative;
  overflow: hidden;
}

.progress-item::before {
  content: '';
  display: block;
  width: 0;
  height: 100%;
  background-color: #0286ff;
  position: absolute;
  top: 0;
  left: 0;
}

.progress-item.is-active::before {
  animation: goProgress linear forwards;
  animation-duration: var(--slide-duration);
  transition: width 0.5s ease-in-out;
}

.progress-item.is-pause::before {
  animation-play-state: paused;
}

.progress-item.is-end::before {
  animation: none;
  width: 100%;
}

.pointer-none {
  pointer-events: none !important;
}

.is-hide {
  display: none !important;
