@keyframes slideFadeOut {
  0% {
    opacity: 1;
  }

  100% {
    opacity: 0;
  }
}


@keyframes goProgress {
  0% {
    width: 0;
  }

  100% {
    width: 100%;
  }
}


@keyframes bound {
  0% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(5px);
  }

  100% {
    transform: translateY(0);
  }
}


@keyframes bound-btn {
  0% {
    transform: translateY(0);
    box-shadow: 0px 8px 0px 0px #1064b1;
  }

  50% {
    transform: translateY(5px);
    box-shadow: 0px 4px 0px 0px #1064b1;
  }

  100% {
    transform: translateY(0);
    box-shadow: 0px 8px 0px 0px #1064b1;
  }
}

