.step_arr {
  position: relative;
  width: min(15vw, 80px);
  height: min(15vw, 80px);
  margin: min(7vw, 20px) auto min(5vw, 50px);
}

.step_arr span {
  position: absolute;
  top: 0;
  left: 0;
  width: min(15vw, 80px);
  height: min(2vw, 10px);
  opacity: 0;
  transform: scale3d(.5, .5, .5);
  animation: Arrowmove 3s ease-out infinite;
}

.step_arr span:nth-of-type(1) {
  animation-delay: 1s;
}

.step_arr span:nth-of-type(2) {
  animation-delay: 2s;
}

.step_arr span:nth-of-type(3) {
  animation-delay: 0s;
}

.step_arr span::before {
  content: ' ';
  position: absolute;
  top: 0;
  left: 0;
  width: 51%;
  height: 100%;
  background: #dddddd;
  transform: skew(0deg, 30deg);
}

.step_arr span::after {
  content: ' ';
  position: absolute;
  top: 0;
  right: 0;
  width: 50%;
  height: 100%;
  background: #dddddd;
  transform: skew(0deg, -30deg);
}

@keyframes Arrowmove {
  25% {
    opacity: 1
  }

  33% {
    opacity: 1;
    transform: translateY(min(2vw, 40px));
  }

  67% {
    opacity: 1;
    transform: translateY(min(8vw, 70px));
  }

  100% {
    opacity: 0;
    transform: translateY(min(12vw, 100px)) scale3d(.5, .5, .5)
  }
}

