.check-area .check-list input[type=radio],
.check-area .check-list input[type=checkbox] {
  display: none;
}

.check-area .check-list input[type=radio]+label,
.check-area .check-list input[type=checkbox]+label {
  position: relative;
  display: flex;
  align-items: center;
  padding: 1.2em 1.5em 1em 3.5em;
  font-size: 24px;
  line-height: 1.2;
  cursor: pointer;
}

.check-area .check-list input[type=radio]+label::before,
.check-area .check-list input[type=checkbox]+label::before {
  content: "";
  position: absolute;
  left: 1em;
  top: 50%;
  transform: translateY(-50%);
  width: 1.2em;
  height: 1.2em;
  border: 0.15em solid #969696;
  border-radius: 0.4em;
