.check-area .check-list input[type=checkbox]:checked+label::before {
  border-color: #D45B41;
}

.check-area .check-list input[type=radio]:checked+label::after,
.check-area .check-list input[type=checkbox]:checked+label::after {
  content: "";
  position: absolute;
  left: 1.5em;
  top: calc(50% - 0.14em);
  transform: translateY(-50%) rotate(45deg);
  width: 0.3em;
  height: 0.7em;
