.chat-item .message::before,
.chat-item .question::before,
.chat-item .message::after,
.chat-item .question::after {
  content: "";
  display: block;
  width: 1em;
  aspect-ratio: 3/4;
  clip-path: polygon(100% 1%, 0 50%, 100% 100%);
  position: absolute;
  background-color: #afd8d0;
  top: 15%;
  left: -1em;
  z-index: 0;
}

.chat-item .message::after,
.chat-item .question::after {
  width: calc(1em - 2px);
  left: calc(-1em + 2.5px);
  background-color: #e5f7f2;
  top: calc(15% + 1px);
  z-index: 1;
}

.chat-item .question {
  background-color: #fff;
  border-color: #ddd;
}

.chat-item .question::before,
.chat-item .question::after {
  display: none;
}

