.resultMain {
  margin: 20px 10px;
  width: calc(100% - 20px);
  height: auto;
  display: flex;
  justify-content: flex-start;
  align-items: flex-start;
}

.resultMain .img__area {
  width: 30%;
  max-width: 230px;
  height: auto;
}

.resultMain .img__area img {
  width: 100%;
  height: auto;
}

.resultMain .text__area {
  width: calc(70% - 20px);
  height: auto;
  margin-left: 20px;
}

.resultMain .text__area .head {
  font-size: 30px;
  font-weight: bold;
  margin: 0;
}

.resultMain .text__area .head .marker {
  background: linear-gradient(to bottom, transparent 44%, #ffef41 44%, #ffef41 70%, transparent 70%);
}

.resultMain .text__area .point__box {
  background: #eaf8fa;
  width: calc(100% - 20px);
  height: auto;
  padding: 0 10px 10px;
  margin-top: 10px;
}

.point__box dl {
  display: flex;
  justify-content: flex-start;
  align-items: flex-start;
  flex-wrap: wrap;
  margin: 0;
}

.point__box dl .pointHead {
  width: 30%;
  height: auto;
  background: #32bed2;
  font-size: 16px;
  font-weight: bold;
  color: #fff;
  text-align: center;
  margin-top: 10px;
}

.point__box dl .pointText {
  width: calc(70% - 10px);
  margin: 10px 0 0 10px;
  font-size: 16px;
}

@media screen and (max-width: 600px) {
  .resultMain {
    flex-wrap: wrap;
  }

  .resultMain .img__area {
    width: 100%;
    max-width: inherit;
  }

  .resultMain .text__area {
    width: 100%;
    margin-left: 0;
  }

  .resultMain .text__area .head {
    font-size: 24px;
  }

  .resultMain .text__area .point__box dl .pointText {
    width: 100%;
    margin: 2px 0 0;
  }
}

.resultDesc {
  margin: 0 10px;
  width: calc(100% - 20px);
  height: auto;
}

.resultDesc .text {
  color: #666;
  font-size: 14px;
  margin: 0;
}

.resultDesc .text+.text {
  margin-top: 10px;
}

.resultJudge {
  margin: 20px 10px 0;
  width: calc(100% - 20px);
  border-top: 1px solid #ffa234;
  border-left: 1px solid #ffa234;
  border-collapse: collapse;
}

@media screen and (max-width: 600px) {
  .resultJudge {
    display: none;
  }
}

.resultJudge th {
  background: #fff6ea;
  border-bottom: 1px solid #ffa234;
  border-right: 1px solid #ffa234;
  color: #666;
  padding: 5px 0;
  font-size: 18px;
}

.resultJudge td {
  border-bottom: 1px solid #ffa234;
  border-right: 1px solid #ffa234;
  text-align: center;
  padding: 5px 0;
  width: 33.3%;
}

.resultJudge td.text {
  font-size: 24px;
  color: #666;
}

.resultJudge td ._bold {
  font-weight: bold;
}

.registerBtn {
  margin-top: 30px;
}

.registerBtn._pcNone {
  display: none;
}

.registerBtn .btn .arrow {
  display: inline-block;
  height: 18px;
  width: 18px;
  background-color: #fff;
  position: relative;
  top: 5px;
  left: -50px;
  animation: arrow 3s linear infinite;
}

@media screen and (max-width: 600px) {
  .registerBtn._pcNone {
    display: block;
  }

  .registerBtn.mb30 {
    margin-bottom: 30px;
  }

  .registerBtn .btn .arrow {
    left: -7%;
    animation: arrowSp 3s linear infinite;
  }
}

.registerBtn .btn .arrow:before {
  position: absolute;
  content: "";
  width: 0;
  height: 0;
  border: 20px solid transparent;
  border-left: 20px solid #fff;
  left: 18px;
  top: -11px;
}

@keyframes arrow {
  0% {
    transform: scale(1) translate(0px, -10px);
  }

  10% {
    transform: scale(1) translate(5px, -10px);
  }

  40% {
    transform: scale(1) translate(15px, -10px);
  }

  50% {
    transform: scale(1) translate(0px, -10px);
  }

  60% {
    transform: scale(1) translate(-50px, -10px);
  }

  75% {
    transform: scale(1) translate(-20px, -10px);
  }

  85% {
    transform: scale(1) translate(15px, -10px);
  }

  100% {
    transform: scale(1) translate(0px, -10px);
  }
}

@keyframes arrowSp {
  0% {
    transform: scale(0.5) translate(0px, -5px);
  }

  10% {
    transform: scale(0.5) translate(2px, -5px);
  }

  40% {
    transform: scale(0.5) translate(10px, -5px);
  }

  50% {
    transform: scale(0.5) translate(0px, -5px);
  }

  60% {
    transform: scale(0.5) translate(-20px, -5px);
  }

  75% {
    transform: scale(0.5) translate(-15px, -5px);
  }

  85% {
    transform: scale(0.5) translate(10px, -5px);
  }

  100% {
    transform: scale(0.5) translate(0px, -5px);
  }
}

