.loading {
  position: relative;
  width: 10px;
  height: 10px;
  border-radius: 5px;
  background-color: #333;
  color: #333;
  animation: dot-flashing 0.5s infinite linear alternate;
  animation-delay: 0.25s;
}

.loading::before,
.loading::after {
  content: "";
  display: inline-block;
  position: absolute;
  top: 0;
}

.loading::before {
  left: -15px;
  width: 10px;
  height: 10px;
  border-radius: 5px;
  background-color: #333;
  color: #333;
  animation: dot-flashing 0.5s infinite alternate;
  animation-delay: 0s;
}

.loading::after {
  left: 15px;
  width: 10px;
  height: 10px;
  border-radius: 5px;
  background-color: #333;
  color: #333;
  animation: dot-flashing 0.5s infinite alternate;
  animation-delay: 0.5s;
}

