.blackwood_box {
  position: relative;
  color: #613d29;
  margin: 30px 0;
}

.blackwood_box .results {
  display: none;
}

.blackwood_box .results.show_result {
  display: block;
  margin-bottom: 10px;
}

.blackwood_box .selecter {
  margin-bottom: 10px;
}

.blackwood_box .selecter .choice-radio {
  border: solid 3px #613d29;
  display: block;
  padding: 10px 15px;
  font-weight: bold;
  border-radius: 28px;
  text-decoration: none;
  color: inherit;
  cursor: pointer;
}

.blackwood_box .selecter .choice-radio:hover {
  background: #f96680;
  border-color: #fff;
  color: #fff;
  box-shadow: 3px 3px 3px rgba(0, 0, 0, 0.5);
  transition: 200ms;
}

.show_result .wood-line {
  background: #f96680;
  color: white;
  border-radius: 30px;
  transition: 1s;
  box-shadow: 3px 3px 3px rgba(0, 0, 0, 0.4);
  width: 1%;
}

.wood-line span {
  width: 100%;
  text-align: right;
  display: block;
  padding: 5px 10px 5px 0;
  box-sizing: border-box;
  white-space: nowrap;
}

@media screen and (max-width:767px) {
  .wood-line span {
    padding-right: 3px;
    font-size: 0.7em;
  }
}

span.result-text {
  font-weight: bold;
}

.checked .results span.result-text {
  padding-left: 1.1em;
  position: relative;
  color: red;
}

.checked .results span.result-text::before {
  content: '';
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  width: 1em;
  height: 1em;
