.view-change-questions {
  max-width: 750px;
  font-size: 20px;
  margin-left: auto;
  margin-right: auto;
  color: #3f3a3b;
  text-align: center;
  background-color: #f0f0f0;
  padding-bottom: 1.5em;
  line-height: 1.5;
  transition: all 0.5s ease;
}

.view-change-questions.is-animate::before {
  content: "";
  position: fixed;
  width: 100vw;
  height: 100vh;
  background: #FFF;
  left: 0;
  top: 0;
  opacity: 1;
  z-index: 5;
  animation: fadeIn 0.5s ease-in-out forwards, fadeOut 0.5s 1.5s ease-in-out forwards;
  will-change: animation, opacity;
}

.view-change-questions.is-animate::after {
  content: "";
  position: fixed;
  width: 100vw;
  height: 100vh;
  background: #fac83c;
  left: 0;
  top: 0;
  transform: translateX(120%);
  animation: slideInOut 1.5s 0.25s ease-in-out forwards;
  will-change: animation, translate;
  z-index: 10;
}

.view-change-wrap {
  padding: 1.5em;
  margin: 1.5em 1.5em 0;
  background-color: #fff;
}

.view-change-progress {
  width: fit-content;
  margin: 0 auto 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75em;
  position: relative;
}

.view-change-progress::before {
  content: "";
  width: 100%;
  height: 3px;
  background-color: #dbdbdb;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  position: absolute;
}

.view-change-progress .progress-item {
  width: 0;
  height: 0;
  padding: 1rem;
  clip-path: circle(50%);
  background-color: #dbdbdb;
  transition: 0.5s;
  counter-increment: number;
  color: #9c9c9c;
}

.view-change-progress .progress-item::before {
  content: "Q" counter(number);
  font-size: 0.8em;
  line-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
}

.view-change-progress .progress-item.current {
  background-color: #fac83c;
  padding: 1.25rem;
  color: #333;
}

.view-change-progress .progress-item.past {
  padding: 0.9rem;
}

.view-change-item:not(:nth-of-type(2)) {
  opacity: 0;
  max-height: 0;
  overflow: hidden;
}
.view-change-item.is-active {
  animation: fadeIn 0.5s 0.5s ease forwards;
  max-height: 100%;
}

.view-change-item .question {
  padding: 1rem 0;
}

.view-change-item .question .num {
  width: fit-content;
  aspect-ratio: 1/1;
  margin: 0 auto 1em;
  font-size: 1.4em;
  font-weight: 600;
  background-color: #fac83c;
  clip-path: circle(50%);
  line-height: unset;
  padding: 0.5em;
  display: grid;
  place-items: center;
}

.view-change-item .question .text {
  font-size: 1.2em;
  line-height: 1.5;
  font-weight: 600;
  text-align: justify;
}

.view-change-item .question .small-text {
  font-size: 0.7em;
  margin: 0.5em 0;
  font-weight: normal;
}

.view-change-item img {
  width: 100%;
  height: auto;
}

.view-change-item .answer {
  background-color: #fff;
  padding: 1em 0;
}

.view-change-item .answer .answer-list {
  display: grid;
  gap: 1em;
  margin-bottom: 1.5em;
}

.view-change-item .answer .answer-list input {
  display: none;
}

.view-change-item .answer .answer-list input:checked+label {
  background-color: #683A09;
  color: #fff;
}

.view-change-item .answer .answer-list input:checked+label::before {
  background-color: #fac83c;
}

.view-change-item .answer .answer-list input:checked+label::after {
  opacity: 1;
}

.view-change-item .answer .answer-list input+label {
  font-size: 0.9em;
  font-weight: 600;
  background-color: #fff;
  display: block;
  padding: 1.5em 0 1.5em 2.5em;
  cursor: pointer;
  border: 2px solid #683A09;
  box-shadow: 0px 5px 0px 0px #683A09;
  color: #683A09;
  border-radius: 0.35em;
  transition: all 0.3s ease;
  text-align: left;
  position: relative;
  line-height: 1;
}

.view-change-item .answer .answer-list input+label::before,
.view-change-item .answer .answer-list input+label::after {
  content: "";
  position: absolute;
  width: 1em;
  height: 1em;
  border: 1px solid #683A09;
  border-radius: 0.35em;
  left: 1em;
  top: 1.5em;
  transition: all 0.3s ease;
}

.view-change-item .answer .answer-list input+label::after {
  border: 3px solid #683A09;
  width: 0.25em;
  height: 0.5em;
  rotate: 45deg;
  border-top: transparent;
  border-left: transparent;
  border-radius: 0;
  left: 1.35em;
  top: 1.65em;
  opacity: 0;
}

.view-change-item.video-item .video-time {
  font-size: 0.9em;
  line-height: 1;
}

.view-change-item.result-item .inner {
  padding: 1em;
}

.view-change-item.result-item .btn {
  text-decoration: none;
  display: block;
  height: auto;
  background-color: #FE5074;
  border: 1px solid #673909;
  border-radius: 20px;
  padding: 1em 0;
  box-shadow: 0 8px 0 0 rgb(103, 57, 9), 0px 6px 0px 0px rgba(92, 50, 18, 0.4);
  overflow: hidden;
  position: relative;
  transition: 0.3s;
  margin: 1.5em 0 0;
  line-height: 1.25;
}

.view-change-item.result-item .btn::before {
  content: "";
  position: absolute;
  background-color: rgba(255, 136, 160, 0.6);
  width: 100%;
  height: 50px;
  -webkit-transform: rotate(0deg);
  transform: rotate(0deg);
  border: none;
  top: 1px;
  right: 0;
  left: 1px;
  border-top-left-radius: 15px;
  border-top-right-radius: 15px;
  border-bottom-left-radius: 50% 60%;
  border-bottom-right-radius: 50% 60%;
  margin-top: 0;
}

.view-change-item.result-item .btn-text {
  position: relative;
  font-size: 1.1em;
  color: #fff;
  font-weight: 600;
  text-align: center;
  line-height: 1.5;
  z-index: 999;
}

.view-change-item.result-item .btn-text-accent {
  font-size: 0.9em;
  color: #FFE65D;
  font-weight: 600;
  text-align: center;
  display: block;
  position: relative;
  z-index: 999;
}

.view-change-next,
.view-change-back {
  width: 80%;
  margin: auto;
  padding: 1em;
  border-radius: 0.25em;
  color: #fff;
  line-height: 1;
  cursor: pointer;
  transition: all 0.3s ease;
  box-sizing: border-box;
  font-weight: 600;
}

.view-change-next:hover,
.view-change-back:hover {
  filter: brightness(1.2);
}

.view-change-next {
  filter: grayscale(200%);
  opacity: 0.5;
  pointer-events: none;
  background: #fac83c;
  box-shadow: 0px 5px 0px 0px #683A09;
  border: 2px solid #683A09;
  color: #683A09;
}

.view-change-next.is-active {
  filter: grayscale(0%);
  opacity: 1;
  pointer-events: all;
}

.view-change-next+.view-change-back {
  margin-top: 1.5em;
}

.view-change-back {
  background: #999;
  box-shadow: 0 4px 0 #666;
}

.is-opcity {
  opacity: 0;
}

.is-hidden {
  opacity: 0;
  max-height: 0;
  overflow: hidden;
}

img,
video {
