.loader,
.loader:before,
.loader:after {
  width: 1em;
  height: 1em;
  animation-fill-mode: both;
}

.loader {
  text-indent: -9999em;
  z-index: 100;
  background-color: #666;
  color: #666;
  animation: dot-flashing 0.25s infinite linear alternate;
  animation-delay: 0.5s;
  margin-left: 1.5em;
}

.loader::before,
.loader::after {
  content: "";
  display: inline-block;
  position: absolute;
  top: 50%;
  translate: 0 -50%;
}

.loader::before {
  left: 0;
  background-color: #666;
  color: #666;
  animation: dot-flashing 1s infinite alternate;
  animation-delay: 0s;
}

.loader::after {
  left: 3em;
  background-color: #666;
  color: #666;
  animation: dot-flashing 1s infinite alternate;
  animation-delay: 1s;
}

.disabled {
  pointer-events: none;
}

._fadeIn {
  animation: fadeIn 1s ease-in-out 0s forwards;
}

@keyframes dot-flashing {
  0% {
    background-color: #666;
  }

  50%,
  100% {
    background-color: rgba(102, 102, 102, 0.2);
  }
}

@keyframes fadeIn {
  0% {
    opacity: 0;
    max-height: 0;
    translate: 0 0;
  }

  50% {
    max-height: 9999vh;
  }

  100% {
    opacity: 1;
    max-height: 9999vh;
    translate: 0 0;
  }
}

@keyframes fadeOut {
  0% {
    opacity: 1;
    max-height: 9999vh;
    translate: 0 0;
  }

  100% {
    opacity: 0;
    max-height: 0;
    translate: 0 0;
    z-index: -100;
  }
}

@keyframes yurayura {
  0% {
    translate: 0 0;
  }

  50% {
    translate: 0 -10px;
  }

  100% {
    translate: 0 0;
  }
}

@keyframes fireworks-animation {
  0% {
    transform: translate(-50%, 90vh);
    width: 4px;
    opacity: 1;
  }

  50% {
    width: 4px;
    opacity: 1;
  }

  100% {
    width: 400px;
    opacity: 0;
  }
}

