img {
  width: 100%;
  height: auto;
}

.wrap-question,
.wrap-result {
  width: 600px;
  text-align: center;
  margin: 20px auto;
}

.title {
  color: #d7083c;
  font-size: 20px;
}

.question {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 0 5px;
  margin: 10px 0;
  font-weight: bold;
  color: #d7083c;
}

.question .num {
  display: inline-flex;
  justify-content: center;
  border: 2px solid #d7083c;
  border-radius: 50%;
  padding: 15px;
  color: #d7083c;
  margin: 0;
  font-size: 20px;
  width: 12.5vw;
  height: 12.5vw;
  align-items: center;
  box-sizing: border-box;
}

.question .num.current {
  background-color: #d7083c;
  color: #fff;
}

.words {
  color: #fff;
  background-color: #d7083c;
  padding: 20px 0;
  margin: 10px 0;
  max-width: unset;
  font-size: 23px;
}

.wrap-img {
  text-align: center;
}

.wrap-img img {
  display: inline !important;
}

.btn-list {
  list-style: none;
  overflow: hidden;
  margin: 0;
  padding: 4.68% 9.37% 5% 9.37%;
  display: flex;
  box-sizing: border-box;
}

.btn-list li {
  width: 50%;
}

.btn-list li:first-child {
  padding-right: 2%;
}

.btn-list li:last-child {
  padding-left: 2%;
}

.radio-input {
  display: none;
}

.btn-radio {
  display: block;
  width: 100%;
  cursor: pointer;
  background-repeat: no-repeat;
  background-size: contain;
  padding: 10%;
  border-radius: 8px;
  font-size: 8vw;
  line-height: 1;
  color: #fff;
  font-weight: bold;
  background: #aaa;
  border-bottom: 5px solid #666;
  box-shadow: 0 3px 5px rgba(0, 0, 0, 0.3);
  transition: all 0.3s;
  box-sizing: border-box;
}

.btn-list input[type=radio]:checked+.y01,
.btn-list input[type=radio]:checked+.n01,
.checked-link input[type=radio]:checked+.y01 .btn-radio,
.checked-link input[type=radio]:checked+.n01 .btn-radio,
.btn-radio:hover {
  margin-top: 3px;
  color: #fff;
  background: #f56500;
  border-bottom: 2px solid #b84c00;
}

.checked-link {
  padding: 4.68% 9.37% 5% 9.37%;
  display: flex;
  flex-wrap: wrap;
  box-sizing: border-box;
}

.checked-link input[type=radio] {
  display: none;
}

.checked-link input[type=radio]+label {
  display: block;
  width: 50%;
  box-sizing: border-box;
}

.checked-link input[type=radio]+label:first-of-type {
  padding-right: 2%;
}

.checked-link input[type=radio]+label:last-of-type {
  padding-left: 2%;
}

.checked-link ::-moz-focus-inner {
  border-color: transparent;
}

.checked-link .link-btn,
.checked-link .result-btn {
  width: 100%;
  margin: 1em 0;
  text-align: center;
  cursor: pointer;
  box-sizing: border-box;
}

.checked-link>.btn-list {
  width: 100%;
  padding: 0;
}

.checked-link .link-btn span,
.checked-link .result-btn span {
  position: relative;
  font-size: 1.2em;
  display: block;
  padding: 1em;
  text-decoration: none;
  font-weight: 700;
  color: #fff;
  background-color: #6c757d;
  opacity: 0.65;
  border-radius: 4px;
  pointer-events: none;
  transition: background-color 0.2s;
}

.checked-link input[type=radio]:checked~.link-btn span,
.checked-link .result-btn.active span {
  color: #fff;
  background-color: #d7083c;
  opacity: 1;
  pointer-events: auto;
}

.checked-link input[type=radio]:checked~.link-btn span:hover {
  background-color: #f73666;
}

.check-list {
  display: inline-block;
  min-width: 90%;
  margin: 0 auto;
  padding: 0 5%;
  list-style: none;
  text-align: left;
  box-sizing: border-box;
}

.check-list label {
  position: relative;
  display: block;
  width: calc(100% - 30px);
  padding-left: 30px;
  cursor: pointer;
  font-size: 20px;
  line-height: 1.4;
  margin-top: 20px;
  font-weight: normal;
}

.check-list label input {
  display: none;
}

.check-list label input+span::before {
  content: "";
  display: block;
  position: absolute;
  top: 0.3em;
  left: 0;
  border: 1px solid #262626;
  width: 20px;
  height: 20px;
  z-index: 1;
}

.check-list label input+span::after {
  content: "";
  display: block;
  position: absolute;
  top: 0;
  left: 10px;
  width: 10px;
  height: 20px;
  border-right: 2px solid transparent;
  border-bottom: 2px solid transparent;
  -webkit-transform: scaleX(0.75) rotate(60deg);
  transform: scaleX(0.75) rotate(60deg);
  transition: 0.2s;
  z-index: 2;
}

.check-list label input:checked+span::after {
  top: 0;
  left: 10px;
  width: 10px;
  height: 20px;
  border-right: 2px solid #C7243A;
  border-bottom: 2px solid #C7243A;
