  animation-delay: 0.3s;
}

.check-bg-list {
  padding: 0;
  margin: 25px auto 10px auto;
  list-style: none;
  text-align: left;
  box-sizing: border-box;
  display: grid;
  gap: 15px;
}

.check-bg-list span {
  width: 100%;
  height: 100%;
  position: relative;
  font-size: 5vw;
  border: solid 1px #ccc;
  border-radius: 7px;
  display: flex;
  align-items: center;
  line-height: 1.5;
  padding: 0.5em 0.5em 0.5em 55px;
