  width: 2.5em;
  height: 2.5em;
  animation-fill-mode: both;
  animation: bblFadInOut 1.8s infinite ease-in-out;
}

.auto-chat .loader {
  color: #000;
  font-size: 7px;
  position: absolute;
  text-indent: -9999em;
  transform: translateZ(0);
  animation-delay: -0.16s;
  top: 10%;
  left: 28%;
  z-index: 100;
}

.auto-chat .loader::before,
.auto-chat .loader::after {
  content: "";
  position: absolute;
  top: 0;
}

.auto-chat .loader::before {
  left: -3.5em;
  animation-delay: -0.32s;
}

.auto-chat .loader::after {
  left: 3.5em;
}

.auto-chat-wrap {
  background-color: #ffe5ec;
  padding: 12% 0 5.5% 5%;
  display: block !important;
  opacity: 1 !important;
}

.auto-chat-wrap>*+* {
  margin-block-start: 4.5em;
}

.auto-chat-greeting>*+*,
.auto-chat-contents>*+*,
.auto-chat-answer>*+*,
.auto-chat-support>*+* {
  margin-block-start: 2em;
}

.auto-chat-greeting.active,
.auto-chat-contents.active,
.auto-chat-answer.active,
.auto-chat-support.active {
  display: block;
}

.auto-chat-item,
.auto-chat-answer {
  position: relative;
  min-height: 5em;
  transition: 0.5s;
}

.auto-chat .icon {
  width: 15%;
  position: absolute;
  top: -2.5em;
  left: 0;
}

.auto-chat .icon img {
  width: 100%;
}

.auto-chat .talk-box,
.auto-chat .answer-box {
  background-color: #fff;
  box-shadow: 2px 3px 1px 0 #f2dae0;
  width: 70%;
  margin: 0 auto 0 20%;
  border-radius: 20px;
  padding: 1.15em;
  position: relative;
  box-sizing: border-box;
  font-size: 1.25em;
  transition: 0.5s;
}

.auto-chat .talk-box::after,
.auto-chat .answer-box::after {
  content: "";
  position: absolute;
  border: 10px solid transparent;
  top: -7px;
}

.auto-chat .talk-box .title,
.auto-chat .answer-box .title {
  font-weight: bold;
  font-size: 1.3em;
}

.auto-chat .talk-box.full-box,
.auto-chat .answer-box.full-box {
  padding: 0;
}

.auto-chat .talk-box.full-content,
.auto-chat .answer-box.full-content {
  width: 100%;
  background: none;
  margin-left: auto;
  box-shadow: none;
}

.auto-chat .talk-box.full-content::after,
.auto-chat .answer-box.full-content::after {
  display: none;
}

.auto-chat .talk-box {
  background-color: #fff;
  border-top-left-radius: 0px;
}

.auto-chat .talk-box::after {
  left: -18px;
  border-right: 25px solid #ffffff;
  rotate: 20deg;
}

.auto-chat .answer-box {
  background-color: #ffacac;
  border-top-right-radius: 0px;
}

.auto-chat .answer-box::after {
  right: -18px;
  border-left: 25px solid #ffacac;
  rotate: -20deg;
}

.auto-chat .answer-box .title {
  text-align: right;
}

.auto-chat .choices {
  padding: 0;
  list-style: none;
  display: grid;
}

.auto-chat .choices>*+* {
  margin-block-start: 0.5em;
}

.auto-chat .choices.active .result {
  display: block;
}

.auto-chat .choices.active input {
  pointer-events: none;
}

.auto-chat .choices.active label {
  box-shadow: none;
  cursor: default;
}

.auto-chat .choices.active li {
  background-color: #fff;
  border-radius: 5px;
}

.auto-chat .choices.active~.select-show-btn {
  opacity: 0.5;
  pointer-events: none;
  background: #d4d4d4;
}

.auto-chat .choices .result {
  display: none;
  border-radius: 0 0 5px 5px;
  padding: 0 1em 1em;
}

.auto-chat .choices input {
  display: none;
}

.auto-chat .choices input[type=radio]:checked+label {
  pointer-events: none;
}

.auto-chat .choices input:checked+label {
  background-color: #d7063b;
  color: #fff;
  border-radius: 5px 5px 0 0;
}

.auto-chat .choices input:checked~.result {
  background-color: #d7063b;
  color: #FFF;
}

.auto-chat .choices input:checked~.result .poll {
  color: #FFF;
}

.auto-chat .choices input[disabled] {
  pointer-events: none;
}

.auto-chat .choices label {
  background-color: #fff;
  text-align: center;
  display: block;
  border-radius: 5px;
  cursor: pointer;
  padding: 0.75em 0;
  box-shadow: 0 3px 2px 0 rgba(38, 0, 10, 0.18);
}

.auto-chat .choices .progress {
