  line-height: 1;
  padding-left: 1em;
  color: #333;
}

.auto-chat .choices .poll {
  display: flex;
  font-size: 0.8em;
  color: #666;
  column-gap: 0.5em;
}

.auto-chat .choices .poll .total::after,
.auto-chat .choices .poll .rate::after {
  content: attr(data-num) "";
  font-size: 0.9em;
  padding-left: 0.25em;
}

.auto-chat .choices .poll .rate::before {
  content: "-";
  padding-right: 0.5em;
}

.auto-chat .choices .choiced label {
  border-radius: 5px !important;
}

.auto-chat .total-poll {
  text-align: right;
  font-size: 0.8em;
}

.auto-chat .select-show-btn {
  background: #d4d4d4;
  color: #FFF;
  text-align: center;
  padding: 0.25em 0;
  margin-top: 0.5em;
