}

.auto-chat-next .btn {
  font-size: 1.3em;
  width: fit-content;
  margin-left: auto;
  background-color: #d7063b;
  color: #FFF;
  text-align: center;
  padding: 0.25em 1.5em;
  border-radius: 10px;
  box-shadow: 0 3px 2px 0 rgba(38, 0, 10, 0.18);
  cursor: pointer;
  position: relative;
  transition: background-color 0.5s, color 0.5s;
  animation: yurayura 3s ease-in-out infinite;
}

.auto-chat-next .btn.disabled {
  background: #d4d4d4;
  box-shadow: none;
  color: #c7c7c7;
  animation: unset;
}

@media screen and (max-width: 600px) {
  .auto-chat {
    font-size: 3vw;
  }

  .auto-chat .talk-box,
  .auto-chat .answer-box {
    width: 75%;
    margin-left: 18%;
  }

  .auto-chat-next {
    width: 75%;
    margin-left: 18%;
  }
}

.disabled {
  pointer-events: none;
}

@keyframes bblFadInOut {

  0%,
  80%,
  100% {
    box-shadow: 0 2.5em 0 -1.3em;
  }

  40% {
    box-shadow: 0 2.5em 0 0;
  }
}

@keyframes progressBtn {
  0% {
    width: calc(0% - 4px);
    opacity: 1;
    background-color: #fff;
  }

  90% {
    width: calc(100% - 4px);
    opacity: 1;
    background-color: #fff;
  }

  100% {
    width: calc(0% - 4px);
    opacity: 0;
    background-color: #d7063b;
  }
}

@keyframes progressBase {
  0% {
    opacity: 0;
  }

  99% {
    opacity: 0;
  }

  100% {
    opacity: 1;
  }
}

@keyframes yurayura {
  0% {
    translate: 0 0;
  }

  50% {
    translate: 0 -10px;
  }

  100% {
    translate: 0 0;
  }
}

.question-reveal-scroll {
