.questions-choice-item .choice-text:before,
.questions-choice-item .choice-text::after {
  content: "";
  width: 40px;
  height: 40px;
  position: absolute;
  left: 0%;
  top: 15px;
  border-radius: 7px;
  background-color: #fff;
