}

.questions-result [data-dishabled="1"] .before {
  opacity: 1;
  transition: 0.25s;
}

.questions-result [data-dishabled="1"] .after {
  position: absolute;
  opacity: 0;
  z-index: -1;
  transition: 0.25s;
}

.questions-result [data-dishabled="0"] .before {
  position: absolute;
  opacity: 0;
}

.questions-result [data-dishabled="0"] .after {
  position: relative;
  opacity: 1;
  z-index: 999;
}

@keyframes loopAnimation {
  0% {
    transform: translateY(0);
  }

  20% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-25px);
  }

  60% {
    transform: translateY(0);
  }

  70% {
    transform: translateY(-15px);
  }

  75% {
    transform: translateY(0);
  }

  80% {
    transform: translateY(-10px);
  }

  90% {
    transform: translateY(0);
  }

  100% {
    transform: translateY(0);
  }
}

