    top: -6px;
    left: 14px;
    width: 16px;
    height: 32px;
    border-right: 4px solid transparent;
    border-bottom: 4px solid transparent;
  }

  .check-list label input:checked+span::after {
    top: -6px;
    left: 14px;
    width: 16px;
    height: 32px;
    border-right: 4px solid #C7243A;
    border-bottom: 4px solid #C7243A;
  }

  .step_arr {
