.loader {
  margin: 100px auto;
  font-size: 25px;
  width: 1em;
  height: 1em;
  border-radius: 50%;
  position: relative;
  text-indent: -9999em;
  animation: load5 1.1s infinite ease;
  transform: translateZ(0);
}

.loader_wrap {
  padding: 2px;
  position: absolute;
  top: 0;
  left: 0;
  opacity: 0.5;
  right: 0;
  bottom: 0;
  display: none;
  align-items: center;
}

.loader_wrap.open {
  display: flex;
}

.btn__box {
  width: 300px;
  height: auto;
  margin: 50px auto 0;
  display: none;
}

.btn__box .btn {
  opacity: 1;
  transition: opacity 0.2s;
}

.btn__box .btn:hover {
  opacity: 0.8;
}

.btn img {
  width: 100%;
  height: auto;
}

.is-hidden {
  display: none;
  opacity: 0;
}

.is-show {
  display: block;
  animation: fadeIn 0.3s ease-in forwards;
}

.is-show-slideBottom {
  display: block;
  animation: slideBottom 0.3s ease-in forwards;
}

@keyframes fadeIn {
  0% {
    opacity: 0;
  }

  100% {
    opacity: 1;
  }
}

@keyframes slideBottom {
  0% {
    opacity: 0;
    transform: translateY(20%);
  }

  30% {
    opacity: 0;
  }

  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

/* widget全体 */
