/* 次へボタン - 押せない時 */
.quiz_cont_item .btn_next:disabled {
  background: #ddd;
  color: #fff;
}

/* 次へボタン - 押せる時 */
.quiz_cont_item .btn_next {
  /* 横幅 */
  width: 300px;
  /* 文字サイズ */
  font-size: 40px;
  /* 文字色 */
  color: #fff;
  /* 背景色 */
  background: #008000;
  /* 枠線|none=無し */
  border: none;
  /* 外側余白|上|左右(auto=自動)|下| */
  margin: 30px auto 0;
  /* 内側余白|上下左右| */
  padding: 10px;
  /* 角の丸み */
  border-radius: 10px;
  /* 文字の影|横方向の距離|縦方向の距離|長さ|色| */
  text-shadow: 0px 1px 3px #afafaf;
  transition: opacity 0.3s;
  display: block;
  appearance: none;
  position: relative;
  box-sizing: border-box;
}

/* 次へボタン - 矢印 */
.quiz_cont_item .btn_next:before {
  /* 横幅 */
  width: 18px;
  /* 縦幅 */
  height: 18px;
  /* 最後が色 */
  border-top: solid 3px #fff;
  /* 最後が色 */
  border-right: solid 3px #fff;
  /* 上からの距離 */
  right: 20px;
  top: 50%;
  transform: translateY(-50%) rotate(45deg);
  position: absolute;
  content: '';
}

/* 次へボタン - マウスを乗せた時 */
.quiz_cont_item .btn_next:hover {
