}

/* 最後の要素 - 外側*/
.result_link {
  /* 横幅 */
  width: 60%;
  /* 外側余白|上|左右(auto=自動)|下| */
  margin: 40px auto 0;
}

/* 最後の要素 - 中身 */
.result_link a {
  /* 文字サイズ */
  font-size: 50px;
  /* 内側余白|上下|左右| */
  padding: 10px 0;
  /* 枠線|太さ|種類|色| */
  border: 1px solid #8bcb8b;
  /* 角の丸み */
  border-radius: 15px;
  /* 文字色 */
  color: #fff;
  /* 影 */
  /* 影|横方向の距離|縦方向の距離|ぼかしの距離|色| */
  box-shadow: 0px 10px 5px #ddd;
  /* 背景色 - グラデーション（to方向|色1|色2） */
  background: linear-gradient(to bottom, #caf1c7 0%, green 80%);
  /* 文字の影|横方向の距離|縦方向の距離|長さ|色| */
  text-shadow: 0px 2px 2px #0b5008;
  text-decoration: none;
  text-align: center;
  box-sizing: border-box;
  transition: all 0.7s;
  position: relative;
  display: block;
}

/* 最後の要素 - マウスを乗せた時 */
