  cursor: pointer;
  opacity: 0.7;
}

/* 最後の要素 - 矢印 */
.result_link a:before {
  /* 横幅 */
  width: 25px;
  /* 縦幅 */
  height: 25px;
  /* 上からの距離 */
  top: 50%;
  /* 右からの距離 */
  right: 20px;
  /* 色 */
  border-top: solid 3px #fff;
  border-right: solid 3px #fff;
  transform: translateY(-50%) rotate(45deg);
  content: '';
  position: absolute;
}

