  border-radius: 6px;
  height: 1.2em;
  width: 1.2em;
  margin: 0;
  position: absolute;
  bottom: calc(-1.2em - 10px);
  left: 50%;
  -webkit-transform: translateX(-50%);
  transform: translateX(-50%);
  z-index: 5;
  transition: border 0.25s linear;
  box-sizing: border-box;
}

.panel-list>li .panel-radio:hover {
  opacity: 0.7;
}

.panel-list>li input:checked+.panel-radio {
  border: 3px solid #6ea8fe;
  opacity: 1;

}

.panel-list>li input:checked+.panel-radio::before {
  border-color: #0d6efd;
}

.panel-list>li input:checked+.panel-radio::after {
  content: "";
  display: block;
  background-color: #0d6efd;
  border-radius: 3px;
  height: calc(1.2em - 10px);
  width: calc(1.2em - 10px);
  margin: 0;
  position: absolute;
  bottom: calc(-1.2em - 5px);
  left: 50%;
  -webkit-transform: translateX(-50%);
  transform: translateX(-50%);
  z-index: 5;
  transition: border 0.25s linear;
  box-sizing: border-box;
}

