  background: #3498db;
  transform: scale(2);
  border-radius: 100%;
  opacity: 0;
  position: absolute;
  content: '';
  transition: all 0.2s;
}

.question-reveal-scroll input[type='checkbox']:checked + label .btn:after {
  opacity: 1;
  transform: rotate(-45deg) scale(1);
}

.question-reveal-scroll input[type='radio']:checked + label .btn::after {
  opacity: 1;
  transform: scale(1);
}

