/*全体の設定*/
.question-reveal-multi {
  width: 750px;
  max-width: 100%;
  font-size: 16px;
  background-color: #fff;
  margin: 0 auto 1rem;
  padding: 1rem;
  line-height: 1.5;
  box-sizing: border-box;
}

/*設問ごとのブロック*/
.question-reveal-multi .questionArea {
  margin-bottom: 96px;
}

/* タイトル */
.question-reveal-multi .title {
  font-size: 2rem;
  text-align: left;
  background: #ddd;
  margin: 0 auto;
  padding: 10px;
}

/* タイトル数字 */
.question-reveal-multi .title_num {
  font-size: 2.5rem;
  margin-right: 5px;
  color: #ccc;
}

/*チェックボックスの設定*/
.question-reveal-multi .linkbox {
  width: 90%;
  text-align: left;
  margin: 48px auto 0;
  padding: 0;
  box-sizing: border-box;
}

.question-reveal-multi input {
  display: none;
}

/* 選択肢の設定 */
.question-reveal-multi .linkbox:not(.yes-no) input + label {
  background: #eee;
  border: 1px solid #ccc;
  padding: 10px;
  margin-bottom: 10px;
  border-radius: 10px;
  cursor: pointer;
  box-sizing: border-box;
  transition: all 0.7s;
  display: block;
}

/* チェックされた時の選択項目設定 */
.question-reveal-multi .linkbox:not(.yes-no) input[type='radio']:checked + label,
.question-reveal-multi .linkbox:not(.yes-no) input[type='checkbox']:checked + label {
  background: #2467bf;
}

/*チェックボックス*/
.question-reveal-multi .linkbox:not(.yes-no) input + label .btn {
  padding: 0.7rem 0.5rem 0.7rem 3.5rem;
  font-weight: normal;
  text-align: left;
  font-size: 1.5rem;
  position: relative;
  display: inline-block;
  box-sizing: border-box;
  cursor: pointer;
}

/* チェックされた時の選択肢文字スタイル */
.question-reveal-multi .linkbox:not(.yes-no) input:checked + label .btn {
  color: #fff;
}

/*チェックボックスの装飾設定  - 単一選択*/
.question-reveal-multi .linkbox:not(.yes-no) input[type='radio'] + label .btn::before {
  top: 50%;
  transform: translateY(-50%);
  left: 8px;
  width: 32px;
  height: 32px;
  border: solid 2px #888888;
  background: #ffffff;
  border-radius: 50%;
  content: '';
  display: block;
  position: absolute;
  box-sizing: border-box;
}

/*チェックボックスの装飾設定  - 複数選択*/
.question-reveal-multi .linkbox:not(.yes-no) input[type='checkbox'] + label .btn::before {
  top: 50%;
  transform: translateY(-50%);
  left: 8px;
  width: 32px;
  height: 32px;
  border: solid 2px #888888;
  background: #ffffff;
  border-radius: 5px;
  content: '';
  display: block;
  position: absolute;
  box-sizing: border-box;
}

