/* 全体の設定 */
.question5change__area {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
}



/* 1つの設問 */
.question__contents .item {
  /* 横幅 */
  width: 100%;
  /* 内側の下余白 */
  padding-bottom: 5%;
  /* 背景色 */
  background: #e7e3d3;
}



/* 1つのゴール */
.answer__contents .item {
  /* 横幅 */
  width: 100%;
}



/* ゴール内画像 */
.answer__contents .item img {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
}



/* 設問の中 */
.item__inner {
  /* 横幅 */
  width: 90%;
  /* 高さ */
  height: auto;
  /* 外側の余白 */
  margin: 0 auto;
  /* 背景色 */
  background: #fff;
}



/* 見出し画像 */
.headImg__box {
  /* 横幅 */
  width: 111%;
  /* 最大幅 */
  max-width: 111%;
  /* 外側の左余白 */
  margin-left: -5.5%;
}



/* 見出し画像 */
.headImg__box img {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
}



/* 見出しの箱 */
.head__box {
  /* 横幅 */
  width: 111%;
  /* 最大幅 */
  max-width: 111%;
  /* 高さ */
  height: auto;
  /* 背景色 */
  background: linear-gradient(to bottom, #bc0832 0%, #890000 100%);
  position: relative;
  /* 内側の余白 */
  padding: 25px 0;
  /* 外側の余白 */
  margin: 0 0 60px -5.5%;
  display: block;
}



/* 見出しの装飾（下の三角形） */
.head__box:before {
  content: "";
  position: absolute;
  /* 表示位置（下基準） */
  bottom: -60px;
  /* 表示位置（左基準） */
  left: 0;
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: 60px;
  /* 背景色 */
  background: linear-gradient(to top right, transparent 50%, #890000 50%) no-repeat top left / 50% 100%,
    linear-gradient(to top left, transparent 50%, #890000 50%) no-repeat bottom right/50% 100%;
}



/* 見出し */
.head__box .text {
  /* 文字の大きさ */
  font-size: 36px;
  /* 文字の色 */
  color: #fff;
  /* 文字の位置 */
  text-align: center;
  /* 外側の余白 */
  margin: 0;
}



/* 見出しの大きい文字 */
.head__box .text ._big {
  /* 文字の大きさ */
  font-size: 46px;
}



/* 要素 */
.content {
  /* 内側の余白 */
  padding: 24px 5% 40px;
}



/* 質問番号 */
.content .qNum {
  /* 文字の色 */
  color: #C7243A;
  /* 文字の大きさ */
  font-size: 48px;
  /* 文字の太さ */
  font-weight: bold;
  /* 文字の位置 */
  text-align: center;
  /* 外側の余白 */
  margin: 0;
}



/* 質問内容 */
.content .question {
  /* 文字の大きさ */
  font-size: 44px;
  /* 行間 */
  line-height: 1.5;
  /* 文字の太さ */
  font-weight: bold;
  /* 外側の余白 */
  margin: 40px 0 0;
}



/* 質問内容の小さい文字 */
.question ._small {
  /* 文字の大きさ */
  font-size: 24px;
  /* 文字の太さ */
  font-weight: normal;
}



/* 設問内画像の箱 */
.questionImg {
  /* 外側の上余白 */
  margin-top: 20px;
}



/* 設問内画像 */
.questionImg img {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
}



/* チェックを入れるところの箱 */
.content .checkbox__area {
  /* 横幅 */
  width: 90%;
  /* 高さ */
  height: auto;
  /* 外側の余白 */
  margin: 0 auto;
  display: flex;
  /*水平方向に間隔を配置する方法。
      flex-start = 左側から配置する
      flex-end = 右側から配置する
      center = 真ん中に配置する
      space-around = 均等配置して両端に間隔を置く
      space-between = 均等配置してエリアの間に間隔を置く
      space-evenly = 均等配置して各アイテム周りに間隔を置く*/
  flex-direction: column;
  /*垂直方向にの配置位置を設定。
      center = 中央配置
      flex-start = 先頭にまとめる
      flex-end = 末尾にまとめる*/
  align-items: flex-start;
}



/* チェック（非表示） */
.checkbox__area input {
  /* 非表示 */
  display: none;
}



/* チェックのラベル */
.checkbox__area label {
  position: relative;
  display: block;
  /* 横幅 */
  width: calc(100% - 50px);
  /* 内側の左余白 */
  padding-left: 50px;
  /* 対象に触れた時のカーソル反応 */
  cursor: pointer;
  /* 文字の大きさ */
  font-size: 38px;
  /* 外側の上余白 */
  margin-top: 20px;
  /* 文字の太さ */
  font-weight: normal;
}

.checkbox__area label:before,
.checkbox__area label:after {
  content: "";
  display: block;
  position: absolute;
}



/* チェックの箱 */
.checkbox__area label:before {
  /* 表示位置（上基準） */
  top: .5em;
  /* 表示位置（左基準） */
  left: 0;
  /* 線｜太さ｜線種｜色｜ */
  border: 1px solid #262626;
  /* 横幅 */
  width: 32px;
  /* 高さ */
  height: 32px;
  z-index: 1;
}



/* チェックマーク（入れる前） */
.checkbox__area input+label:after {
  /* 表示位置（上基準） */
  top: 8px;
  /* 表示位置（左基準） */
  left: 14px;
  /* 横幅 */
  width: 16px;
  /* 高さ */
  height: 32px;
  /* 右線｜太さ｜線種｜色｜ */
  border-right: 4px solid transparent;
  /* 下線｜太さ｜線種｜色｜ */
  border-bottom: 4px solid transparent;
  /* 変形｜拡大縮小（X方向）｜回転｜ */
  transform: scaleX(0.75) rotate(60deg);
  /* アニメーションの速さ */
  transition: .2s;
  z-index: 2;
}



/* チェックマーク（入れた後） */
.checkbox__area input:checked+label:after {
  /* 表示位置（上基準） */
  top: 8px;
  /* 表示位置（左基準） */
  left: 14px;
  /* 横幅 */
  width: 16px;
  /* 高さ */
  height: 32px;
  /* 右線｜太さ｜線種｜色｜ */
  border-right: 4px solid #C7243A;
  /* 下線｜太さ｜線種｜色｜ */
  border-bottom: 4px solid #C7243A;
  /* 変形｜拡大縮小（X方向）｜回転｜ */
  transform: scaleX(1) rotate(45deg);
}



/* ボタン */
.btn {
  /* 横幅 */
  width: 90%;
  /* 高さ */
  height: auto;
  /* 文字の位置 */
  text-align: center;
  /* 文字の大きさ */
  font-size: 36px;
  /* 文字の太さ */
  font-weight: bold;
  /* 文字の色 */
  color: #fff;
  /* 背景色 */
  background: #5ebd25;
  /* 線｜太さ｜線種｜色｜ */
  border: 3px solid #eee;
  /* 角丸 */
  border-radius: 50vw;
  /* 影｜X方向｜Y方向｜ぼかし｜色｜ */
  box-shadow: 3px 3px 3px rgba(0, 0, 0, 0.2);
  /* 内側の余白 */
  padding: 10px 0;
  /* 外側の余白 */
  margin: 30px auto 0;
  position: relative;
  /* アニメーションの速さ */
  transition: background 0.2s;
  /* 対象に触れた時のカーソル反応 */
  cursor: pointer;
  /* 飾り */
  text-decoration: none;
  display: block;
}



/* ボタンホバー時 */
.btn:hover {
  /* 背景色 */
  background: #71c647;
}



/* ボタン（非アクティブ） */
.btn:disabled {
  /* 背景色 */
  background: #ccc;
  /* 対象に触れた時のカーソル反応 */
  cursor: inherit;
}



/* ボタンホバー（非アクティブ） */
.btn:disabled:hover {
  /* 背景色 */
  background: #ccc;
}



/* ボタン内のマーク（白丸） */
.btn:before {
  content: '';
  /* 背景色 */
  background: #fff;
  /* 横幅 */
  width: 30px;
  /* 高さ */
  height: 30px;
  /* 角丸 */
  border-radius: 15px;
  position: absolute;
  /* 表示位置（上基準） */
  top: 50%;
  /* 表示位置（右基準） */
  right: 30px;
  /* 変形｜｜｜ */
  transform: translateY(-50%);
  /* 影｜X方向｜Y方向｜ぼかし｜色｜ */
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
}



/* ボタン内のマーク（三角） */
.btn:after {
  content: '';
  /* 横幅 */
  width: 8px;
  /* 高さ */
  height: 14px;
  /* 背景色 */
  background: linear-gradient(to bottom left, transparent 50%, #5ebd25 50%) no-repeat top left / 100% 50%,
    linear-gradient(to top left, transparent 50%, #5ebd25 50%) no-repeat bottom left/100% 50%;
  position: absolute;
  /* 表示位置（上基準） */
  top: 50%;
  /* 表示位置（右基準） */
  right: 40px;
  /* 変形｜｜｜ */
  transform: translateY(-50%);
}



/* ボタン内のマーク（非アクティブ、三角） */
.btn:disabled:after {
  /* 背景色 */
  background: linear-gradient(to bottom left, transparent 50%, #ccc 50%) no-repeat top left / 100% 50%,
    linear-gradient(to top left, transparent 50%, #ccc 50%) no-repeat bottom left/100% 50%;
}



/* チェック後表示されつエリア */
