/* 全体の設定 */
.questionFlame__area {
  /* 横幅 */
  width: 600px;
  /* 最大幅 */
  max-width: 100%;
  /* 高さ */
  height: auto;
  /* 外側の余白 */
  margin: 0 auto 20px;
}

/* 吹き出しと画像が入る部分の設定 */
.message__box {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
  display: flex;
  /*水平方向に間隔を配置する方法。
  flex-start = 左側から配置する
  flex-end = 右側から配置する
  center = 真ん中に配置する
  space-around = 均等配置して両端に間隔を置く
  space-between = 均等配置してエリアの間に間隔を置く
  space-evenly = 均等配置して各アイテム周りに間隔を置く*/
  justify-content: flex-end;
  /*垂直方向にの配置位置を設定。
  center = 中央配置
  flex-start = 先頭にまとめる
  flex-end = 末尾にまとめる*/
  align-items: center;
}

/* 吹き出し部分 */
.message__box .fukidashi__box {
  /* 横幅 */
  width: calc(76% - 19px);
  /* 高さ */
  height: auto;
  /* 線｜太さ｜線種｜色｜ */
  border: 2px solid #ffa500;
  /* 角丸 */
  border-radius: 5px;
  /* 背景色 */
  background: #fff;
  /* 内側の余白 */
  padding: 10px 2%;
  /* 外側の右余白 */
  margin-right: 19px;
  position: relative;
}

/* 吹き出しの三角部分（縁部分） */
.fukidashi__box:before {
  content: "";
  position: absolute;
  /* 表示位置（上基準 */
  top: 50%;
  /* 表示位置（右基準） */
  right: -19px;
  transform: translateY(-50%);
  /* 横幅 */
  width: 0;
  /* 高さ */
  height: 0;
  /* 線種 */
  border-style: solid;
  /* 線の太さ */
  border-width: 19px 0 0 19px;
  /* 線の色 */
  border-color: transparent transparent transparent #ffa600;
}

/* 吹き出しの三角部分（中側） */
.fukidashi__box:after {
  content: "";
  position: absolute;
  /* 表示位置（上基準 */
  top: 50%;
  /* 表示位置（右基準） */
  right: -15px;
  transform: translateY(-50%);
  /* 横幅 */
  width: 0;
  /* 高さ */
  height: 0;
  /* 線種 */
  border-style: solid;
  /* 線の太さ */
  border-width: 15px 0 0 15px;
  /* 線の色 */
  border-color: transparent transparent transparent #ffffff;
}

