  display: inline-block;
  /* 高さ */
  height: 18px;
  /* 横幅 */
  width: 18px;
  /* 背景色 */
  background-color: #fff;
  position: relative;
  /* 表示位置（上基準） */
  top: 5px;
  /* 表示位置（左基準） */
  left: -50px;
  /*アニメーションの設定｜アニメーション名｜1回のサイクルに要する時間｜進め方｜実行回数｜*/
  animation: arrow 3s linear infinite;
}

