   }
 }


 @keyframes arrowSp {
   0% {
     transform: scale(0.5) translate(0px, -5px);
   }

   10% {
     transform: scale(0.5) translate(2px, -3px);
   }

   40% {
     transform: scale(0.5) translate(10px, -5px);
   }

   50% {
     transform: scale(0.5) translate(0px, -5px);
   }

   60% {
     transform: scale(0.5) translate(-20px, -5px);
   }

   75% {
     transform: scale(0.5) translate(-15px, -5px);
   }

   85% {
     transform: scale(0.5) translate(10px, -5px);
   }

   100% {
     transform: scale(0.5) translate(0px, -5px);
   }
 }

.is-hidden {
  display: none;
}

.is-show {
  display: block;
  animation: fadeIn 0.3s ease-in forwards;
}

.is-show-slideBottom {
  display: block;
  animation: slideBottom 0.3s ease-in forwards;
}

@keyframes fadeIn {
  0% {
    opacity: 0;
  }

  100% {
    opacity: 1;
  }
}

@keyframes slideBottom {
  0% {
    opacity: 0;
    transform: translateY(20%);
  }

  30% {
    opacity: 0;
  }

  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

