 .make-summary {
   width: 100%;
   /* 最大幅 */
   max-width: 800px;
   margin: 0 auto;
   text-align: center;
   box-sizing: border-box;
 }

 .make-summary>.title {
   margin: 1em 0;
   padding: 0 0 10px 0;
   /* 見出しの文字サイズ */
   font-size: 150%;
   /* 見出しの文字色 */
   color: #191970;
   line-height: 1.2;
   font-weight: 700;
   position: relative;
 }

 .make-summary>.title::after {
   content: "";
   position: absolute;
   bottom: 0;
   left: calc(50% - 1em);
   width: 2em;
   height: 2px;
   /* 見出し下線装飾の色 */
   background-color: #4169e1;
 }

 .make-summary>.lead {
   margin: 0;
   padding: 0;
