   width: 100%;
   border: 1px solid #191970;
   margin: 30px auto 0;
   padding: 30px;
   box-sizing: border-box;
 }

 .make-summary .view>.question {
   /* display: noneをコメントアウトすると質問部分がエディタ上に表示されます
