   color: #191970;
   font-weight: 700;
   position: relative;
 }

 .make-summary .view>.question .title::before {
   content: "";
   position: absolute;
   top: calc(50% - 2px);
   left: calc(100% + 0.3em);
   width: 1em;
   height: 3px;
   /* 質問見出し装飾の色 */
   background-color: #191970;
 }

 .make-summary .view>.question .title::after {
   content: "";
   position: absolute;
   top: calc(50% - 2px);
   right: calc(100% + 0.3em);
   width: 1em;
   height: 3px;
