/* ウィジェット全体 */
.l-survey_arw {
  /* 横幅 */
  width: 100%;
  /* 最大幅 */
  max-width: 780px;
  /* 外側余白|上|左右auto=自動|下| */
  margin: 0 auto 20px;
  /* 内側余白|上下左右| */
  padding: 0;
  box-sizing: border-box;
  line-height: 1.4;
}

/* リストスタイルリセット */
.l-survey_arw__list,
.l-survey_arw__progress,
.l-survey_arw__qa__a {
  list-style-type: none;
  /* 外側余白|上下左右| */
  margin: 0;
  /* 内側余白|上下左右| */
  padding: 0;
}

/* それぞれの問題 */
.l-survey_arw__list__item {
  padding-bottom: 19vh;
  /* 外側余白|上|左右auto=自動|下| */
  margin: 0 0 20px;
  box-sizing: border-box;
  overflow: hidden;
  position: relative;
  z-index: 1;
}

/* 問題下の三角 */
.l-survey_arw__list__item:before {
  /* 大きさ|高さ|横幅半分|0|横幅半分 */
  border-width: 160px 50vw 0 50vw;
  /* 色 */
  border-color: #ddd transparent transparent transparent;
  bottom: 10px;
  width: 0;
  height: 0;
  border-style: solid;
  position: absolute;
  z-index: 0;
  content: "";
  right: 50%;
  transform: translateX(50%);
}

.l-survey_arw__list__item__inner {
  /* 背景色 */
  background-color: #ddd;
  /* 内側余白|上下|左右| */
  padding: 10px;
  /* 外側余白|上|左右|下| */
  margin: 0 0 20px;
  position: relative;
  box-sizing: border-box;
}

/* 次への文字 */
.l-survey_arw__list__item__inner:after {
  /* 文字サイズ */
  font-size: 27px;
  /* 表示させる文字 */
  content: "次へ";
  /* 文字の太さ */
  font-weight: bold;
  /* 文字揃え|center=中央|left=左|right=右| */
  text-align: center;
  /* 下からの距離 */
  bottom: -80px;
  right: 50%;
  transform: translateX(50%);
  display: block;
  position: absolute;
  z-index: 1;
}

@media screen and (max-width: 860px) {
  .l-survey_arw__list__item {
    padding-bottom: 70px;
  }

  .l-survey_arw__list__item:before {
    border-width: 80px 50vw 0 50vw;
  }

  .l-survey_arw__list__item__inner:after {
    font-size: 18px;
    bottom: -40px;
  }
}

/* 進捗 */
.l-survey_arw__progress {
  /* 横並び */
  display: flex;
  justify-content: center;
  align-items: center;
}

/* 進捗それぞれ */
.l-survey_arw__progress__item {
  /* 文字サイズ */
  font-size: 20px;
  /* 文字の太さ */
  font-weight: bold;
  /* 外側余白|上|右|下|左 */
  margin: 0 4px 20px 4px;
  /* 背景色 */
  background: #fff;
  /* 文字揃え|center=中央|left=左|right=右| */
  text-align: center;
  flex: 1;
  box-sizing: border-box;
}

/* 現在の進捗 */
.l-survey_arw__progress__item.current {
  /* 文字色 */
  color: #fff;
  /* 背景色 */
  background: #5e200d;
}

/* 問題文 */
.l-survey_arw__q {
  /* 文字サイズ */
  font-size: 26px;
  /* 文字の太さ */
  font-weight: bold;
  /* 外側下余白 */
  margin-bottom: 20px;
  /* 文字揃え|center=中央|left=左|right=右| */
  text-align: center;
}

/* 注釈 */
.caution {
  /* 文字サイズ */
  font-size: 14px;
  /* 文字揃え|center=中央|left=左|right=右| */
  text-align: right;
  /* 外側余白|上|左右|下| */
  margin: 10px 0 0;
  display: block;
}

/* 回答リスト */
.l-survey_arw__qa__a {
  /* 外側下余白 */
  margin-bottom: 10px;
}

/* 回答文 */
.l-survey_arw__qa__a__item {
  /* 外側下余白 */
  margin-bottom: 10px;
}

/* 回答分 */
.l-survey_arw__qa__a__item__label {
  /* 文字サイズ */
  font-size: 20px;
  display: inline-flex;
  cursor: pointer;
}

/* ラジオボタン丸 */
.l-survey_arw__qa__a__item__label input[type="radio"] {
  /* 線|太さ|タイプ|色| */
  border: 2px solid #ccc;
  /* 横幅 */
  width: 20px;
  /* 高さ */
  height: 20px;
  /* 角の丸み */
  border-radius: 50%;
  /* 背景色 */
  background: #fff;
  /* 外側余白|上|右|下|左 */
  margin: 0.5em 10px 0 0;
  flex-shrink: 0;
  position: relative;
  appearance: none;
}

/* チェックボックス四角 */
.l-survey_arw__qa__a__item__label input[type="radio"]:checked:before {
  /* 横幅 */
  width: 12px;
  /* 高さ */
  height: 12px;
  /* 角の丸み */
  border-radius: 50%;
  /* 左からの距離 */
  left: 2px;
  /* 上からの距離 */
  top: 2px;
  /* 背景色 */
  background: #000;
  content: "";
  position: absolute;
}

.l-survey_arw__qa__a__item__label input[type="checkbox"] {
  /* 線|太さ|タイプ|色| */
  border: 2px solid #ccc;
  /* 横幅 */
  width: 20px;
  /* 高さ */
  height: 20px;
  /* 背景色 */
  background: #fff;
  /* 外側余白|上|右|下|左 */
  margin: 0.5em 10px 0 0;
  flex-shrink: 0;
  position: relative;
  appearance: none;
}

.l-survey_arw__qa__a__item__label input[type="checkbox"]:checked:before {
  /* 横幅 */
  width: 15px;
  /* 高さ */
  height: 7px;
  /* 上からの距離 */
  top: 0;
  /* 左からの距離 */
  left: 0;
  /* 左の線|幅|タイプ|色| */
  border-left: 3px solid #000;
  /* 右の線|幅|タイプ|色| */
  border-bottom: 3px solid #000;
  transform: rotate(-45deg);
  position: absolute;
  content: "";
}

/* 画像 */
.l-survey_arw__image img {
  /* 最大横幅 */
  max-width: 100%;
  height: auto;
}

/* 最後に表示される部分 */
.l-survey_arw_result {
  box-sizing: border-box;
}

/* 最後に表示される部分の画像 */
.l-survey_arw_result img {
  /* 最大横幅 */
  max-width: 100%;
  height: auto;
}

