      space-evenly = 均等配置して各アイテム周りに間隔を置く*/
   justify-content: center;
 }



 /* 吹き出し */
 .userCount__area .fukidashi {
   /* 横幅 */
   width: 148px;
   position: relative;
   /* 文字の太さ */
   font-weight: bold;
   /* 文字の位置 */
   text-align: center;
   display: inline-block;
   /* 背景色 */
   background: #32bed2;
   /* 文字の大きさ */
   font-size: 16px;
   /* 内側の余白 */
   padding: 6px 12px;
   /* 外側の余白 */
   margin: 0 auto 12px;
   /* 文字の色 */
   color: #ffffff;
   /* 角丸 */
   border-radius: 32px;
 }



 /* 吹き出し下の三角 */
 .userCount__area .fukidashi:after {
   content: '';
   /* 横幅 */
   width: 0;
   /* 高さ */
   height: 0;
   border-style: solid;
   border-width: 12px 6px 0 6px;
   /* 三角の色 */
   border-color: #32bdd2 transparent transparent transparent;
   position: absolute;
   bottom: -12px;
   /* 表示位置（左基準） */
   left: 50%;
   transform: translateX(-50%);
 }



 /* 吹き出し内の人数部分 */
 .userCount__area .fukidashi .num {
   /* 文字の大きさ */
   font-size: 20px;
 }



 /* 診断するボタン */
 .btn {
   /* 横幅 */
   width: 90%;
   /* 高さ */
   height: auto;
   /* 外側の余白 */
   margin: 0 auto;
   /* 内側の余白 */
   padding: 15px 0;
   /* 文字の色 */
   color: #fff;
   /* 文字の太さ */
   font-weight: bold;
   /* 文字の大きさ */
   font-size: 30px;
   /* 文字の位置 */
   text-align: center;
   /* 文字飾り */
   text-decoration: none;
   display: block;
   /* 角丸 */
   border-radius: 42px;
   /* 背景色 */
   background: linear-gradient(180deg, rgba(252, 153, 172, 1) 0%, rgba(240, 117, 139, 1) 100%);
   /* 影｜X方向｜Y方向｜ぼかし｜色｜ */
   box-shadow: 0 5px 0 #d64d65;
   /* 透明度 */
   opacity: 1;
   /* アニメーションの対象と速さ */
   transition: opacity 0.2s;
 }

 /* レスポンシブ（初期：画面幅600px以下） */
 @media screen and (max-width:600px) {
   .btn {
     padding: 5px 0;
   }
 }



 /* ボタンをホバーした時 */
 .btn:hover {
   /* 透明度 */
   opacity: 0.8;
 }

