/* ウィジェット全体 */
.l-chat {
  /* 横幅 */
  width: 100%;
  /* 最大幅 */
  max-width: 780px;
  /* 外側余白|上|左右auto=自動|下| */
  margin: 0 auto 20px;
  /* 内側余白|上下|左右| */
  padding: 0 10px;
  box-sizing: border-box;
}

.l-chat ul {
  list-style-type: none;
}

.l-chat__list {
  /* 外側余白 */
  margin: 0;
  /* 内側余白 */
  padding: 0;
}

.l-chat__list__item {
  /* 外側余白|上|左右auto=自動|下| */
  margin: 0 auto 20px;
  /* 内側余白 */
  padding: 0;
}

.l-chat__list__item:not(:first-of-type) {
  display: none;
}

.l-chat__list__item:not(:first-of-type).is-show {
  display: block;
}

/* 読み込み中の表示 */
.l-chat__loading {
  /* 横並び */
  display: flex;
  justify-content: flex-start;
  align-items: center;
  opacity: 1;
}

.l-chat__loading.is-hidden {
  display: none;
}

.l-chat__loading__loader {
  display: flex;
}

.loader_square {
  opacity: 0;
}

/* 読み込み中の表示の四角アニメーション */
.loader_square:nth-of-type(1) {
  animation: 1s linear infinite loading;
}

.loader_square:nth-of-type(2) {
  animation: 1s linear 0.3s infinite loading;
}

.loader_square:nth-of-type(3) {
  animation: 1s linear 0.6s infinite loading;
}

@keyframes loading {
  0% {
    opacity: 0;
  }

  66.66% {
    opacity: 1;
  }

  100% {
    opacity: 1;
  }
}

/* 読み込み中の表示の四角設定 */
.loader_square {
  /* 横幅 */
  width: 15px;
  /* 縦幅 */
  height: 17px;
  /* 背景色 */
  background: #000;
  /* 外側余白右 */
  margin-right: 7px;
}

/* ロゴ */
.l-chat__logo {
  /* 外側余白右 */
  margin-right: 10px;
  /* 横幅 */
  width: 15%;
  /* 縦幅 */
  height: auto;
}

.l-chat__qa {
  /* 横並び */
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
}

/* 質問者画像 */
.l-chat__asker {
  /* 横幅 */
  width: 15%;
  /* 縦幅 */
  height: auto;
}

/* 吹き出し */
.l-chat__qa__q {
  /* 横幅 */
  width: 85%;
  /* 文字揃え|center=中央|left=左|right=右 */
  text-align: left;
  /* 外側余白 */
  margin: 0;
  /* 内側余白|上|左|下|右| */
  padding: 0 0 0 20px;
  box-sizing: border-box;
}

/* 吹き出しのスタイル */
.l-chat__qa__q__item__inner {
  /* 最大幅 */
  max-width: 80%;
  /* 文字サイズ */
  font-size: 1em;
  /* 背景色 */
  background: #e5e5e5;
  /* 角の丸み */
  border-radius: 1em;
  /* 外側余白|上|左|下|右| */
  margin: 0 0 10px 10px;
  /* 内側余白 */
  padding: 0.8em;
  /* 文字揃え|center=中央|left=左|right=右 */
  text-align: left;
  border: none;
  line-height: 1.5;
  display: inline-block;
  position: relative;
}

.l-chat__qa__q__item__inner:after {
  /* 上からの距離 */
  top: 15px;
  /* 左からの距離 */
  left: -20px;
  width: 0;
  height: 0;
  content: "";
  border-style: solid;
  border-width: 5px 10px;
  border-color: rgba(0, 0, 0, 0) #e5e5e5 rgba(0, 0, 0, 0) rgba(0, 0, 0, 0);
  position: absolute;
}

/* 次へボタン */
.l-btn__next button {
  /* 外側余白|上|左|下|右| */
  margin: 20px 0 0 auto;
  /* 背景色 */
  background: #070707;
  /* 文字色 */
  color: #fff;
  /* 内側余白|上下|左右| */
  padding: 0.7em 2em;
  /* 角の丸み */
  border-radius: 3em;
  font-weight: bold;
  font-size: 1.1em;
