/* widget全体の設定 */
.question_branches {
  /* 外側の下余白 */
  margin-bottom: 20px;
  /* 内側の余白 */
  padding: 15px 15px 15px;
  /* 背景色 */
  background-color: #CAE9FF;
  /* 背景の模様（斜線） */
  background-image: -webkit-gradient(linear, 0 0, 100% 100%, color-stop(.25, #75b2c6), color-stop(.25, #7cb6c9), color-stop(.5, #7cb6c9), color-stop(.5, #75b2c6), color-stop(.75, #75b2c6), color-stop(.75, #7cb6c9), to(#7cb6c9));
  /* 斜線の太さ */
  background-size: 14px 14px;
  box-sizing: border-box;
  /* 最大幅 */
  max-width: 100%;
}



/* widgetに使用している画像の設定 */
.question_branches img {
  /* 最大幅 */
  max-width: 100%;
}



/* 設問ずつの設定 */
.question_branches .question_branches__item {
  /* 内側の余白 */
  padding: 12px;
  box-sizing: border-box;
}



/* check○の文字 */
.question_branches__item .question_branches__question {
  /* 文字色 */
  color: #fff;
  /* 文字の大きさ */
  font-size: 36px;
  /* 文字の位置 */
  text-align: center;
  /* 文字の太さ */
  font-weight: bold;
  /* 外側の下余白 */
  margin-bottom: 10px;
}



/* 黄色文字 */
.color-yellow {
  /* 文字色 */
  color: #e9f344;
}



/* 設問の白丸 */
.question_branches__item .checkNum {
  display: flex;
  /*水平方向に間隔を配置する方法。
      flex-start = 左側から配置する
      flex-end = 右側から配置する
      center = 真ん中に配置する
      space-around = 均等配置して両端に間隔を置く
      space-between = 均等配置してエリアの間に間隔を置く
      space-evenly = 均等配置して各アイテム周りに間隔を置く*/
  justify-content: space-between;
  /*垂直方向にの配置位置を設定。
      center = 中央配置
      flex-start = 先頭にまとめる
      flex-end = 末尾にまとめる*/
  align-items: flex-start;
  /* 横幅 */
  width: 80%;
  /* 最大幅 */
  max-width: 100px;
  /* 外側の余白 */
  margin: 0 auto;
}



/* 設問の白丸（1つずつ） */
.question_branches__item .checkNum .num {
  /* 横幅 */
  width: 14px;
  /* 高さ */
  height: 14px;
  /* 線｜太さ｜線種｜色｜ */
  border: 1px solid #fff;
  /* 角丸 */
  border-radius: 7px;
}



/* 設問の白丸（active） */
.question_branches__item .checkNum .num.active {
  /* 背景色 */
  background: #fff;
}



/* 設問文のエリア */
.question_branches__item .question__text {
  /* 背景色 */
  background: #fff;
  /* 横幅 */
  width: 95%;
  /* 高さ */
  height: auto;
  /* 内側の余白 */
  padding: 20px 2.5%;
  /* 外側の上余白 */
  margin-top: 30px;
}



/* 設問文 */
.question_branches__item .question__text p {
  /* 文字色 */
  color: #0f4980;
  /* 文字の大きさ */
  font-size: 30px;
  /* 文字の太さ */
  font-weight: bold;
  /* 文字の位置 */
  text-align: center;
}



/*チェックしないと表示しないエリア*/
.question_branches .question_branches__item.is-hidden {
  /* 非表示 */
  display: none;
}



/* 設問の画像 */
.question_branches__img {
  /* 行間 */
  line-height: 0;
}



/* 回答リストエリア */
.question_branches ul {
  /* 背景色 */
  background: rgba(0, 0, 0, 0.1);
  /* 内側の余白 */
  padding: 20px 0;
  /* 外側の余白 */
  margin: 0;
}



/* 回答リスト */
.question_branches li {
  /* 外側の余白 */
  margin: 10px;
  /* 行間 */
  line-height: 2;
  /* 文字の大きさ */
  font-size: 1.5rem;
  /* 文字の太さ */
  font-weight: bold;
  /* 文字色 */
  color: #fff;
  /*垂直方向にの配置位置を設定。
      center = 中央配置
      flex-start = 先頭にまとめる
      flex-end = 末尾にまとめる*/
  align-items: center;
  display: flex;
  /*水平方向に間隔を配置する方法。
      flex-start = 左側から配置する
      flex-end = 右側から配置する
      center = 真ん中に配置する
      space-around = 均等配置して両端に間隔を置く
      space-between = 均等配置してエリアの間に間隔を置く
      space-evenly = 均等配置して各アイテム周りに間隔を置く*/
  justify-content: flex-start;
}



/*チェックボックスを左に寄せない場合は下記を削除してください（質問が短い場合は削除が良いかもしれません）*/
.question_branches ul {
  padding-inline-start: 0 !important;
}

/*スマホ用のフォントサイズを指定できます（指定が特にいらない場合は削除してください）*/
@media screen and (max-width: 415px) {
  .question_branches li {
    /* 文字の大きさ */
    font-size: 15px;
  }
}



/* デフォルトのラジオボタン */
.question_branches input {
  /* 非表示 */
  display: none;
}



/*チェックボックス*/
.question_branches input+span {
  display: inline-block;
  position: relative;
  /* 内側の左余白 */
  padding-left: 2em;
  /* 外側の余白 */
  margin: 0 0.2em 0;
  box-sizing: border-box;
}



/* 回答内容部分 */
.question_branches input+span {
  /* 内側の左余白 */
  padding-left: 2.2em;
}



/* 回答内容がチェックされていない時 */
.question_branches input+span::before {
  position: absolute;
  content: "";
  /* 表示位置（上基準） */
  top: 50%;
  /* 表示位置（左基準） */
  left: 0;
  transform: translateY(-50%);
  /* 背景色 */
  background: transparent;
  /* 線｜太さ｜線種｜色｜ */
  border: 2px solid #fff;
  /* 角丸 */
  border-radius: 2px;
  /* 横幅 */
  width: 1em;
  /* 高さ */
  height: 1em;
  display: block;
}



/*チェック済みのチェックマーク*/
.question_branches input:checked+span::after {
  position: absolute;
  content: "";
  /* 表示位置（上基準） */
  top: 50%;
  /* 表示位置（左基準） */
  left: 0;
  transform: translateY(-50%);
  /* 背景色 */
  background: #fff;
  /* 線｜太さ｜線種｜色｜ */
  border: 2px solid #fff;
  /* 角丸 */
  border-radius: 2px;
  /* 横幅 */
  width: 1em;
  /* 高さ */
  height: 1em;
  display: block;
}



/* 「次へ」ボタン */
.question_branches .nextBtn {
  /* 最大幅 */
  max-width: 466px;
  /* 横幅 */
  width: 100%;
  /* 文字の大きさ */
  font-size: 36px;
  /* 文字の太さ */
  font-weight: bold;
  /* 文字色 */
  color: #0f4980;
  /* 内側の余白 */
  padding: 10px 0;
  /* 対象にカーソルを置いたときに指になる */
  cursor: pointer;
  /* 外側の余白 */
  margin: 20px auto;
  display: block;
  /* 線｜太さ｜線種｜色｜ */
  border: 3px solid #0f4980;
  /* 影｜X方向｜Y方向｜ぼかし｜色｜ */
  box-shadow: 0 5px 0 #0f4980;
  /* 角丸 */
  border-radius: 3px;
  /* 背景色 */
  background: #feff00;
}



/* 「次へ」ボタンdisabled時 */
.question_branches .nextBtn:disabled {
  /* 背景色 */
  background: #fff;
  /* 対象にカーソルを置いたときに指になる */
  cursor: auto;
}



/* 追加コンテンツ非表示 */
.question_branches .addContent.is-hidden {
  /* 非表示 */
  display: none;
}



/* 最終画面のテキスト */
.question_branches .answer__box .text {
  /* 文字の大きさ */
  font-size: 36px;
  /* 文字色 */
  color: #fff;
  /* 影｜X方向｜Y方向｜ぼかし｜色｜ */
  text-shadow: 0 3px 0 #0f4980;
  /* 文字の太さ */
  font-weight: bold;
  /* 文字の位置 */
  text-align: center;
}



/* 最終画面の吹き出し部分 */
.question_branches .answer__box .fukidashi {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
  /* 外側の余白 */
  margin: 20px 0 40px;
  /* 内側の余白 */
  padding: 20px 0;
  /* 背景色 */
  background: #fff;
  /* 線｜太さ｜線種｜色｜ */
  border: 2px solid #0f4980;
  /* 角丸 */
  border-radius: 6px;
  /* 影｜X方向｜Y方向｜ぼかし｜色｜ */
  box-shadow: 0 5px 0 #0f4980;
  /* 文字の大きさ */
  font-size: 20px;
  /* 文字色 */
  color: #0f4980;
  /* 文字の位置 */
  text-align: center;
  /* 文字の太さ */
  font-weight: bold;
  position: relative;
}



/* 最終画面の吹き出し三角部分（影） */
.question_branches .answer__box .fukidashi:before {
  content: '';
  position: absolute;
  /* 表示位置（下基準） */
  bottom: -30px;
  /* 表示位置（左基準） */
  left: 50%;
  transform: translateX(-50%);
  display: inline-block;
  /* 横幅 */
  width: 0;
  /* 高さ */
  height: 0;
  border-style: solid;
  border-width: 30px 23px 0 23px;
  border-color: #0f4980 transparent transparent transparent;
}



/* 最終画面の吹き出し三角部分 */
.question_branches .answer__box .fukidashi:after {
  content: '';
  position: absolute;
  /* 表示位置（下基準） */
  bottom: -20px;
  /* 表示位置（左基準） */
  left: 50%;
  transform: translateX(-50%);
  display: inline-block;
  /* 横幅 */
  width: 0;
  /* 高さ */
  height: 0;
  border-style: solid;
  border-width: 20px 15px 0 15px;
  border-color: #ffffff transparent transparent transparent;
}



/* 最終画面の吹き出し赤文字部分*/
.question_branches .answer__box .fukidashi ._red {
  /* 文字色 */
  color: #b01819;
  /* 文字の大きさ */
  font-size: 28px;
}



/* 最終画面のリンクボタン */
.question_branches .answer__box .linkBtn {
  /* 横幅 */
  width: calc(100% - 20px);
  /* 高さ */
  height: auto;
  /* 文字色 */
  color: #fff;
  display: block;
  /* 文字の太さ */
  font-weight: bold;
  /* 文字の大きさ */
  font-size: 36px;
  /* 内側の余白 */
  padding: 10px 10px;
  text-decoration: none;
  /* 文字の位置 */
  text-align: center;
  /* 背景色 */
  background: linear-gradient(180deg, rgba(87, 220, 25, 1) 0%, rgba(20, 113, 25, 1) 100%);
  /* 角丸 */
  border-radius: 50vw;
  /* 線｜太さ｜線種｜色｜ */
  border: 3px solid #ead291;
  /* 影｜X方向｜Y方向｜ぼかし｜色｜ */
  box-shadow: 0 5px 0 #705413;
  /* 外側の上余白 */
  margin-top: 20px;
}



/* 最終画面のリンクボタンの矢印 */
.question_branches .answer__box .linkBtn .arrow {
  /* 横幅 */
  width: 2rem;
  /* 高さ */
  height: 2rem;
  /* 背景色 */
  background: #fff;
  /* 角丸 */
  border-radius: 1rem;
  display: inline-block;
  /* 外側の左余白 */
  margin-left: 10px;
  position: relative;
}



/* 最終画面のリンクボタンの矢印の三角 */
.question_branches .answer__box .linkBtn .arrow:after {
  content: '';
  display: inline-block;
  /* 横幅 */
  width: 0;
  /* 高さ */
  height: 0;
  border-style: solid;
  border-width: 7.5px 0 7.5px 13.0px;
  border-color: transparent transparent transparent #147119;
  position: absolute;
  /* 表示位置（上基準） */
  top: 50%;
  /* 表示位置（左基準） */
  left: 50%;
  transform: translate(-50%, -50%);
}

.search-link {
  /* 背景色 */
  background: #fff0f5;
  /* 文字色 */
  color: #360000;
  border-radius: 20px;
  padding: 20px;
  /* 最大幅 */
  max-width: 800px;
  margin: 0 auto;
}

.search-link>.title {
  /* タイトル文字色 */
  color: #ff1493;
  font-weight: 700;
  text-align: center;
}

.search-link>.lead {
  /* リード文字色 */
  color: #800000;
  font-weight: 700;
  text-align: center;
}

.search-link .item {
  padding: 20px 0;
  /* ボーダー設定 */
  border-bottom: 1px solid #f5b5d7;
}

.search-link .item:first-of-type {
  padding-top: 0;
}

.search-link .item .title {
  /* 項目タイトル文字サイズ */
  font-size: 110%;
  font-weight: 700;
  margin: 0;
}

.search-link .item .title.inline {
  display: inline-block;
}

.search-link .item .title.inline+.note {
  display: inline-block;
}

.search-link .item .note {
  /* 注釈文字サイズ */
  font-size: 80%;
  margin: 0 0 1em;
}

.search-link .list-check {
  list-style: none;
  margin: 0 0 2em;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
}

.search-link .list-check:last-of-type {
  margin: 0;
}

.search-link .list-check>li {
  margin: 4px 1.5em 4px 0;
}

.search-link .list-check>li label {
  cursor: pointer;
}

.search-link input[type=radio],
.search-link input[type=checkbox] {
  display: none;
}

.search-link input[type=radio]+span,
.search-link input[type=checkbox]+span {
  position: relative;
  display: inline-block;
  padding-left: 1.8em;
  box-sizing: border-box;
}

.search-link input[type=radio]+span::before,
.search-link input[type=checkbox]+span::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 0;
  -webkit-transform: translateY(-50%);
  transform: translateY(-50%);
  width: 1.2em;
  height: 1.2em;
  /* チェックボックスの枠線色 */
  border: 1px solid #ff1493;
  background: #ffffff;
  border-radius: 4px;
  box-sizing: border-box;
}

.search-link input[type=radio]:checked+span::before,
.search-link input[type=checkbox]:checked+span::before {
  content: "";
  /* チェック時の背景色 */
  background: #ff1493;
  box-sizing: border-box;
}

.search-link input[type=radio]:checked+span::after,
.search-link input[type=checkbox]:checked+span::after {
  content: "";
  position: absolute;
  top: calc(50% - 0.1em);
  left: 0.2em;
  width: 0.8em;
  height: 0.5em;
  /* チェックマークの色 */
  border: 3px solid #ffffff;
  border-top: none;
  border-right: none;
  -webkit-transform: translateY(-50%) rotate(-45deg);
  transform: translateY(-50%) rotate(-45deg);
  box-sizing: border-box;
}

.search-link .wrap-submit {
  text-align: center;
  padding: 1.5em 0 1em;
}

.search-link .wrap-submit .submit {
  font-size: 120%;
  display: inline-block;
  padding: 0.4em 1em 0.2em;
  /* 検索ボタン文字色 */
  color: #ffffff;
  /* 検索ボタンステッチ */
  border: #ffffff dashed 1px;
  /* 検索ボタン背景色（外） */
  box-shadow: 0 0 0 0.2em #ff77bb;
  border-radius: 2.5px;
  /* 検索ボタン背景色（中） */
  background-color: #ff77bb;
  text-decoration: none;
  cursor: pointer;
}

.search-link .wrap-submit .submit:hover {
  background: #ff1493;
  box-shadow: 0 0 0 0.2em #ff1493;
}

.search-link .wrap-result {
  /* 結果表示の背景色 */
  background-color: #ffffff;
  margin: 20px auto 0;
  padding: 0;
  text-align: center;
  transition: max-height 0.5s;
  border-radius: 8px;
  position: relative;
  overflow: hidden;
  /* 下記max-heightをautoに変更すると結果表示部分がプレビューに表示されます。
  使用の際は0にしてください。 */
  max-height: 0;
}

.search-link .wrap-result .inner {
  padding: 10px 10px 1.5em;
}

.search-link .wrap-result .inner p {
  margin: 20px 0;
}

.search-link .wrap-result .result {
  font-size: 120%;
  display: inline-block;
  padding: 0.4em 1em 0.2em;
  /* 結果ボタン文字色 */
  color: #ffffff;
  /* 結果ボタンステッチ */
  border: #ffffff dashed 1px;
  /* 結果ボタン背景色（外） */
  box-shadow: 0 0 0 0.2em #ff77bb;
  border-radius: 2.5px;
  /* 結果ボタン背景色（中） */
  background-color: #ff77bb;
  text-decoration: none;
  cursor: pointer;
}

.search-link .wrap-result .result:hover {
  background: #ff1493;
  box-shadow: 0 0 0 0.2em #ff1493;
}

