/* 進捗バー */
.flow-list {
  /* 横幅 */
  max-width: 100%;
  /* 内側の余白|上下|左右| */
  padding: 0;
  /* 枠線|1px|タイプ|色| */
  border: 1px solid #0a5487;
  /* 外側の余白|上|左右|下| */
  margin: 1rem auto 0;
  display: flex;
  justify-content: center;
  align-items: center;
  list-style-type: none;
  overflow: hidden;
}

/* 進捗バーそれぞれ */
.flow-list_item {
  /* 高さ */
  height: 48px;
  /* 背景色 */
  background: #fff;
  /* 文字色 */
  color: #5c5c5c;
  /* 文字の太さ|bold＝太い|normal=普通| */
  font-weight: normal;
  display: flex;
  align-items: center;
  justify-content: space-around;
  flex: 1;
  position: relative;
}

/* 進捗バー - 現在の問題 */
.flow-list_item.current {
  /* 背景色 */
  background: #0a5487;
  /* 文字色 */
  color: #fdd46d;
  /* 文字の太さ|bold＝太い|normal=普通| */
  font-weight: bold;
}

.flow-list_item:not(:last-of-type) {
  border-right: 1px solid #dedede;
}

.flow-list_item:before {
  content: "";
  position: absolute;
  right: -9px;
  top: 50%;
  transform: translateY(-50%);
  width: 0;
  height: 0;
  border-style: solid;
  border-width: 30px 0 30px 10px;
  border-color: transparent transparent transparent #fff;
  z-index: 2;
  margin: 0;
  box-sizing: border-box;
}

.flow-list_item:after {
  content: "";
  position: absolute;
  right: -10px;
  top: 50%;
  transform: translateY(-50%);
  width: 0;
  height: 0;
  border-style: solid;
  border-width: 30px 0 30px 10px;
  border-color: transparent transparent transparent #2297aa;
  z-index: 1;
  box-sizing: border-box;
}

.flow-list_item.current::before {
  border-color: transparent transparent transparent #0a5487;
}

.flow-list_item:last-of-type.current:before {
  border-color: transparent transparent transparent #fff;
}

.flow-list_item:last-of-type::before,
.flow-list_item:last-of-type::after,
.flow-list_item:last-of-type.current::before,
.flow-list_item:last-of-type.current::after {
  content: none;
}

/*全体的な指定*/
.l-qacb {
