}

/* アンケートボックス */
.l-qacb .selecter {
  /*外側の下余白*/
  margin-bottom: 10px;
}

/*アンケートボックス回答部分*/
.l-qacb .selecter>span {
  /*アンケート枠の線。線の種類｜線の太さ｜線の色*/
  border: solid 2px #222;
  display: block;
  /*アンケート枠の内側余白。上下｜左右*/
