/* 全体設定 */
.content__area {
  /* 横幅 */
  width: 460px;
  /* 最大幅 */
  max-width: calc(100% - 40px);
  /* 高さ */
  height: auto;
  /*外側の余白｜上下余白｜左右余白（auto=センタリング）｜*/
  margin: 0 auto;
  /* 文字位置 */
  text-align: center;
  /* 線｜太さ｜線種｜色｜ */
  border: 2px solid #03b6ad;
  /* 角丸 */
  border-radius: 6px;
  /*内側の余白｜上余白｜左右余白｜下余白｜*/
  padding: 0 20px 2em;
}



/* 見出し部分 */
.content__area .head {
  /* 文字色 */
  color: #03b6ad;
  /* 文字の大きさ */
  font-size: 1.2em;
  /* 文字の太さ */
  font-weight: bold;
  /* 外側の上余白 */
  margin-top: 1em;
}



/* テキスト部分 */
.content__area .text {
  /* 文字色 */
  color: #000;
  /* 外側の上余白 */
  margin-top: 0.5em;
  /* 文字の大きさ */
  font-size: 1em;
}

.content__area select {
  /* 横幅 */
  width: 10em;
  /* 最大幅 */
  max-width: 100%;
  /* 内側の余白 */
  padding: 0.5em;
  /* 外側の上余白 */
  margin-top: 0.2em;
  /* 文字の大きさ */
  font-size: 1.1em;
}

.content__area input[type="text"] {
  /* 横幅 */
  width: 6em;
  /* 内側の余白 */
  padding: 0.48em;
  /* 外側の余白 */
  margin: 1em 0.4em;
  /* 文字の大きさ */
  font-size: 1.1em;
}

.content__area button {
  /* 文字の大きさ */
  font-size: 1.2em;
  /* 横幅 */
  width: 60%;
  /* 文字の太さ */
  font-weight: bold;
  box-sizing: border-box;
  /* 文字色 */
  color: #fff;
  /* 背景色 */
  background: #51bbb5;
  /* 線 */
  border: none;
  /* 下線 */
  border-bottom: 5px solid #347774;
  /* 影 */
  box-shadow: 0 3px 5px rgba(0, 0, 0, 0.3);
  /* アニメーションの移り変わり */
  transition: all 0.1s;
  /* 内側の余白 */
  padding: 0.6em 0.6em;
  /* 角丸 */
  border-radius: 0.5em;
  cursor: pointer;
  outline: none;
}

.content__area button:hover {
  /* 外側の上余白 */
  margin-top: 3px;
  /* 下線 */
  border-bottom: 2px solid #347774;
}

.result__box {
  /* 外側の上余白 */
  margin-top: 2em;
}

.result__box .text {
  /* 文字の大きさ */
  font-size: 1em;
  /* 行間 */
  line-height: 1.2;
}

.result__box .text:nth-of-type(2) {
  margin-right: 0.3em;
}

.result__box .text .red {
  /* 文字の大きさ */
  font-size: 1.5em;
  /* 文字の太さ */
  font-weight: bold;
  /* 文字色 */
  color: #ff0000;
  /* 内側の余白 */
  padding: 0 0.2em;
}

/* 全体の設定 */
.check__area {
  /* 横幅 */
  width: 600px;
  /* 最大幅 */
  max-width: 100%;
  /* 高さ */
  height: auto;
  /*外側の余白｜上下余白｜左右余白（auto=センタリング）｜*/
  margin: 0 auto;
}



/* リストの設定 */
.check__area .checkLists {
  /* リストスタイル */
  list-style: none;
  /* 内側の余白 */
  padding: 20px;
  /* 背景色 */
  background: #efefef;
  /* 線｜太さ｜線種｜色｜ */
  border: 2px solid #ccc;

}



/* リスト一行ごとの設定 */
.check__area .checkLists li {
  /* 文字の大きさ */
  font-size: 16px;
  /* 下線｜太さ｜線種｜色｜ */
  border-bottom: 1px dashed #ccc;
  /* 内側の下余白 */
  padding-bottom: 0.5em;
  /* 外側の下余白 */
  margin-bottom: 0.5em;
  position: relative;
}



/* デフォルトのチェックボックス  */
.check__area .checkLists li label input {
  /* 非表示 */
  display: none;
}

.check__area .checkLists li span {
  padding-left: 35px;
  display: inline-block;
}



/* 飾り付けしたチェックボックス （未チェック、チェック済み） */
.check__area .checkLists li label input[type="checkbox"]~span:before,
.check__area .checkLists li label input[type="checkbox"]:checked~span::before {
  content: '';
  position: absolute;
  /* 縦位置（上基準） */
  top: 35%;
  /* 横位置（左基準） */
  left: 0;
  transform: translateY(-50%);
  /* 横幅 */
  width: 25px;
  /* 高さ */
  height: 25px !important;
  display: inline-block;
  /* 背景色 */
  background: #fff;
  /* 線｜太さ｜線種｜色｜ */
  border: 1px solid #bbb;
  /* 角丸 */
  border-radius: 2px;
  /* 右側の余白 */
  margin-right: 0.5em;
}



/* 飾り付けしたチェックボックス （チェック済み） */
.check__area .checkLists li label input[type="checkbox"]:checked~span::before {
  /* チェックマーク */
  background-image: url('/uploads/962f370979b113c124944430d6188b2c6223cf7985f453dbdce9bbf7b56434a1.png');
  /* 背景色 */
  background-color: #fff;
  /* チェックマークの繰り返し */
  background-repeat: no-repeat;
  /* チェックマークの位置 */
  background-position: center;
}



/* チェックの結果（初期：非表示） */
.result__area {
  /* 外側の上余白 */
  margin-top: 2em;
  /* 非表示 */
  display: none;
}



/* 結果のテキストの設定 */
.result__area .resultText {
  /* 文字位置 */
  text-align: center;
  /* 文字の大きさ */
  font-size: 20px;
  /* 文字の太さ */
  font-weight: bold;
}



/* 結果の数字部分 */
.result__area .resultText .num {
  /* 文字色 */
  color: #ff0000;
  /* 文字の大きさ */
  font-size: 40px;
  /* 右側の余白 */
  margin-right: 0.5rem;
}

/*全体の設定*/
.question-reveal {
  /* 横幅の指定 */
  width: 750px;
  max-width: 100%;
  /* 文字サイズ */
  font-size: 16px;
  /*背景色*/
  background-color: #fff;
  /*枠の外側の余白、1番目の値は上下余白、2番目の値は左右余白（auto=センタリング）*/
  margin: 0 auto 1rem;
  /*枠の内側の余白、1番目の値は上下左右余白*/
  padding: 1rem;
  line-height: 1.5;
  box-sizing: border-box;
}

/*設問ごとのブロック*/
.question-reveal .questionArea {
  /*下側の余白*/
  margin-bottom: 50px;
}

/* タイトル */
.question-reveal .title {
  /* 文字サイズ */
  font-size: 2rem;
  /*文字位置*/
  text-align: center;
  /*外側の余白|上|左右auto=自動|下|*/
  margin: 0 auto 1rem;
  /*内側の余白*/
  padding: 0;
}

/*チェックボックスの設定*/
.question-reveal .linkbox {
  /*文字位置*/
  text-align: left;
  /*外側の余白|上下左右|*/
  margin: 0;
  /*内側の余白*/
  padding: 0;
  box-sizing: border-box;
}

.question-reveal input {
  display: none;
}

.question-reveal input+label {
  display: block;
  border: none;
}

/*チェックボックス*/
.question-reveal input+label .btn {
  /*内側の余白、1番目の値は上余白、2番目の値は右余白、3番目の値は下余白、4番目の値は左余白*/
  padding: 0.7rem 0.5rem 0.5rem 3.5rem;
  /*文字の太さ*/
  font-weight: normal;
  /*文字位置*/
  text-align: left;
  /*文字の大きさ*/
  font-size: 1.5rem;
  position: relative;
  display: inline-block;
  box-sizing: border-box;
  cursor: pointer;
}

/*チェックボックスの装飾設定*/
.question-reveal input+label .btn::before {
  /*上位置*/
  top: 0.5rem;
  /*左位置*/
  left: 0.5rem;
  /*横幅*/
  width: 2rem;
  /*高さ*/
  height: 2rem;
  /*枠線|線種|太さ|色|*/
  border: solid 2px #888888;
  /*背景色*/
  background: #ffffff;
  /*枠の角丸*/
  border-radius: 4px;
  content: "";
  display: block;
  position: absolute;
}

.question-reveal input+label .btn:focus {
  outline: none !important;
}

/*チェックマークの設定*/
.question-reveal input[type="checkbox"]:checked+label .btn::after {
  /*上位置*/
  top: 0.7rem;
  /*左位置*/
  left: 0.7rem;
  /*横幅*/
  width: 2rem;
  /*高さ*/
  height: 2rem;
  /*チェックマークの画像*/
  background: url("/uploads/2365fb3bc9fa566945a647f69580bd92d7fd25920b0e14114d8593edff66363a.svg") no-repeat center;
  background-size: contain;
  content: "";
  display: block;
  position: absolute;
}

.question-reveal ::-moz-focus-inner {
  border-color: transparent;
}

/*完了ボタンの設定*/
.question-reveal .send-btn {
  /*外側の余白|上下|左右auto=自動|*/
  margin: 1rem auto;
}

/*完了ボタンの設定*/
.question-reveal .send-btn button {
  /*文字位置*/
  text-align: center;
  /*線の有無*/
  border: none;
  /*文字の大きさ*/
  font-size: 1.2rem;
  /*文字の太さ*/
  font-weight: 700;
  /* 文字色 */
  color: #fff;
  /*外側の余白|上下|左右auto=自動|*/
  margin: 0 auto;
  /*内側の余白*/
  padding: 1em;
  /* 背景色 */
  background-color: #007bff;
  /*角丸*/
  border-radius: 4px;
  position: relative;
  pointer-events: auto;
  display: block;
}

/*完了ボタンのホバー時設定*/
.send-btn button:hover {
  /* 背景色 */
  background-color: #0069d9;
  /* 拡大率 */
  transform: scale(1.2);
  cursor: pointer;
}

/* 完了ボタンを押すと表示される部分 */
.revealarea {
  /*文字の大きさ*/
  font-size: 1.2rem;
  /*文字位置*/
  text-align: left;
  /*外側の余白|上|左右auto=自動|下|*/
  margin: 3rem auto 0;
  /*内側の余白*/
  padding: 0;
  box-sizing: border-box;
}

