.qBox {
  max-width: 100%;
  width: 100%;
  margin: 0 auto 3.6em;
  padding: 0;
  box-sizing: border-box;
}

.qBox ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

.qBox li {
  margin: 0;
  padding: 0;
  font-size: 1.1em;
}

.qBox li:not(:last-child) {
  margin-bottom: 1.8em;
}

.qBox input {
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
  vertical-align: middle;
  cursor: default;
  box-sizing: border-box;
  position: relative;
  padding: 0;
  margin: 0;
  margin-left: 0.4rem;
  margin-right: 0.5rem;
  border: 2px solid #a6a6a6;
  border-radius: 4px;
  display: inline-block;
  width: 21px;
  height: 21px;
}

.qBox input:checked {
  border: none;
  background: #0576ff;
}

.qBox input:checked:before {
  color: #fff;
  content: "";
  display: inline-block;
  position: absolute;
  top: 5px;
  left: 50%;
  transform: translateX(-50%) rotate(-45deg);
  box-sizing: border-box;
  height: 7.5px;
  width: 15px;
  border-left: 3px solid #fff;
  border-bottom: 3px solid #fff;
  margin: 0;
  padding: 0;
}

.qBox input+label {
  line-height: 1.5em;
  display: inline;
  padding: 0;
  margin: 0;
  vertical-align: middle;
}

