}

.choices-chart .wrap-btn > label:nth-of-type(1) {
  /* YESボタンの枠線 */
  border: 3px solid #dc143c;
  /* YESボタンの文字色 */
  color: #dc143c;
}

.choices-chart .wrap-btn > label:nth-of-type(2) {
  /* NOボタンの枠線 */
  border: 3px solid #1e90ff;
  /* NOボタンの文字色 */
  color: #1e90ff;
}

.choices-chart .wrap-item .chart-item {
  display: none;
  position: relative;
  border-top: 3px solid #228b22;
  padding: 80px 0 0;
  margin: 15px 0;
  text-align: center;
}

.choices-chart input[name*='chart-'] {
  display: none;
}

.choices-chart input[name*='chart-']:nth-of-type(1):checked ~ .wrap-btn {
  z-index: 2;
}

.choices-chart input[name*='chart-']:nth-of-type(1):checked ~ .wrap-btn::after {
  content: '';
  display: block;
  width: 40px;
  height: 20px;
  background: linear-gradient(to top right, transparent 49%, #dc143c 50%) top left/50% 100% no-repeat,
    linear-gradient(to top left, transparent 49%, #dc143c 50%) top right/50% 100% no-repeat;
  position: absolute;
  bottom: -80px;
  left: calc(50% - 20px);
}

.choices-chart input[name*='chart-']:nth-of-type(1):checked ~ .wrap-btn > label:nth-of-type(1)::before {
  content: '';
  display: block;
  width: 25%;
  height: 30px;
  border-left: 10px solid #dc143c;
  border-bottom: 10px solid #dc143c;
  position: absolute;
  left: calc(25% - 5px);
  bottom: -40px;
}

.choices-chart input[name*='chart-']:nth-of-type(1):checked ~ .wrap-btn > label:nth-of-type(1)::after {
  content: '';
  display: block;
  width: 25%;
  height: 20px;
  border-right: 10px solid #dc143c;
  position: absolute;
  left: calc(25% - 5px);
  bottom: -60px;
}

.choices-chart input[name*='chart-']:nth-of-type(2):checked ~ .wrap-btn {
  z-index: 2;
}

.choices-chart input[name*='chart-']:nth-of-type(2):checked ~ .wrap-btn::after {
  content: '';
  display: block;
  width: 40px;
  height: 20px;
  background: linear-gradient(to top right, transparent 49%, #1e90ff 50%) top left/50% 100% no-repeat,
    linear-gradient(to top left, transparent 49%, #1e90ff 50%) top right/50% 100% no-repeat;
  position: absolute;
  bottom: -80px;
  right: calc(50% - 20px);
}

.choices-chart input[name*='chart-']:nth-of-type(2):checked ~ .wrap-btn > label:nth-of-type(2)::before {
  content: '';
  display: block;
  width: 25%;
  height: 30px;
  border-right: 10px solid #1e90ff;
  border-bottom: 10px solid #1e90ff;
  position: absolute;
  right: calc(25% - 5px);
  bottom: -40px;
}

.choices-chart input[name*='chart-']:nth-of-type(2):checked ~ .wrap-btn > label:nth-of-type(2)::after {
  content: '';
  display: block;
  width: 25%;
  height: 20px;
  border-left: 10px solid #1e90ff;
  position: absolute;
  right: calc(25% - 5px);
  bottom: -60px;
}

.choices-chart input[name*='chart-']:nth-of-type(1):checked ~ .wrap-item > .chart-item:nth-of-type(1) {
  display: block;
}

.choices-chart input[name*='chart-']:nth-of-type(2):checked ~ .wrap-item > .chart-item:nth-of-type(2) {
  display: block;
}

.choices-chart .link-btn.image {
  border: none;
  border-radius: 0;
  /* リンクボタンの背景色 */
  background-color: none;
  padding: 0;
}

.choices-chart .link-btn.purupuru {
  /*アニメーション名、動きの速さ0.8s（=0.8秒）、動き具合、開始時間5s(=5秒後)、動く回数infinite(=無限 3=3回など)   */
  animation: purupuru 0.8s linear 5s infinite;
}

@keyframes purupuru {
  /*アニメーションの最初の動き*/
  0% {
    /*skew = 傾斜変形する、1番目の値はX軸、2番目に値がある場合はY軸に傾斜変形する
    　　　　9deg = 9度*/
    transform: skew(9deg);
  }

  10% {
    transform: skew(-8deg);
  }

  20% {
    transform: skew(7deg);
  }

  30% {
    transform: skew(-6deg);
  }

  40% {
    transform: skew(5deg);
  }

  50% {
    transform: skew(-4deg);
  }

  60% {
    transform: skew(3deg);
  }

  70% {
    transform: skew(-2deg);
  }

  80% {
    transform: skew(1deg);
  }

  90% {
    transform: skew(0deg);
  }

  /*アニメーションの最後の動き*/
  100% {
    transform: skew(0deg);
  }
}

.is-hidden {
  display: none;
}

.is-show {
  display: block;
  animation: fadeIn 0.3s ease-in forwards;
}

.is-show-slideBottom {
  display: block;
  animation: slideBottom 0.3s ease-in forwards;
}

@keyframes fadeIn {
  0% {
    opacity: 0;
  }

  100% {
    opacity: 1;
  }
}

@keyframes slideBottom {
  0% {
    opacity: 0;
    transform: translateY(20%);
  }

  30% {
    opacity: 0;
  }

  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

