  border-color: #666666 transparent transparent transparent;
  content: "";
  height: 0;
  left: 50%;
  bottom: calc(100% - 14px);
  -webkit-transform: translateX(-50%);
  transform: translateX(-50%);
  width: 0;
}

.range-form .list-form .wrap-tooltip .tooltip::after {
  /* 文字サイズ */
  font-size: 12px;
  /* 文字色 */
  color: #fff;
  /* 背景色 */
  background: #666666;
  border-radius: 3px;
  content: attr(data-tooltip);
  padding: 5px 10px;
  bottom: 100%;
  left: 50%;
  -webkit-transform: translateX(-50%);
  transform: translateX(-50%);
  white-space: pre;
}

.range-form .list-form .wrap-range {
  display: flex;
  align-items: center;
  padding: 0 0 30px 0;
  margin: 30px 0 0 0;
}

.range-form .list-form .wrap-range .btn-minus,
.range-form .list-form .wrap-range .btn-plus {
  position: relative;
  display: inline-block;
  /* +-ボタンの大きさ */
  width: 40px;
  height: 40px;
  /* +-ボタンの文字サイズ */
  font-size: 25px;
  /* +-ボタンの文字色 */
  color: #008000;
  font-weight: 700;
  border-radius: 50%;
  /* +-ボタンの枠色 */
  border: 3px solid #008000;
  /* +-ボタンの背景色 */
  background-color: #fff;
  margin: 0;
  padding: 0;
  flex-shrink: 0;
  line-height: 0;
  cursor: pointer;
  box-sizing: border-box;
}

.range-form .list-form .wrap-range .btn-minus::after,
.range-form .list-form .wrap-range .btn-plus::after {
  content: attr(data-label);
  min-width: 3em;
  font-size: 12px;
  font-weight: normal;
  white-space: nowrap;
  display: block;
  position: absolute;
  top: 50px;
  left: 0;
}

.range-form .list-form .wrap-range .btn-plus::after {
  left: auto;
  right: 0;
}

.range-form .list-form input[type="range"] {
  height: 32px;
  -webkit-appearance: none;
  margin: 0 10px;
  width: 100%;
  background-color: transparent;
}

.range-form .list-form input[type="range"]:focus {
  outline: none;
}

.range-form .list-form input[type="range"]::-webkit-slider-runnable-track {
  width: 100%;
  height: 16px;
  cursor: pointer;
  animate: 0.2s;
  box-shadow: 0px 0px 0px #000000;
  /* スライダー色 */
  background: #bebebe;
  border-radius: 25px;
  border: 1px solid #8a8a8a;
}

.range-form .list-form input[type="range"]::-webkit-slider-thumb {
  box-shadow: 1px 1px 1px #828282;
  border: 1px solid #8a8a8a;
  height: 24px;
  width: 35px;
  border-radius: 6px;
  /* スライダーつまみ色 */
  background: #f5db3a;
  cursor: pointer;
  -webkit-appearance: none;
  margin-top: -5px;
}

.range-form .list-form input[type="range"]:focus::-webkit-slider-runnable-track {
  background: #bebebe;
}

.range-form .list-form input[type="range"]::-moz-range-track {
  width: 100%;
  height: 16px;
  cursor: pointer;
  animate: 0.2s;
  box-shadow: 0px 0px 0px #000000;
  /* スライダー色 */
  background: #bebebe;
  border-radius: 25px;
  border: 1px solid #8a8a8a;
}

.range-form .list-form input[type="range"]::-moz-range-thumb {
  box-shadow: 1px 1px 1px #828282;
  border: 1px solid #8a8a8a;
  height: 24px;
  width: 35px;
  border-radius: 6px;
  /* スライダーつまみ色 */
  background: #f5db3a;
  cursor: pointer;
}

.range-form .list-form input[type="range"]::-ms-track {
  width: 100%;
  height: 16px;
  cursor: pointer;
  animate: 0.2s;
  background: transparent;
  border-color: transparent;
  color: transparent;
}

.range-form .list-form input[type="range"]::-ms-fill-lower {
  /* スライダー色 */
  background: #bebebe;
  border: 1px solid #8a8a8a;
  border-radius: 50px;
