.question__box {
  max-width: 100%;
  height: auto;
  word-break: break-all;
  overflow: hidden;
  /*内側の余白、1番目の値は上側の余白、2番目の値は左右の余白、3番目の値は下の余白*/
  padding: 60px 15px 10px;
  /* 枠線|太さ|タイプ|色| */
  border: 4px solid green;
  /* 角丸の大きさ */
  border-radius: 10px;
  /* 外側の余白|上下|左右auto=自動| */
  margin: 10px auto;
}

.question__content:nth-child(n + 2),
.answer__content {
  /*初期では2番目以降の質問と答えは非表示*/
  display: none;
}

/*質問、答えのタイトル*/
.questionTitle__area .q_title,
.answerTitle__area .a_title {
  /*文字の大きさ*/
  font-size: 60px;
  /*文字の色*/
  color: green;
  /* 文字の太さ */
  font-weight: bold;
  /*文字位置*/
  text-align: center;
  /*行間*/
  line-height: 1;
  /*外側の余白、1番目の値は上の余白、2番目の値は左右の余白、3番目の値は下の余白*/
  margin: 0 0 20px;
}

/*質問、答えの内側の領域*/
.question__inner,
.answer__inner {
  /*背景色*/
  background: #fff;
  /*内側の余白、1番目の値は上下余白、2番目の値は左右余白*/
  padding: 20px 5%;
}

/*質問の説明文、チェックボックの上の線*/
.question__descriptionBox,
.question__checkBox {
  /*1番目の値は線の太さ、2番目の値は線種、3番目の値は線の色*/
  border-top: 1px solid #aaa;
}

/*質問文*/
.question__text {
  /* 文字色 */
  color: #fff;
  /*文字の大きさ*/
  font-size: 26px;
  /* 文字の太さ */
  font-weight: bold;
  /* 文字揃え|center＝中央|right=右|left=左| */
  text-align: center;
  /* 横幅 */
  width: 100%;
  /*内側の余白、1番目の値は上下余白、2番目の値は左右余白*/
  padding: 1em 0.5em;
  /* 背景色 */
  background-color: #008000;
  /* 角丸の半径 */
  border-radius: 20px;
  margin: 0;
  position: relative;
  box-sizing: border-box;
}

/* 吹き出しの三角 */
.question__text:after {
  /* 吹き出しの色 */
  border-color: #008000 transparent transparent transparent;
  border-width: 45px 15px 0 15px;
  border-style: solid;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  position: absolute;
  content: "";
  width: 0;
  height: 0;
}

/*質問の説明文*/
.question__descriptionBox .question__description {
  /*文字の大きさ*/
  font-size: 18px;
  /*内側の余白、1番目の値は上下余白、2番目の値は左右余白*/
  padding: 1em 0;
}

/*チェックボックス*/
.question__checkBox {
  /*内側の余白、1番目の値は上側の余白、2番目の値は左右の余白、3番目の値は下の余白*/
  padding: 20px 0 0;
}

.question__checkBox input {
  display: none;
}

/*チェックボックス隣の回答文*/
.question__checkBox input+label {
  /* 文字の大きさ */
  font-size: 20px;
  /* 文字下の余白 */
  margin-bottom: 15px;
  /* 文字とチェックボックスの間の余白 */
  padding-left: 37px;
  display: block;
  position: relative;
  cursor: pointer;
}

.question__checkBox input+label::before {
  /* チェックボックスの背景色 */
  background-color: #fff;
  /* チェックボックスの縦位置 */
  top: 2px;
  /* チェックボックスの横位置 */
  left: 0;
  /* チェックボックスの横幅 */
  width: 24px;
  /* チェックボックスの縦幅 */
  height: 24px;
  /* チェックボックスの枠の装飾、1番目の値は線の太さ、2番目の値は線種、3番目の値は線の色 */
  border: 1px solid #333;
  content: "";
  display: block;
  position: absolute;
}

.question__checkBox input:checked+label::after {
  /* チェックマークの縦位置 */
  top: 5px;
  /* チェックマークの横位置 */
  left: 8px;
  /* チェックマークの大きさ */
  width: 8px;
  height: 13px;
  /* チェックマークの線の装飾、1番目の値は線の太さ、2番目の値は線種、3番目の値は線の色 */
  border-right: solid 3px #ce666f;
  border-bottom: solid 3px #ce666f;
  content: "";
  display: block;
  -webkit-transform: rotate(45deg);
  transform: rotate(45deg);
  position: absolute;
}

/*答えの説明文*/
.answer__descriptionBox .answer__descriontion {
  /*文字の大きさ*/
  font-size: 18px;
}

.check__area {
  margin-top: 60px;
  display: flex;
  flex-direction: column;
}

.check__area input {
  display: none;
}

/* --チェックボックス横のテキスト装飾-- */
.check__area label,
.check__area input+label {
  display: inline-block;
  position: relative;
  cursor: pointer;
  /* 文字の大きさ */
  font-size: 20px;
  /* 文字下の余白 */
  margin-bottom: 15px;
  /* 文字とチェックボックスの間の余白 */
  padding-left: 37px;
}

/* --チェックボックスの装飾-- */
.check__area label::before,
.check__area input+label::before {
  content: "";
  display: block;
  position: absolute;
  /* チェックボックスの背景色 */
  background-color: #fff;
  /* チェックボックスの縦位置 */
  top: 2px;
  /* チェックボックスの横位置 */
  left: 0;
  /* チェックボックスの横幅 */
  width: 24px;
  /* チェックボックスの縦幅 */
  height: 24px;
  /* チェックボックスの枠の装飾 */
  border: 3px solid #f4d7de;
  /* チェックボックスの枠の角丸 */
  border-radius: 5px;
}

/* --チェックボックス内のチェックマークの装飾-- */
.check__area label:checked:after,
.check__area input:checked+label::after {
  content: "";
  display: block;
  -webkit-transform: rotate(45deg);
  transform: rotate(45deg);
  position: absolute;
  /* チェックマークの縦位置 */
  top: 7px;
  /* チェックマークの横位置 */
  left: 10px;
  /* チェックマークの大きさ */
  width: 8px;
  height: 13px;
  /* チェックマークの線の装飾 */
  border-right: solid 3px #f4d7de;
  border-bottom: solid 3px #f4d7de;
}

/* --選択時に表示されるエリア-- */
.check__area .select__area {
  display: none;
  /* チェックボックス（一番下）と表示されるエリアの余白 */
  margin-top: 10px;
  /* チェックボックス（一番下）と表示されるエリアの余白 */
  margin-bottom: 10px;
}

.check__area input:checked+label+.select__area {
  display: block;
}

.check__area .select__area img {
  max-width: 100%;
}

.q_circles {
  text-align: center;
}

/* Qの下の○ */
.q_circles>span {
  /* 横幅 */
  width: 30px;
  /* 縦幅 */
  height: 30px;
  /* 色 */
  background: yellowgreen;
  border-radius: 50%;
  margin: 0 3px;
  display: inline-block;
}

/* Qの下の○ - 現在地 */
.q_circles>span.current {
  /* 色 */
  background: green;
}

/* 全体設定 */
.heightClac__box {
  /* 横幅 */
  width: 500px;
  /* 最大幅 */
  max-width: 100%;
  /* 高さ */
  height: auto;
  /*外側の余白｜上下余白｜左右余白（auto=センタリング）｜*/
  margin: 0 auto;
}



/* 画像部分 */
.heightCalc__imgArea {
  /* 横幅（画像の横幅にも影響してきます） */
  width: 300px;
  /* 最大幅 */
  max-width: 100%;
  /* 高さ */
  height: auto;
  /*外側の余白｜上下余白｜左右余白（auto=センタリング）｜*/
  margin: 0 auto;
}



/* 画像 */
.heightCalc__imgArea img {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
}



/* フォーム部分 */
.heightCalc__formBox {
  /* 外側の上余白 */
  margin-top: 20px;
}



/* フォームの中部分 */
.heightCalc__form {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
  display: flex;
  /*水平方向に間隔を配置する方法。
  flex-start = 左側から配置する
  flex-end = 右側から配置する
  center = 真ん中に配置する
  space-around = 均等配置して両端に間隔を置く
  space-between = 均等配置してエリアの間に間隔を置く
  space-evenly = 均等配置して各アイテム周りに間隔を置く*/
  justify-content: center;
  /* 子要素が横幅以上になったら改行する */
  flex-wrap: wrap;
  /* 外側の余白 */
  margin: 0;
}



/* フォームのテキスト部分（左側） */
.heightCalc__form dt {
  /* 横幅（全体幅　-　右側余白） */
  width: calc(50% - 1em);
  /*外側の余白｜上余白｜右余白｜下余白｜左余白｜*/
  margin: 0 1em 0.5em 0;
  /* 文字寄せ */
  text-align: right;
  /* 文字の大きさ */
  font-size: 16px;
  /* 文字の高さ（入力欄の高さと揃えると綺麗になります） */
  line-height: 34px;
}



/* フォームの入力部分（右側） */
.heightCalc__form dd {
  /* 横幅 */
  width: 50%;
  /*外側の余白｜上余白｜左右余白｜下余白｜*/
  margin: 0 0 0.5em;
  /* 文字の大きさ */
  font-size: 16px;
}



/* フォームの入力部分共通設定 */
.heightCalc__form dd input,
.heightCalc__form dd select {
  /* 文字の大きさ */
  font-size: 16px;
  /* 文字の高さ（左側のテキストと高さを揃えると綺麗になります） */
  min-height: 34px;
}



/* 「計算」ボタン」部分 */
.heightClac__btn {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
  /* 下線｜太さ｜線種｜色｜ */
  border-bottom: 1px solid #ccc;
}



/* ボタン部分 */
.heightClac__btn button {
  /* ボタンの色 */
  background: #5a73a5;
  /* 文字色 */
  color: #fff;
  /*内側の余白｜上余白｜右余白｜下余白｜左余白｜*/
  padding: 2px 7px 2px calc(7px + 0.5em);
  /* 文字の大きさ */
  font-size: 16px;
  /* ボタンの角丸 */
  border-radius: 4px;
  /* 文字間 */
  letter-spacing: 0.5em;
  /*外側の余白｜上下余白｜左右余白（auto=センタリング）｜*/
  margin: 20px auto 15px;
  display: block;
}



/* 「お子様の予測身長」部分 */
.heightCalc__childBox {
  display: flex;
  /*水平方向に間隔を配置する方法。
  flex-start = 左側から配置する
  flex-end = 右側から配置する
  center = 真ん中に配置する
  space-around = 均等配置して両端に間隔を置く
  space-between = 均等配置してエリアの間に間隔を置く
  space-evenly = 均等配置して各アイテム周りに間隔を置く*/
  justify-content: center;
  /* 外側の上余白 */
