}



/* 「お子様の予測身長」部分（左側/テキスト部分） */
.heightCalc__childBox p {
  /* 外側の余白 */
  margin: 0;
  /* 文字の大きさ */
  font-size: 16px;
  /* 外側の右余白 */
  margin-right: 1em;
