/* ウィジェット全体 */
.quizWrap {
  /* 幅 */
  width: 100%;
  /* 最大幅 */
  max-width: 600px;
  /* 外側の余白|上|左右(auto=自動)|下| */
  margin: 0 auto 30px;
}

/* 見出し */
.quizWrap .quiz_ttl {
  /*文字サイズ*/
  font-size: 2em;
  /*下線の下余白*/
  margin-bottom: 10px;
  /*見出しの下線。線の太さ｜線の種類｜線の色*/
  border-bottom: 1px solid #51bbb5;
  /*下線と見出し間の余白*/
  padding-bottom: 5px;
}

/*見出しスマホ時*/
@media screen and (max-width: 767px) {
  .quizWrap .quiz_ttl {
    /*スマホ時の見出しフォントサイズ */
    font-size: 19px;
    margin: 30px 0 20px;
  }
}

.quizWrap .quiz_img {
  margin-bottom: 20px;
}

.quizWrap .quiz_img img {
  max-width: 100%;
  height: auto;
}

.quizWrap form {
  position: relative;
}

/* 選択肢 */
.quizWrap .choicebox {
  /* 文字サイズ */
  font-size: 20px;
  /*アンケート枠の線。線の種類｜線の太さ｜線の色*/
  border: solid 2px #222;
  /*アンケート枠の内側余白。上下｜左右*/
  padding: 10px 15px;
  /*アンケート内の文字の太さ*/
  font-weight: bold;
  /*アンケートの角丸*/
  border-radius: 5px;
  /*外側の下余白*/
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  position: relative;
}

/* 奇数の選択肢 */
.quizWrap .choicebox:not(.is-changed):hover {
  /*背景色*/
  background: #222;
  /*文字色*/
  color: #fff;
  /*アンケートボックスの影。水平の距離｜垂直の距離｜ぼかし具合｜色の指定*/
  box-shadow: 3px 3px 3px rgba(0, 0, 0, 0.5);
  transition: 200ms;
}

.quizWrap .choicebox.is-changed {
  border: none;
}

.quizWrap .choicebox input {
  appearance: none;
  position: relative;
  box-sizing: border-box;
}

.quizWrap .choicebox input.is-hidden {
  display: none;
}

/* 選択肢の文字 */
.quizWrap .choicebox label {
  /* 内側左の余白 */
  padding: 5px 10px;
  /* 最小の高さ */
  min-height: 50px;
  display: flex;
  align-items: center;
  flex: auto;
  box-sizing: border-box;
}

.quizWrap .choicebox label.is-hidden {
  display: none;
}

.quizWrap .results {
  display: none;
  /* はずれ表記の文字色 */
  color: green;
}

.quizWrap .results.show_result {
  display: block;
}

.quizWrap .correct .results {
  /* はずれ表記の文字色 */
  color: red;
}

.quizWrap .is-clicked .results.show_result {
  padding-left: 1.1em;
  position: relative;
}

