/*全体的な指定*/
.blackwood_box {
  position: relative;
  /*色*/
  color: #222;
  /*外側の余白。上下｜左右*/
  margin: 30px 0;
}



/*見出し*/
.blackwood_box h3 {
  /*文字サイズ*/
  font-size: 2em;
  /*下線の下余白*/
  margin-bottom: 10px;
}

.blackwood_box .results {
  display: none;
}

.blackwood_box .results.show_result {
  display: block;
  /*結果グラフの下余白*/
  margin-bottom: 10px;
}

.blackwood_box .selecter {
  /*アンケートボックス外側の下余白*/
  margin-bottom: 10px;
}



/*アンケートボックス*/
.blackwood_box .selecter>span {
  /*アンケート枠の線。線の種類｜線の太さ｜線の色*/
  border: solid 2px #222;
  display: block;
  /*アンケート枠の内側余白。上下｜左右*/
  padding: 10px 15px;
  /*アンケート内の文字の太さ*/
  font-weight: bold;
  /*アンケートの角丸*/
  border-radius: 5px;
}



/* 結果表示時 */
.show_result .wood-line span {
  /* 投票数の影｜水平の距離｜垂直の距離｜ぼかし具合｜色の指定｜ */
  text-shadow: 1px 1px 5px #000;
}



/*グラフの上にカーソルを乗せた時*/
.blackwood_box .selecter>span:hover {
  /*背景色*/
  background: #222;
  /*文字色*/
  color: #fff;
  /*アンケートボックスの影。水平の距離｜垂直の距離｜ぼかし具合｜色の指定*/
  box-shadow: 3px 3px 3px rgba(0, 0, 0, 0.5);
  transition: 200ms;
}



/*結果グラフ*/
.show_result .wood-line {
  /*結果グラフ背景色*/
  background: #222;
  /*結果グラフの文字色*/
  color: white;
  /*結果グラフの角丸*/
  border-radius: 30px;
  /*結果グラフのアニメーション速度 1s=1秒*/
  transition: 1s;
  /*結果グラフの影。水平の距離｜垂直の距離｜ぼかし具合｜色の指定*/
  box-shadow: 3px 3px 3px rgba(0, 0, 0, 0.4);
  width: 1%;
}

.wood-line span {
  width: 100%;
  text-align: right;
  display: block;
  /*結果グラフの内側余白。上｜右｜下｜左*/
  padding: 5px 10px 5px 0;
  box-sizing: border-box;
  white-space: nowrap;
}

span.result-text {
  /*結果グラフの文字の太さ*/
  font-weight: bold;
}

