/* widget全体の設定 */
.questionChoise__area {
  /* 囲み枠｜太さ｜線種｜色｜ */
  border: 1px solid #333;
  /* 横幅 */
  width: 700px;
  /* 最大幅（全体　-　余白分） */
  max-width: calc(100% - 30px);
  /* 高さ */
  height: auto;
  /*外側の余白｜上下余白｜左右余白（auto=センタリング）｜*/
  margin: 0 auto;
  /*内側の余白｜上下余白｜左右余白｜*/
  padding: 0 15px;
}



/* 質問2個目以降 */
.questionChoise__area .question__box:nth-of-type(n+2) {
  /* 初期：非表示 */
  display: none;
}



/* 質問タイトルを囲む箱 */
.questionChoise__area .question__title {
  /* 下線｜太さ｜線種｜色｜ */
  border-bottom: 2px solid #000;
}



/* 質問タイトル */
.questionChoise__area .question__title .title {
  /* 文字の大きさ */
  font-size: 30px;
