/* widget全体 */
.question__wrap {
  /* 横幅 */
  width: 90%;
  /* 外側の余白|上|左右(auto=自動)|下) */
  margin: 0 auto 0px;
  /* シャドウ  */
  box-shadow: 0 0 8px #b6b6b6;
  max-width: 100%;
}



/* 質問文 */
.question_title {
  /*文字サイズ*/
  font-size: 20px;
  /*文字の色*/
  color: #000;
  /*文字の太さ。太字はbold、標準の太さはnormal*/
  font-weight: normal;
  /*水平方向の字間のスペース*/
  letter-spacing: 0.05em;
  /*背景の色*/
  background: #eeeeee;
  /*要素を横並びにする:flex | 1行にする場合は削除 | */
  display: flex;
  /* 右の線|太さ|スタイル(solid:直線,dotted:点線,double:二重線)|色 */
  border-bottom: 1px solid #ddd;
  position: relative;
}



/* グラデーション四角形 */
.question_title:before {
  /* 横幅 */
  width: 90px;
  /* 縦幅 */
  height: 90px;
  /* グラデーション色設定linear-gradient(開始色, 終了色) */
  background: linear-gradient(#fff, #eeeeee);
  z-index: 0;
  position: absolute;
  content: "";
  top: 0;
  left: 0;
}



/* 三角形 */
.question_title:after {
  position: absolute;
  content: "";
  top: 0;
  left: 0;
  width: 0;
  height: 0;
  border-style: solid;
  border-width: 0 0 90px 90px;
  border-color: transparent transparent #eeeeee transparent;
  z-index: 1;
}



/*Questionの部分*/
.q_num {
  /*文字サイズ*/
  font-size: 16px;
  /* フォント */
  font-family: "Times New Roman", "YuMincho", "Hiragino Mincho ProN",
    "Yu Mincho", "MS PMincho", serif;
  /* 文字スタイル|normal=標準,italic=イタリック体| */
  font-style: italic;
  /*内側の余白|上|下|左|右|*/
  padding: 15px 20px;
  /* 右の線|太さ|スタイル(solid:直線,dotted:点線,double:二重線)|色 */
  border-right: 1px solid #e9e9e9;
  /* 左右揃え|center=中央揃え,flex-start=上揃え,flex-end=下揃え| */
  align-items: center;
  /* 上下揃え|center=中央揃え,flex-start=上揃え,flex-end=下揃え| */
  justify-content: center;
  display: flex;
  flex-direction: column;
  max-width: 100%;
  position: relative;
  z-index: 3;
}



/*数字部分*/
.q_num_hd {
  /*文字サイズ*/
  font-size: 30px;
  /*中央揃え | 左揃え:center | 右揃え:right |*/
  text-align: center;
  /*文字色*/
  color: #d71a46;
  /*文字の太さ | 太い:bold | 普通: normal*/
  font-weight: bold;
  display: block;
  position: relative;
  z-index: 3;
}



/* テキスト部分 */
.q_text_wrap {
  /* フォント */
  font-family: "Times New Roman", "YuMincho", "Hiragino Mincho ProN",
    "Yu Mincho", "MS PMincho", serif;
  /*内側の余白|上|下|左|右|*/
  padding: 15px 5px 15px 20px;
  /* 右の線|太さ|スタイル(solid:直線,dotted:点線,double:二重線)|色 */
  border-left: 1px solid #fff;
  /* 上下揃え|center=中央揃え,flex-start=上揃え,flex-end=下揃え| */
  align-items: center;
  display: flex;
  position: relative;
  z-index: 3;
}

.red {
  /* 文字色 */
  color: #d71a46;
}



/* チェックボックスのブロック */
.checkbox-list {
  /* 外側の余白 |上下左右(auto=自動)| */
  margin: 0;
  /* 内側の余白 |上下|左右(auto=自動)| */
  padding: 20px 30px;
  /* 文字の大きさ */
  font-size: 16px;
  list-style-type: none;
}



/* チェックボックスの各要素 */
.checkbox-list .checkbox {
  /* 外側の余白 |上下左右(auto=自動)| */
  margin-bottom: 15px;
  /* 内側の余白 |上下左右(auto=自動)| */
  padding: 0;
  /* 上下揃え|center=中央揃え,flex-start=上揃え,flex-end=下揃え| */
  align-items: center;
  display: flex;
}



/* チェックボックスのチェック部分 */
.checkbox-list input[type="checkbox"] {
  /* 横幅 */
  width: 26px;
  /* 縦幅 */
  height: 26px;
  /* 線|太さ|スタイル(solid:直線,dotted:点線,double:二重線)|色 */
  border: 2px solid #bababa;
  /* チェック部分と文字との間隔 */
  margin: 0 10px 0 0;
  flex-shrink: 0;
  position: relative;
  appearance: none;
}



/* 選択した時のチェックボックスのチェック部分 */
.checkbox-list input[type="checkbox"]:checked:before {
  /* 横幅 */
  width: 28px;
  /* 縦幅 */
  height: 9px;
  /* 左の線|太さ|スタイル(solid:直線,dotted:点線,double:二重線)|色 */
  border-left: 2px solid #d71a46;
  /* 下の線|太さ|スタイル(solid:直線,dotted:点線,double:二重線)|色 */
  border-bottom: 2px solid #d71a46;
  /* 角度 */
  transform: rotate(-45deg);
  /* 左からの位置 */
  left: 0px;
  /* 上からの位置 */
  top: -2px;
  content: "";
  position: absolute;
}

.checkbox-list label {
  /* 文字サイズ */
  font-size: 26px;
}

.checkbox-list input[type="checkbox"]:checked+label {
  /* 選択した時の文字色 */
  color: #d71a46;
}

/*スマホの場合*/
@media screen and (max-device-width: 767px) {


  /* widget全体 */
  .question__wrap {
    width: 100%;
  }



  /*Questionの部分*/
  .q_num {
    /*内側の余白 上下 | 左右*/
    padding: 15px 10px;
  }



  /* 質問文 */
  .question_title {
    /*文字サイズ*/
    font-size: 16px;
  }



  /* チェックボックスのブロック */
  .checkbox-list {
    /* 内側の余白*/
    padding: 20px;
  }



  /* チェックボックスのチェック部分 */
  .checkbox-list input[type="checkbox"] {
    /* 横幅 */
    width: 20px;
    /*縦幅*/
    height: 20px;
  }



  /* 選択した時のチェックボックスのチェック部分 */
  .checkbox-list input[type="checkbox"]:checked:before {
    /* 横幅 */
    width: 10px;
    /* 縦幅 */
    height: 7px;
    /* 左からの位置 */
    left: 2px;
    /* 上からの位置 */
    top: 1px;
  }

  .checkbox-list label {
    /* 文字サイズ */
    font-size: 16px;
  }
}

.slide-to-line {
  /* 最大幅 */
  max-width: 750px;
  width: 100%;
  margin: 0 auto;
  /* 背景画像の表示領域（上 / 左右 / 下） */
  padding: 20px 5% 100px;
  text-align: center;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
}

.slide-to-line .result .result-in {
  /* リザルト背景色 */
  background-color: #ffffff;
  /* リザルト背景画像（不要な場合は削除） */
  background-image: url(/uploads/b2a43120a9b3ac8e0801d4e9ae6c5efa881a7761649f09dc97fdcfb7457d78f1.png);
  background-repeat: no-repeat;
  /* リザルト背景画像の表示位置 */
  background-position: bottom right;
  /* リザルト背景画像のサイズ*/
  background-size: 80px;
  /* リザルト枠線 */
  border: 4px solid #ed808a;
  width: 90%;
  max-height: 90%;
  position: absolute;
  top: 20%;
  left: 50%;
  -webkit-transform: translate(-50%, -20%);
  transform: translate(-50%, -20%);
  display: flex;
  justify-content: center;
  align-items: center;
  box-sizing: border-box;
}

.slide-to-line>.bg {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100% !important;
  -o-object-fit: cover;
  object-fit: cover;
  z-index: 0;
}

.slide-to-line .title {
  /* タイトル文字色 */
  color: #ffffff;
  /* タイトル文字サイズ */
  font-size: 18px;
  font-weight: 700;
  margin: 10px 0 14px;
  position: relative;
}

.slide-to-line .question {
  /* 質問文文字色 */
  color: #ed808a;
  /* 質問文文字サイズ */
  font-size: 18px;
  font-weight: 700;
  margin: 0 0 14px;
}

.slide-to-line form[name=form-slide-to-line] {
  position: relative;
  overflow: hidden;
}

.slide-to-line .list-slide {
  display: flex;
  width: 100%;
  position: relative;
  left: 0;
  margin: 0 auto;
  padding: 0;
  list-style: none;
  box-sizing: border-box;
  transition: left 0.5s;
}

.slide-to-line .list-slide>li {
  /* スライド部分背景色 */
  background-color: #ffffff;
  padding: 30px 20px 30px 10px !important;
  flex-basis: 100%;
  flex-shrink: 0;
  box-sizing: border-box;
}

.slide-to-line .list-slide>li::before {
  content: none !important;
}

.slide-to-line .list-form-radio {
  margin: 0 auto;
  padding: 0;
  list-style: none;
  box-sizing: border-box;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
}

.slide-to-line .list-form-radio.col-2>li {
  flex-basis: calc(100% / 2);
}

.slide-to-line .list-form-radio.col-3>li {
  flex-basis: calc(100% / 3);
}

.slide-to-line .list-form-radio>li {
  flex-basis: 100%;
  padding: 6px;
  box-sizing: border-box;
}

.slide-to-line .list-form-radio>li label {
