  width: 100%;
}

.slide-to-line .list-form-radio>li label input[type=radio] {
  display: none;
}

.slide-to-line .list-form-radio>li label input[type=radio]+.txt {
  /* ボタン文字色 */
  color: #ffffff;
  /* ボタン背景色 */
  background-color: #f0b0b5;
  border-radius: 6px;
  width: 100%;
  cursor: pointer;
  text-align: center;
  padding: 6px;
  margin: 0;
  text-decoration: none;
  position: relative;
  display: inline-block;
  transition: background-color 0.2s;
  box-sizing: border-box;
}

.slide-to-line .list-form-radio>li label input[type=radio]+.txt:focus {
  outline: none !important;
}

.slide-to-line .list-form-radio>li label input[type=radio]+.txt:hover {
  /* 選択時ボタン背景色 */
  background-color: #ee868f;
}

