  /* 選択時ボタン背景色 */
  background-color: #ee868f;
}

.slide-to-line .list-form-radio>li label ::-moz-focus-inner {
  border-color: transparent;
}

.slide-to-line .nav-slide-to-line {
  display: flex;
  justify-content: center;
  width: 100%;
  margin: 0 auto;
  padding: 10px;
  list-style: none;
  box-sizing: border-box;
  position: relative;
}

.slide-to-line .nav-slide-to-line>li {
  /* ナビゲーション背景色 */
  background-color: transparent;
  /* ナビゲーション枠線 */
  border: 4px solid #ffffff;
  font-weight: bold;
  text-align: center;
  margin: 2px 6px;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  order: 1;
  box-sizing: border-box;
}

.slide-to-line .nav-slide-to-line>li.current {
