 .question_branches {
   /* 枠の下の余白 */
   margin-bottom: 20px;
   /*枠の幅。上｜左右｜下*/
   padding: 15px 15px 15px;
   /*枠の色*/
   background: #5eb6d3;
   box-sizing: border-box;
   max-width: 100%;
 }

 .question_branches img {
   max-width: 100%;
 }

 .question_branches .question_branches__item {
   /*枠内側の余白*/
   padding: 12px;
   /*内側背景色*/
   background: #fff;
   box-sizing: border-box;
 }



 /*チェックしないと表示しないエリア*/
 .question_branches .question_branches__item.is-hidden {
   display: none;
 }



 /*質問文*/
 .question_branches__question {
   /*質問文の文字の太さ*/
   font-weight: 700;
   /*質問文の文字サイズ*/
   font-size: 20px;
   margin-top: 10px;
 }

 .question_branches li {
   /*アンケート行周りの余白*/
   margin: 10px;
   /*行間の高さ*/
   line-height: 2;
   /*文字サイズ*/
   font-size: 1.5rem;
   /*文字色*/
   color: #333;
   align-items: center;
   display: flex;
   justify-content: flex-start;
 }



 /*チェックボックスを左に寄せない場合は下記を削除してください（質問が短い場合は削除がいいかもです）*/
 .question_branches ul {
   padding-inline-start: 0 !important;
 }

 /*スマホ用のフォントサイズを指定できます（指定が特にいらない場合は削除してください）*/
 @media screen and (max-width: 415px) {
   .question_branches li {
     font-size: 15px;
   }
 }

 .question_branches input {
   display: none;
 }



 /*チェックボックス*/
 .question_branches input+span {
   display: inline-block;
   position: relative;
   /*チェックボックスとの余白*/
   padding-left: 2em;
   /*周りの余白。上｜左右｜下*/
   margin: 0 0.2em 0;
   box-sizing: border-box;
 }

 .question_branches input+span {
   /*遷移無しのチェックボックスとの余白*/
   padding-left: 2.2em;
 }

 .question_branches input+span::before {
   position: absolute;
   content: "";
   top: 50%;
   left: 0;
   transform: translateY(-50%);
   /*チェックボックス 背景色*/
   background: #fff;
   /*チェックボックス線。線の太さ｜線の種類｜線の色*/
   border: 2px solid #333;
   /*角を丸くする*/
   border-radius: 2px;
   /*幅*/
   width: 1em;
   /*高さ*/
   height: 1em;
   display: block;
 }



 /*チェック済みのチェックマーク*/
 .question_branches input:checked+span::after {
   position: absolute;
   content: "";
   top: 50%;
   left: 0;
   transform: translateY(-50%) rotate(-45deg);
   width: 1em;
   height: 0.3em;
   margin-top: -0.2em;
   display: block;
   /*チェックマークの色変更は以下２行のカラーコード部分を変更してください*/
   border-left: 4px solid #ff0000;
   border-bottom: 4px solid #ff0000;
 }

/*全体の設定*/
.booleanBoxLink {
  /* 横幅の指定 */
  width: 500px;
  max-width: 100%;
  /*枠の線、1番目の値は太さ、2番目の値は線種、3番目の値は色*/
  border: 6px solid #daa520;
  /*枠の角丸*/
  border-radius: 6px;
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-orient: vertical;
  -webkit-box-direction: normal;
  -ms-flex-direction: column;
  flex-direction: column;
  /*デフォルトの文字位置*/
  text-align: center;
  /*背景色*/
  background-color: #fff;
  /*枠の外側の余白、1番目の値は上下余白、2番目の値は左右余白（auto=センタリング）*/
  margin: 0 auto;
  /*枠の内側の余白、1番目の値は上下左右余白*/
  padding: 10px;
  -webkit-box-sizing: border-box;
  box-sizing: border-box;
}



/*設問ごとのブロック*/
.booleanBoxLink .booleanArea {
  /*下側の余白*/
  margin-bottom: 50px;
}

.booleanBoxLink .title {
  /* タイトルの文字サイズ */
  font-size: 27px;
}

.booleanBoxLink .image {
  margin: 0;
  padding: 0;
}



/*画像の設定*/
.booleanBoxLink .image>img {
  /*横幅*/
  width: 100%;
  max-width: 100%;
}



/*テキストの設定*/
.booleanBoxLink .text {
  /*文字位置*/
  text-align: left;
  /*外側の余白、1番目の値は上下余白、2番目の値は左右余白*/
  margin: 1em 0;
}



/*区切り線の設定*/
.booleanBoxLink hr {
  /*横幅*/
  width: 100%;
  /*線の設定、1番目の値は太さ、2番目の値は線種、3番目の値は色*/
  border-top: 1px solid #ccc;
  /*外側の余白、1番目の値は上余白、2番目の値は右余白、3番目の値は下余白、4番目の値は左余白*/
  margin: 0 0 1em 0;
}



/*チェックボックスの設定*/
.booleanBoxLink .linkbox {
  /*文字位置*/
  text-align: left;
  /*外側の余白*/
  margin: 0;
  /*内側の余白*/
  padding: 0;
  list-style: none;
  -webkit-box-sizing: border-box;
  box-sizing: border-box;
}

.booleanBoxLink input[type="radio"] {
  display: none;
}

.booleanBoxLink input[type="radio"]+label {
  display: block;
}



/*チェックボックスの装飾設定*/
.booleanBoxLink input[type="radio"]+label .btn {
  /*内側の余白、1番目の値は上余白、2番目の値は右余白、3番目の値は下余白、4番目の値は左余白*/
  padding: 0.7rem 0.5rem 0.5rem 3.5rem;
  /*文字の太さ*/
  font-weight: bold;
  text-decoration: none;
  position: relative;
  display: inline-block;
  /*文字位置*/
  text-align: left;
  /*文字の大きさ*/
  font-size: 23px;
  -webkit-box-sizing: border-box;
  box-sizing: border-box;
  cursor: pointer;
}



/*チェックボックスの位置*/
.booleanBoxLink input[type="radio"]+label .btn::before {
  content: "";
  display: block;
  position: absolute;
  /*上位置*/
  top: 0.5rem;
  /*左位置*/
  left: 0.5rem;
  /*横幅*/
  width: 2rem;
  /*高さ*/
  height: 2rem;
  /*枠線、1番目の値は線種、2番目の値は太さ、3番目の値は色*/
  border: solid 2px #888888;
  /*背景色*/
  background: #ffffff;
  /*枠の角丸*/
  border-radius: 4px;
}

.booleanBoxLink input[type="radio"]+label .btn:focus {
  outline: none !important;
}



/*チェックマークの設定*/
.booleanBoxLink input[type="radio"]:checked+label .btn::after {
  content: "";
  display: block;
  position: absolute;
  /*上位置*/
  top: 0.7rem;
  /*左位置*/
  left: 0.7rem;
  /*横幅*/
  width: 2rem;
  /*高さ*/
  height: 2rem;
  /*チェックマークの画像*/
  background: url("/uploads/2365fb3bc9fa566945a647f69580bd92d7fd25920b0e14114d8593edff66363a.svg") no-repeat center;
  background-size: contain;
}

.booleanBoxLink ::-moz-focus-inner {
  border-color: transparent;
}



/*ボタンの設定*/
.booleanBoxLink .send-btn button {
  /*外側の余白、1番目の値は上側の余白、2番目の値は左右余白、3番目の値は下余白*/
  margin: 1em auto 0;
  /*文字位置*/
  text-align: center;
  /*線の有無*/
  border: none;
  position: relative;
  /*文字の大きさ*/
  font-size: 1.2em;
  display: block;
  /*ボタン内側の余白*/
  padding: 1em;
  text-decoration: none;
  /*文字の太さ*/
  font-weight: 700;
  /* リンクボタンの文字色 */
  color: #fff;
  /* リンクボタンの背景色 */
  background-color: #007bff;
  opacity: 1;
  pointer-events: auto;
  /*ボタンの角丸*/
  border-radius: 4px;
  -webkit-transition: background-color 0.2s;
  transition: background-color 0.2s;
}

.booleanBoxLink .send-btn button:disabled {
  /* リンクボタンの非活性時文字色 */
  color: #fff;
  /* リンクボタンの非活性時背景色 */
  background-color: #6c757d;
  opacity: 0.65;
  pointer-events: none;
}

.send-btn button:hover {
  /* リンクボタンのホバー時背景色 */
  background-color: #0069d9;
}

