}

.blackwood_box .results {
  display: none;
}

.blackwood_box .results.show_result {
  display: block;
  /*結果グラフの下余白*/
  margin-bottom: 10px;
}

.blackwood_box .selecter {
  /*アンケートボックス外側の下余白*/
  margin-bottom: 10px;
}



/*アンケートボックス*/
.blackwood_box .selecter>span {
  /*アンケート枠の線。線の種類｜線の太さ｜線の色*/
  border: solid 3px #613d29;
  display: block;
  /*アンケート枠の内側余白。上下｜左右*/
  padding: 10px 15px;
  /*アンケート内の文字の太さ*/
  font-weight: bold;
  /*アンケートの角丸*/
  border-radius: 28px;
}



/*グラフの上にカーソルを乗せた時*/
.blackwood_box .selecter>span:hover {
  /*背景色*/
  background: #f96680;
  /*アンケート枠の線の色*/
  border-color: #fff;
  /*文字色*/
  color: #fff;
  /*アンケートボックスの影。水平の距離｜垂直の距離｜ぼかし具合｜色の指定*/
  box-shadow: 3px 3px 3px rgba(0, 0, 0, 0.5);
  transition: 200ms;
}



/*結果グラフ*/
.show_result .wood-line {
