  background: #f96680;
  /*結果グラフの文字色*/
  color: white;
  /*結果グラフの角丸*/
  border-radius: 30px;
  /*結果グラフのアニメーション速度 1s=1秒*/
  transition: 1s;
  /*結果グラフの影。水平の距離｜垂直の距離｜ぼかし具合｜色の指定*/
  box-shadow: 3px 3px 3px rgba(0, 0, 0, 0.4);
  width: 1%;
}

.wood-line span {
  width: 100%;
  text-align: right;
  display: block;
  /*結果グラフの内側余白。上｜右｜下｜左*/
  padding: 5px 10px 5px 0;
  box-sizing: border-box;
  white-space: nowrap;
}

