/* 全体設定 */
.diagnosis10__box {
  /* 横幅 */
  width: 580px;
  /* 最大幅 */
  max-width: calc(100% - 20px);
  /* 高さ */
  height: auto;
  /* 最小の高さ（waitの画像に合わせて高さを変更してください） */
  min-height: 211px;
  /* 背景色 */
  background: #f0f0f0;
  /* 外側の余白｜上下余白｜左右余白（auto=センタリング）｜ */
  margin: 0 auto;
  /* 内側の余白 */
  padding: 10px;
  position: relative;
}



/* 見出し */
.diagnosis10__headArea {
  /* 下外側の余白 */
  margin-bottom: 15px;
  /* 下内側の余白 */
  padding-left: 10px;
  /* 左線｜線の太さ｜線種｜線の色｜ */
  border-left: 5px solid #e40581;
}

.diagnosis10__headArea .head__text {
  /* 文字の大きさ */
  font-size: 20px;
  /* 文字の太さ */
  font-weight: bold;
  /* 文字の色 */
  color: #595959;
}



/* 質問、wait、診断結果画面 */
.diagnosis10__contentArea {
  /* 背景色 */
  background: #fff;
  /* 横幅 */
  width: calc(100% - 20px);
  /* 高さ */
  height: auto;
  /* 内側の余白 */
  padding: 10px;
}



/* 質問の説明分 */
.diagnosis10__contentArea .description {
  /* 文字の位置 */
  text-align: center;
  /* 外側の余白｜上側｜左右｜下側｜ */
  margin: 10px 0 30px;
}



/* 質問がactiveになった時（表示されている質問） */
.diagnosis10__contentArea .question.active {
  display: flex;
  /* 縦配置の真ん中寄せ */
  align-items: center;
  flex-direction: column;
}



/* 質問の画像 */
.diagnosis10__contentArea .question .question__img {
  /* 下外側の余白 */
  margin-bottom: 20px;
}



/* 質問のボタン */
.diagnosis10__contentArea .question .question__btn {
  display: flex;
  /* センタリング */
  flex-direction: column;
  align-items: center;
}

.diagnosis10__contentArea .question .question__btn input {
  display: none;
}



/* 質問ボタンのデザイン */
.diagnosis10__contentArea .question .question__btn label {
  /* 横幅 */
  width: 400px;
  /* 最大幅 */
  max-width: 95%;
  /* 高さ */
  height: 80px;
  /* 文字の大きさ */
  font-size: 20px;
  /* 囲み線｜線の太さ｜線種｜線の色｜ */
  border: 3px solid #e794c6;
  /* 文字の位置 */
  text-align: center;
  /* 行の高さ（1行の場合はheightと同じ値にしてください） */
  line-height: 80px;
  /* 下外側の余白 */
  margin-bottom: 20px;
  /* hover時の切り替わる速さ */
  transition: 0.2s;
}



/* ボタンにカーソルが触れた時のデザイン */
.diagnosis10__contentArea .question .question__btn label:hover {
  /* 背景色 */
  background: #ffcce6;
}



/* wait画面がactiveになった時 */
.diagnosis10__contentArea .wait.active {
  display: block;
  /* 文字の位置 */
  text-align: center;
  /* 横幅 */
  width: calc(100% - 20px);
  position: absolute;
  /* 上基準の表示位置 */
  top: 10px;
  /* 左基準の表示位置 */
  left: 10px;
  /* 背景色 */
  background: #fff;
}



/* wait画面の表示中のアニメーション（点滅） */
.diagnosis10__contentArea .wait.active img {
  animation: flash 1s linear infinite;
  display: inline-block !important;
}

@keyframes flash {

  0%,
  100% {
    opacity: 1;
  }

  50% {
    opacity: 0;
  }
}



/* 設問表示中の画像部分 */
.diagnosis10__contentArea .illustArea {
  /* 画像の位置 */
  text-align: center;
}



/* 画像の設定 */
.diagnosis10__contentArea .illustArea img {
  /* 横幅 */
  width: 80%;
  /* 最大幅 */
  max-width: 100%;
  /* 高さ */
  height: auto;

  display: inline-block !important;
}

.diagnosis10__contentArea .question,
.diagnosis10__contentArea .wait {
  display: none;
}

.diagnosis10__contentArea .result {
  display: block;
}



/* 診断結果の画像 */
.diagnosis10__contentArea .result img {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
  /* 下外側の余白 */
  margin-bottom: 20px;
}



/* 診断結果のテキスト */
.diagnosis10__contentArea .result .text {
  /* 文字の大きさ */
  font-size: 16px;
  /* 外側の余白 */
  margin: 0;
}

.diagnosis10__contentArea .result.inactive {
  display: none;
}

