 .questionnaire {
   /*枠の幅。上｜左右｜下*/
   padding: 15px 15px 15px;
   /*枠の色*/
   background: #5eb6d3;
 }

 .questionnaire .questionnaire__area {
   /*枠内側の余白*/
   padding: 12px;
   /*内側背景色*/
   background: #fff;
 }



 /*チェックしないと表示しないエリア*/
 .questionnaire .questionnaire__area.hidden {
   display: none;
 }



 /*吹き出し部分（Q1など）*/
 .questionnaire__balloon {
   position: relative;
   display: inline-block;
   /*内側の余白｜上下余白｜左右余白｜*/
   padding: 0 15px;
   /*横幅*/
   width: auto;
   /*横幅の最低値*/
   min-width: 50px;
   /*高さ*/
   height: 30px;
   /*角丸*/
   border-radius: 3px;
   /*文字色*/
   color: #F6F6F6;
   /*行間（heightと同じにしてください）*/
   line-height: 30px;
   /*文字位置*/
   text-align: center;
   /*文字の太さ*/
   font-weight: bold;
   /*背景色*/
   background: #aac5c9;
   z-index: 0;
 }



 /* 吹き出し三角 */
 .questionnaire__balloon::before {
   content: "";
   position: absolute;
   /*位置（下基準）*/
   bottom: -12px;
   /*位置（右基準）*/
   right: 10px;
   /*右側の余白*/
   margin-left: 0;
   display: block;
   width: 0px;
   height: 0px;
   border-style: solid;
   /* 三角形の大きさ */
   border-width: 13px 18px 0 0;
   /* 三角の色 */
   border-color: #aac5c9 transparent transparent transparent;
   z-index: -1;
 }



 /*質問文*/
 .questionnaire__question {
   /*質問文の文字の太さ*/
   font-weight: 700;
   /*質問文の文字サイズ*/
   font-size: 20px;
   margin-top: 10px;
 }

 .questionnaire input {
   display: none;
 }



 /*チェックボックス*/
 a,
 .questionnaire input+span {
   display: inline-block;
   position: relative;
   /*チェックボックスとの余白*/
   padding-left: 2em;
   /*周りの余白。上｜左右｜下*/
   margin: 0 .2em 0;
 }

 .questionnaire input+span {
   /*遷移無しのチェックボックスとの余白*/
   padding-left: 2.2em;
 }

 a::before,
 .questionnaire input+span::before {
   position: absolute;
   content: "";
   top: 50%;
   left: 0;
   transform: translateY(-50%);
   /*チェックボックス 背景色*/
   background: #fff;
   /*チェックボックス線。線の太さ｜線の種類｜線の色*/
   border: 2px solid #333;
   /*角を丸くする*/
   border-radius: 2px;
   /*幅*/
   width: 1em;
   /*高さ*/
   height: 1em;
   display: block;
 }



 /*チェック済みのチェックマーク*/
 .questionnaire input:checked+span::after {
   position: absolute;
   content: "";
   top: 50%;
   left: 0;
   transform: translateY(-50%) rotate(-45deg);
   width: 1em;
   height: .3em;
   margin-top: -.2em;
   display: block;
   /*チェックマークの色変更は以下２行のカラーコード部分を変更してください*/
   border-left: 4px solid #FF0000;
   border-bottom: 4px solid #FF0000;
 }



 /*票部分*/
