   margin: 0 0 0 auto;
 }

.form-indicator {
  /* 最大幅 */
  max-width: 600px;
  width: 100%;
  /* 枠線の色 */
  border: 12px solid #5eb7d5;
  margin: 0 auto;
  position: relative;
  box-sizing: border-box;
}

.form-indicator .view-indicator-wrap {
  /* ゲージ枠線の色 */
  background-color: #000000;
  position: sticky;
  height: 40px;
  bottom: 0;
  margin: 30px auto 0;
  padding: 10px 0;
  border-left: 10px solid #000;
  border-right: 10px solid #000;
  box-sizing: border-box;
}

.form-indicator .view-indicator-wrap::before {
  content: "";
  /* ゲージの色 */
  background: linear-gradient(to right, #fff200, #ff0000);
  width: 100%;
  height: 20px;
  position: absolute;
  top: 10px;
  left: 0;
  z-index: -1;
}

.form-indicator .view-indicator-wrap .view-indicator-tag {
  /* ゲージタイトルの文字色 */
  color: #ffff00;
  font-weight: 700;
  /* ゲージ枠線の色 */
  background-color: #000000;
  padding: 0 5px 0 10px;
  display: inline-block;
  position: relative;
  height: 30px;
  top: -31px;
  left: -10px;
  z-index: -1;
}

.form-indicator .view-indicator-wrap .view-indicator-tag::before {
  content: "";
  position: absolute;
  top: 0;
  right: -20px;
  width: 20px;
  height: 100%;
  /* ゲージ枠線の色 */
  background: linear-gradient(to bottom left, rgba(255, 255, 255, 0) 50%, #000000 55%) no-repeat top left/100% 100%;
}

.form-indicator .view-indicator-wrap .view-indicator {
  /* ゲージの下地色 */
  background-color: #efffff;
  position: absolute;
  width: 100%;
  top: 10px;
  right: 0;
  transition: width 0.5s;
  height: 20px;
  box-sizing: border-box;
}

.form-indicator .tag {
  position: relative;
  display: inline-block;
  /* 吹き出しの背景色 */
  background-color: #5eb7d5;
  /* 吹き出しの文字色 */
  color: #ffffff;
