  font-size: 20px;
  font-weight: 700;
  padding: 0.4em 1.2em;
  border-radius: 1.4em;
  box-sizing: border-box;
}

.form-indicator .tag::before {
  content: "";
  position: absolute;
  bottom: -8px;
  left: 50%;
  border: 5px solid transparent;
  /* 吹き出しの背景色 */
  border-top: 4px solid #5eb7d5;
  border-right: 4px solid #5eb7d5;
}

.form-indicator .title {
