}



/* 設問パンくずリスト */
.questionSlide__box .num__box {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
  /* 下線｜線の太さ｜線種｜色｜ */
  border-bottom: 1px solid #ccc;
  display: flex;
  justify-content: center;
  /* 内側の余白｜上下左右｜ */
  padding: 0;
}

.questionSlide__box .num__box .numList {
  list-style: none;
  /* 外側の余白 */
  margin: 5px 10px 0;
  /* 文字の大きさ */
  font-size: 0.8em;
  /* 文字の色 */
  color: #ccc;
}



/* 数字部分 */
.questionSlide__box .num__box .numList .num {
  /* 文字の大きさ */
  font-size: 1.1em;
}



/* 該当設問がactiveになったら */
.questionSlide__box .num__box .numList.active {
  /* 文字の色 */
  color: #F8791F;
  /* 文字の太さ */
  font-weight: bold;
  position: relative;
}

.questionSlide__box .num__box .numList.active::before {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 0;
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: 2px;
  /* 下線｜線の太さ｜線種｜色｜ */
  border-bottom: 2px solid #f8791f;
}

.questionSlide__box .num__box .numList.active::after {
  content: '';
  position: absolute;
  bottom: -5px;
  left: calc(50% - 5px);
  /* 以下三角形部分 */
  /* 横幅 */
  width: 0;
  /* 高さ */
  height: 0;
  border-style: solid;
  border-width: 5px 5px 0 5px;
  /* 線の色 */
  border-color: #f8791f transparent transparent transparent;
}



/*設問部分*/
.questionSlide__box .slide__area {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
  display: none;
}



/*設問部分がactiveになったら*/
.questionSlide__box .slide__area.active {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  /*スライドアニメーション*/
  animation: slideIn 1s cubic-bezier(0.25, 1, 0.5, 1) 1 forwards;
}

@keyframes slideIn {
  0% {
    transform: translateX(180px);
    /*透明度*/
    opacity: 0;
  }

  100% {
    transform: translateX(0);
  }

  40%,
  100% {
    /*透明度*/
    opacity: 1;
  }
}



/*1問目はスライドアニメーションを設定しない*/
.questionSlide__box .slide__area:first-of-type.active {
  animation: none;
}

.questionSlide__box .slide__area .question__text {
  /* 外側の余白 */
  margin: 0;
  /*質問左側の余白*/
  padding-left: 15px;
  position: relative;
}



/*質問左側の飾り*/
.questionSlide__box .slide__area .question__text::before {
  content: '';
  /* 横幅 */
  width: 10px;
  /* 高さ */
  height: 10px;
  /*角丸*/
  border-radius: 2px;
  /*背景色*/
  background: #f8791f;
  position: absolute;
  left: 0;
  top: 7px;
}

.questionSlide__box .slide__area .question {
  display: none;
}

.questionSlide__box .slide__area .checkList {
  /* 横幅 */
  width: 100%;
  display: block;
  /*上下左右に線を引く｜太さ｜線種｜色｜*/
  border: 3px solid #F7DBBF;
  /*角丸*/
  border-radius: 4px;
  /*下の余白*/
  margin-bottom: 5px;
}

.questionSlide__box .slide__area label {
  box-sizing: border-box;
  cursor: pointer;
  display: inline-block;
  /* 内側の余白　 */
  padding: 5px 30px;
  position: relative;
  /* 横幅 */
  width: 100%;
  /*上下左右に線を引く｜太さ｜線種｜色｜*/
  border: 1px solid #C2C0B2;
  /*背景色*/
  background: #fff;
}



/*チェックボックス */
.questionSlide__box .slide__area label::before {
  /*背景色*/
  background: #fff;
  /*上下左右に線を引く｜太さ｜線種｜色｜*/
  border: 2px solid #f8791f;
  /*角丸*/
  border-radius: 2px;
  content: '';
  display: block;
  /* 高さ */
  height: 16px;
  left: 5px;
  /*上の余白*/
  margin-top: -8px;
  position: absolute;
  top: calc(50% - 2px);
  /* 横幅 */
  width: 16px;
}



/*チェックマーク*/
.questionSlide__box .slide__area label::after {
  border-right: 3px solid #fff;
  /* 下線｜線の太さ｜線種｜色｜ */
  border-bottom: 3px solid #fff;
  content: '';
  display: block;
  /* 高さ */
  height: 9px;
  left: 11px;
  /*上の余白*/
  margin-top: -7px;
  /*透明度*/
  opacity: 0;
  position: absolute;
  top: 50%;
  transform: rotate(45deg);
  /* 横幅 */
  width: 5px;
}



/*チェックを付けたら*/
.questionSlide__box .slide__area .question:checked+label {
  /*背景色*/
  background: #F7F3E7;
  /* 線の色*/
  border-color: #FFF;
}

.questionSlide__box .slide__area .question:checked+label::before {
  /*背景色*/
  background: #f8791f;
}

.questionSlide__box .slide__area .question:checked+label::after {
  /*透明度*/
  opacity: 1;
}

.questionSlide__box .slide__area .btn__box {
  /*上の余白*/
  margin-top: 20px;
  display: flex;
}

.questionSlide__box .slide__area .btn__box .btn {
  /*背景色*/
  background: none;
  /*上下左右に線を引く｜太さ｜線種｜色｜*/
  border: none;
  /* 横幅 */
  width: 140px;
  /* 高さ */
  height: 34px;
  /*ボタンの左側に余白*/
  margin-left: 20px;
}



/*最初に戻るボタン、もしくは最初に次へボタンがある場合は左側に余白を入れない*/
.questionSlide__box .slide__area .btn__box .back__btn:first-of-type,
.questionSlide__box .slide__area .btn__box .next__btn:first-of-type {
  margin-left: 0;
}



/*次へボタン*/
.questionSlide__box .slide__area .btn__box .next__btn {
  background-image: url('/uploads/f0e173cce0c38392a074e0bbd8242404ea38e7f5b7bb872bb39974e785e578fa.png');
}



/*次へボタンが選択できない状態の時*/
.questionSlide__box .slide__area .btn__box .next__btn:disabled {
  background-image: url('/uploads/d15385028475a367042a14a1c19bdb20fb4bda934680389ef9c94dea8badf7dc.png');
}



/*戻るボタン*/
.questionSlide__box .slide__area .btn__box .back__btn {
  background-image: url('/uploads/237dc0f5cbfd076dd61a46ce8e3edff9d51d9504c453c4a067c6e8cb09728cba.png');
}



/*サイトへボタン*/
.questionSlide__box .slide__area .btn__box .link__btn {
  background-image: url('/uploads/f4a68626e9f028092e2fb1b2a55ef012d87e0a628bfa053b5b6c109342ddcfa9.png');
  pointer-events: inherit;
}



/*サイトへボタンが選択できない状態の時*/
.questionSlide__box .slide__area .btn__box .link__btn.disable {
  background-image: url('/uploads/804f53d776ab926159a605cd53872691236fa8cf6644dfa07867e3a4de421046.png');
  pointer-events: none;
}

