/*全体の設定*/
.question__box {
  /*横幅*/
  width: 100%;
  height: auto;
  /*外側の余白　|上下余白|左右余白（auto=センタリング）|*/
  margin: 0 auto;
  max-width: 100%;
}



/*見出しの設定*/
.question__box .head__content {
  /*横幅　（全体- (内側余白 + 飾り線))*/
  width: calc(100% - (0.5em + 5px));
  /*内側の余白　|上余白|右余白|下余白|左余白|*/
  padding: 10px 0 10px 0.5em;
  /*外側の余白*/
  margin: 0;
  /*背景色*/
  background: #efefef;
  /*左の飾り　|太さ|線種|色|*/
  border-left: 5px solid #f44746;
}



/*質問内容の設定*/
.question__box .question__text {
  /*外側の余白　|上余白|左右余白|下余白|*/
  margin: 1.5em 0 0;
}



/*回答ボックスの設定*/
.question__box .question__area {
  /*横幅　(全体 - 内側の左右余白)*/
  width: calc(100% - 2em);
  height: auto;
  max-width: 100%;
  /*外側の余白　|上余白|左右余白（auto=センタリング）|下余白|*/
  margin: 1.5em auto 0;
  /*内側の余白*/
  padding: 1em;
  /*囲み線　|太さ|線種|色|*/
  border: 2px solid #efefef;
}



/*チェックボックスと回答の設定*/
.question__box .question__form {
  display: flex;
  /*複数行にする*/
  flex-wrap: wrap;
  justify-content: center;
}

.question__box input[type="radio"] {
  display: none;
}



/*チェックボックスの装飾*/
.question__box label {
  /*横幅　（全体 - 内側の左右余白）*/
  width: calc(100% - 60px);
  box-sizing: border-box;
  cursor: pointer;
  display: inline-block;
  /*内側の余白　|上下余白|左右余白|*/
  padding: 5px 30px;
  position: relative;
}

.question__box label::before {
  /*チェックボックの中の色*/
  background: #fff;
  /*チェックボックスの枠　|太さ|線種|色|*/
  border: 1px solid #231815;
  content: '';
  display: block;
  /*横幅*/
  width: 16px;
  /*高さ*/
  height: 16px;
