/*widget全体の設定*/
.btnQuestion__box {
  /*横幅*/
  width: 100%;
  /*高さ*/
  height: auto;
  /*外側の余白、1番目の値は上下余白、2番目の余白は左右余白（autoにすることによってセンタリング）*/
  margin: 0 auto;
}



/*ボタンの設定*/
.btnQuestion__box .result {
  /*横幅（全体の横幅からpaddingの左右合計値を引いています）*/
  width: calc(100% - 20px);
  /*高さ*/
  height: auto;
  /*ボタンの色*/
  background: #36d900;
  /*文字の大きさ*/
  font-size: 18px;
  /*文字の太さ*/
  font-weight: bold;
  /*文字の色*/
  color: #fff;
  /*文字の位置*/
  text-align: center;
  display: block;
  /*ボタンの角丸*/
  border-radius: 5px;
  /*行間*/
  line-height: 1.5;
  /*内側の余白、1番目の値は上下余白、2番目の値は左右余白*/
  padding: 10px 10px;
  /*外側の下余白*/
  margin-bottom: 10px;
  /*ボタンの影、1番目の値はx値の位置、2番目の値はy値の位置、3番目の値はぼかし具合、4番目の値は影の色*/
  box-shadow: 3px 3px 2px #ccc;
  cursor: pointer;
  position: relative;
  top: 0;
  /*ボタンhover時のアニメーションの速さ（0.1s=0.1秒）*/
  transition: 0.1s;
}



/*カーソルがボタンに触れた時の設定*/
.btnQuestion__box .result:hover {
  /*ボタンの背景色*/
  background: #2fb534;
  /*ボタンの影*/
  box-shadow: none;
  /*ボタンの位置、押された分（下に移動した分）影が消える仕組み*/
  top: 3px;
}



/*アンケート結果（ボタン未押下時は非表示）*/
.btnQuestion__box .result .rate {
  display: none;
}



/*ボタン押下後、ボタン非表示（アンケート結果はjsから表示設定）*/
.btnQuestion__box.active .result {
  background: none;
  box-shadow: none;
  padding: 0;
  cursor: inherit;
}

.btnQuestion__box.active .result:hover {
  top: 0;
}



/*選択済みの答えにチェックマーク表示*/
.btnQuestion__box.active .result.check .answer {
  position: relative;
  /*左側の余白*/
  padding-left: 1.5em;
}



/*チェックマーク*/
.btnQuestion__box.active .result.check .answer::after {
  content: '';
  display: block;
  position: absolute;
  /*垂直位置（topk基準）*/
  top: .5em;
  /*水平位置（left基準）*/
  left: 0;
  /*横幅*/
  width: 10px;
  /*高さ*/
  height: 5px;
  /*チェックマークの線、1番目の値は太さ、2番目の値は線種、3番目の値は色*/
  border-left: 2px solid #000;
  border-bottom: 2px solid #000;
  /*線を傾ける（-45°）*/
  transform: rotate(-45deg);
}



/*アンケート結果表示時の回答*/
.btnQuestion__box.active .result .answer {
  /*文字色*/
  color: #000;
  /*文字位置*/
  text-align: left;
  display: block;
}



/*棒グラフ*/
.btnQuestion__box.active .result .rate {
  display: block;
  /*背景色*/
  background: #333;
  /*角丸*/
  border-radius: 10vw;
  /*内側の余白、1番目の値は上余白、2番目の値は右余白、3番目の値は下余白、4番目の値は左余白
  ※右余白と左余白の数値を変更する場合はjsの【rateWidth[i].style.width = "calc(" + rate + "% - 15px)";】の「15px」（右余白+左余白）の値も変更してください*/
  padding: 10px 10px 10px 5px;
  /*文字位置*/
  text-align: right;
  /*文字色*/
  color: #fff;
  /*文字の大きさ*/
  font-size: 14px;
  min-width: calc(43px - 15px);
  /*文字の折り返し*/
  white-space: nowrap;
}

