  display: flex;
  flex-direction: column;
}

 .check__area input {
  display: none;
}



/* --チェックボックス横のテキスト装飾-- */
.check__area input+label {
  display: inline-block;
  position: relative;
  cursor: pointer;
  /* 文字の大きさ */
  font-size: 20px;
  /* 文字下の余白 */
  margin-bottom: 15px;
  /* 文字とチェックボックスの間の余白 */
  padding-left: 37px;
}



/* --チェックボックスの装飾-- */
.check__area input+label::before {
  content: "";
  display: block;
  position: absolute;
  /* チェックボックスの背景色 */
  background-color: #fff;
  /* チェックボックスの縦位置 */
  top: 2px;
  /* チェックボックスの横位置 */
  left: 0;
  /* チェックボックスの横幅 */
  width: 24px;
  /* チェックボックスの縦幅 */
  height: 24px;
  /* チェックボックスの枠の装飾 */
  border: 3px solid #f4d7de;
  /* チェックボックスの枠の角丸 */
  border-radius: 5px;
}



/* --チェックボックス内のチェックマークの装飾-- */
.check__area input:checked+label::after {
  content: "";
  display: block;
  -webkit-transform: rotate(45deg);
  transform: rotate(45deg);
  position: absolute;
  /* チェックマークの縦位置 */
  top: 7px;
  /* チェックマークの横位置 */
  left: 10px;
  /* チェックマークの大きさ */
  width: 8px;
  height: 13px;
  /* チェックマークの線の装飾 */
  border-right: solid 3px #f4d7de;
  border-bottom: solid 3px #f4d7de;
}



/* --選択時に表示されるエリア-- */
.check__area .select__area {
  display: none;
  /* チェックボックス（一番下）と表示されるエリアの余白 */
  margin-top: 40px;
}

