/*ローダー*/
.loader {
  margin: 100px auto;
  font-size: 25px;
  width: 1em;
  height: 1em;
  border-radius: 50%;
  position: relative;
  text-indent: -9999em;
  animation: load5 1.1s infinite ease;
  transform: translateZ(0);
}

.loader_wrap {
  padding: 2px;
  position: absolute;
  top: 0;
  left: 0;
  opacity: 0.5;
  right: 0;
  bottom: 0;
  display: none;
  align-items: center;
}

.loader_wrap.open {
  display: flex;
}

/*-- Q1~Q4部分 --*/
.checkbox__wrap .question__badge {
  max-width: 100%;
  margin: 0 auto;
  padding: 0;
  list-style: none;
  display: flex;
  justify-content: center;
  align-items: flex-start;
}

.checkbox__wrap .question__badge .question {
  position: relative;
  width: 90px;
  height: 90px;
  border-radius: 50%;
  line-height: 90px;
  margin-right: 40px;
  /* 通常時の背景色 */
  background: #d2d2d2;
}

.checkbox__wrap .question__badge .question {
  text-align: center;
  font-size: 40px;
  font-weight: bold;
  /* 通常時の文字色 */
  color: #817f80;
}

.checkbox__wrap .question__badge .question:last-of-type {
  margin-right: 0;
}

.checkbox__wrap .question__badge .question.is-active {
  /* is-active時の背景色 */
  background: #fb9392;
  /* is-active時の文字色 */
  color: #fff;
}

.checkbox__wrap .question__badge .question::after {
  content: "";
  background: url('/uploads/2accf980d4782ec4bb80ecfc682cbb0f0daffc0fd94c5183812967a23660af78.png') no-repeat;
  width: 32px;
  height: 32px;
  display: inline-block;
  position: absolute;
  top: calc(50% - 12px);
  right: -40px;
}

.checkbox__wrap .question__badge .question:last-of-type::after {
  content: none;
}



/*-- 質問文部分（タイトル） --*/
.checkbox__wrap .checkbox__title {
  margin: 20px;
  padding: 0;
  /* 質問文のフォントサイズ */
  font-size: 72px;
  /* 質問文の太さ */
  font-weight: normal;
  /* 質問文のテキスト配置 */
  text-align: center;
}



/*-- 画像部分 --*/
.checkbox__wrap .checkbox__image {
  max-width: 100%;
  margin-bottom: 20px;
}

.checkbox__wrap .checkbox__image img {
  margin: 0 auto;
  display: block;
  max-width: 100%;
}



/*-- バッジ部分 --*/
.checkbox__wrap .badge {
  /* 右寄せ */
  text-align: right;
  /* バッジとチェックボックスブロックとの間隔 */
  margin-bottom: 10px;
}

.checkbox__wrap .badge span {
  display: inline-block;
  padding: 0 10px;
  /* バッジの背景色 */
  background: #f5b5d5;
  /* バッジの文字色 */
  color: #fff;
  /* バッジの文字の大きさ */
  font-size: 20px;
}



/*-- チェックボックスのブロック --*/
.checkbox__wrap .checkbox-list {
  padding: 10px 5%;
  /* チェックボックスのブロックを囲う線 */
  border: 1px solid #ccc;
  /* チェックボックスの文字の大きさ */
  font-size: 24px;
}

.checkbox__wrap .checkbox-list label input {
  display: none;
}



/*チェックボックス各行*/
.checkbox__wrap .checkbox-list .checkbox {
  /*下余白*/
  padding-bottom: 10px;
}



/*--チェックボックスと文--*/
.checkbox__wrap .checkbox-list label input+span {
  display: inline-block;
  position: relative;
  /*周りの余白。上｜左右｜下*/
  margin: 0 .2em 0;
  /*チェックボックスとの余白*/
  padding-left: 1.5em;
  cursor: pointer;
}



/*--チェックボックス-- */
.checkbox__wrap .checkbox-list label input+span::before {
  position: absolute;
  content: "";
  /*チェックボックス 背景色*/
  background: #fff;
  /*チェックボックス線。太さ｜種類｜色*/
  border: 2px solid #333;
  /*角を丸くする*/
  border-radius: 2px;
  /*幅*/
  width: 1em;
  /*高さ*/
  height: 1em;
  display: block;
  top: 50%;
  left: 0;
  transform: translateY(-50%);
}



/*--チェック済みのチェックマーク--*/
.checkbox__wrap .checkbox-list label input:checked+span::after {
  position: absolute;
  content: "";
  /*チェックマーク右側サイズ*/
  width: .8em;
  /*チェックマーク左側サイズ*/
  height: .2em;
  /*チェックマーク上余白*/
  margin-top: -0.1em;
  /*チェックマーク左余白*/
  margin-left: 0.1em;
  display: block;
  /*チェックマークの色変更は以下２行のカラーコード部分を変更してください*/
  border-left: 4px solid #FF0000;
  border-bottom: 4px solid #FF0000;
  top: 50%;
  left: 0;
  transform: translateY(-50%) rotate(-45deg);
}

/*タブレット・スマホの場合*/
@media screen and (max-width: 768px) {
  .checkbox__wrap .question__badge .question {
    width: 50px;
    height: 50px;
    margin-right: 30px;
    line-height: 50px;
  }

  .checkbox__wrap .question__badge .question {
    font-size: 28px;
  }

  .checkbox__wrap .question__badge .question::after {
    background-size: 50%;
    top: calc(50% - 7px);
  }
}

