  padding-bottom: 0.5em;
  /*下線の下余白*/
  margin-bottom: 1em;
  /*文字の太さ*/
  font-weight: bold;
  /*文字の色*/
  color: #333;
  /*下線。種類｜太さ｜色*/
  border-bottom: solid 2px #139e5d;
}

.qBox ul {
  list-style: none;
  /*項目エリアの余白。上下｜左右*/
  padding: 0 0.5em;
}


/*各選択項目*/
.qBox li {
  /*文字サイズ*/
  font-size: 1.1em;
  /*各行下余白*/
  margin-bottom: 1.8em;
  position: relative;
}

.qBox input {
  position: absolute;
  opacity: 0;
}

.qBox span {
  /*項目文の左側余白*/
  padding-left: 1.8em;
}

/*チェックボックス */
.qBox input+span {
  display: block;
  /*画像*/
  background: url(/uploads/b7ad84af552b78b2458a246322b64eeaedca03207ce07fc9df9e3cad228ec317.gif) 0 0 no-repeat;
  /*画像サイズ*/
  background-size: 1.5em;
  /*行間調整*/
  line-height: 1.5em;
}

/*チェックした時*/
.qBox input:checked+span {
  /*文字の太さ*/
  font-weight: bold;
  /*文字の色*/
  color: #fc5356;
  /*チェックマーク画像*/
  background: url(/uploads/fe341e9cf3aada72cb257fe256f51831c610eebbe5fd5beef7cfd7ef2ed812e1.gif) 0 0 no-repeat;
  /*画像サイズ*/
  background-size: 1.5em;
}

.outline {
  /*外枠の幅*/
  padding: 20px;
  /*外枠のグラデーション。上｜下*/
  background: linear-gradient(#B0DEF6, #94C8F8);
}

.container {
  /*アンケート内背景色*/
  background-color: white;
}

.img-wrapper {
  /*画像横幅*/
  width: 30%;
}

.main {
  /*文章エリア余白。上｜左右｜下*/
  padding: 10px 20px 50px;
}

.title>h3 {
  /*タイトル文字サイズ*/
  font-size: 20px;
  /*文字の太さ。太字はbold、標準の太さはnormal*/
  font-weight: normal;
}

.title>hr {
  /*タイトル下線。太さ｜種類｜色*/
  border-top: 1px dashed #000;
}



/*複数選択可の部分*/
.notice {
  /*文字を右寄せ*/
  text-align: right;
  /*文字色*/
  color: red;
}


/*選択項目エリア*/
.questions {
  /*上余白*/
  margin-top: 10px;
  /*文字サイズ*/
  font-size: 30px;
}

.questions li {
  /*選択項目各行の余白。上下｜左右*/
  padding: 20px 0;
}

input[type="checkbox"] {
  display: none;
}

label {
  position: relative;
}



/*各設問*/
input[type="checkbox"]+span {
  display: block;
  position: relative;
  /*左側余白*/
  padding-left: 35px;
  /*各行の下余白*/
  margin-bottom: 22px;
  /*文字サイズ*/
  font-size: 20px;
  /*文字行間調整*/
  line-height: 1.5;
  /*文字の太さ。太字はbold、標準の太さはnormal*/
  font-weight: bold;
  cursor: pointer;
}



/*チェックボックス */
input[type="checkbox"]+span:before {
  content: '';
  display: block;
  /*横幅*/
  width: 20px;
  /*縦幅*/
  height: 20px;
  /*枠線。太さ｜種類｜色*/
  border: 1px solid #000;
  position: absolute;
  /*左からの位置*/
  left: 0;
  /*上からの位置*/
  top: 3px;
  /*透明度　0=透明*/
  opacity: 0.6;
  /*クリックした時の変化速度。1=1秒*/
  transition: all 0.12s;
}



/*チェックした時のマーク*/
input[type="checkbox"]:checked+span:before {
  /*幅*/
  width: 10px;
  /*上からの位置*/
  top: 0;
  /*左からの位置*/
  left: 5px;
  /*チェックマーク右側の色*/
  border-right-color: #6cc0e5;
  /*チェックマーク左側の色*/
  border-bottom-color: #6cc0e5;
  /*透明度　0=透明*/
  opacity: 1;
  /*45度回転*/
  transform: rotate(45deg);
  border-top-color: transparent;
  border-left-color: transparent;
}
